// ─── Frontend Principal ───────────────────────────────────────────────────────
// Rota raiz → onboarding (splash + login) como app nativo
// ─── API: trocar Google OAuth code por id_token via PKCE ─────────────────────
// O frontend envia { code, code_verifier, redirect_uri }
// O servidor troca pelo Google Token Endpoint e retorna { id_token }
app.post('/api/auth/google-code', async (c) => {
  try {
    const { code, code_verifier, redirect_uri } = await c.req.json() as any
    if (!code || !code_verifier) return c.json({ error: 'Parâmetros faltando' }, 400)

    const clientId = '1078426960222-viiv45tf4i508rlvj53202h6kda8ga9b.apps.googleusercontent.com'
    // Client secret do OAuth Web Client (necessário para troca de code)
    // Configure via: npx wrangler secret put GOOGLE_CLIENT_SECRET --config wrangler-worker.jsonc
    const clientSecret = (c.env as any)?.GOOGLE_CLIENT_SECRET as string || ''

    if (!clientSecret) {
      return c.json({ error: 'client_secret_missing', detail: 'GOOGLE_CLIENT_SECRET não configurado no servidor. Configure via Cloudflare Secrets.' }, 503)
    }

    const finalRedirectUri = redirect_uri || 'https://rotaposto.com.br/auth/google/callback'
    const body = new URLSearchParams({
      code,
      client_id: clientId,
      client_secret: clientSecret,
      redirect_uri: finalRedirectUri,
      grant_type: 'authorization_code',
      code_verifier,
    })

    const resp = await fetch('https://oauth2.googleapis.com/token', {
      method: 'POST',
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
      body: body.toString(),
    })
    const data = await resp.json() as any
    if (!resp.ok || !data.id_token) {
      return c.json({ error: data.error || 'Falha ao obter token', detail: data.error_description }, 400)
    }
    return c.json({ id_token: data.id_token })
  } catch (e) {
    return c.json({ error: String(e) }, 500)
  }
})

// ─── One Tap / FedCM — valida JWT diretamente (sem troca de code) ────────────
// O GSI envia o id_token (JWT) direto do browser → validamos a assinatura Google
// e retornamos { ok, user } para o frontend completar o login sem redirect.
app.post('/api/auth/google-onetap', async (c) => {
  try {
    const { idToken } = await c.req.json() as any
    if (!idToken) return c.json({ ok: false, erro: 'idToken ausente' }, 400)

    const CLIENT_ID = '1078426960222-viiv45tf4i508rlvj53202h6kda8ga9b.apps.googleusercontent.com'

    // Validar JWT junto ao Google tokeninfo (simples e sem necessidade de chave privada)
    const verifyResp = await fetch(
      'https://oauth2.googleapis.com/tokeninfo?id_token=' + encodeURIComponent(idToken)
    )
    const info = await verifyResp.json() as any

    if (!verifyResp.ok || info.error) {
      return c.json({ ok: false, erro: 'Token inválido: ' + (info.error_description || info.error) }, 401)
    }
    // Garantir que o token foi emitido para nosso client_id
    if (info.aud !== CLIENT_ID) {
      return c.json({ ok: false, erro: 'Token não pertence a este app' }, 401)
    }

    const { sub: uid, email, name, picture: photo } = info

    // Criar/atualizar sessão no KV (mesmo padrão de /api/usuario/sessao)
    const kv = getKV(c.env as any)
    if (kv) {
      const sessionToken = crypto.randomUUID()
      await kv.put(`session:${uid}`, JSON.stringify({
        token: sessionToken, uid, createdAt: Date.now()
      }), { expirationTtl: 60 * 60 * 24 * 30 })

      // Upsert perfil
      let perfil: any = {}
      try { const r = await kv.get(`profile:${uid}`); if (r) perfil = JSON.parse(r) } catch {}
      await kv.put(`profile:${uid}`, JSON.stringify({
        ...perfil, uid, name: name || perfil.name || '',
        email: email || perfil.email || '',
        photo: photo || perfil.photo || '',
        provider: 'google', ultimoLogin: Date.now(),
        criadoEm: perfil.criadoEm || Date.now(),
      }), { expirationTtl: 60 * 60 * 24 * 400 })
    }

    return c.json({
      ok: true,
      user: { uid, email, nome: name, foto: photo, provider: 'google' }
    })
  } catch (e) {
    return c.json({ ok: false, erro: String(e) }, 500)
  }
})

// ─── Callback OAuth Google (WebView nativo) ──────────────────────────────────
// Google redireciona para cá após autenticação com ?code=xxx&state=yyy
// Esta página lê o code, busca o id_token via /api/auth/google-code,
// faz signInWithCredential e redireciona para /app
app.get('/auth/google/callback', (c) => {
  const firebaseScripts = getFirebaseAuthScripts()
  return c.html(`<!DOCTYPE html>
<html lang="pt-BR">
<head>
  <meta charset="UTF-8"/>
  <meta name="viewport" content="width=device-width, initial-scale=1.0"/>
  <title>RotaPosto – Entrando...</title>
  <style>
    body{margin:0;display:flex;align-items:center;justify-content:center;min-height:100vh;background:#fff;font-family:sans-serif;flex-direction:column;gap:16px;}
    .spinner{width:40px;height:40px;border:4px solid #FFE0B2;border-top-color:#FF6D00;border-radius:50%;animation:spin .8s linear infinite;}
    @keyframes spin{to{transform:rotate(360deg);}}
    p{color:#666;font-size:14px;}
    .erro{color:#E53935;font-size:13px;text-align:center;padding:0 24px;max-width:320px;}
  </style>
  ${firebaseScripts}
</head>
<body>
  <div class="spinner"></div>
  <p>Finalizando login...</p>
  <div class="erro" id="erro" style="display:none"></div>
  <script>
    function mostrarErro(msg) {
      document.querySelector('.spinner').style.display = 'none';
      document.querySelector('p').style.display = 'none';
      var el = document.getElementById('erro');
      el.textContent = msg;
      el.style.display = 'block';
      setTimeout(function(){ window.location.href = '/'; }, 5000);
    }

    // Ler query params (Google envia code= e state= aqui no fluxo PKCE)
    var queryParams = {};
    window.location.search.substring(1).split('&').forEach(function(part) {
      var eq = part.indexOf('=');
      if (eq > 0) queryParams[decodeURIComponent(part.substring(0,eq))] = decodeURIComponent(part.substring(eq+1));
    });

    // Ler fragment (fluxo implícito legado: id_token no #)
    var fragment = window.location.hash.substring(1);
    var fragParams = {};
    fragment.split('&').forEach(function(part) {
      var eq = part.indexOf('=');
      if (eq > 0) fragParams[decodeURIComponent(part.substring(0,eq))] = decodeURIComponent(part.substring(eq+1));
    });

    var erro = queryParams['error'] || fragParams['error'];
    var code  = queryParams['code'];      // Fluxo PKCE (Authorization Code)
    var state = queryParams['state'];
    var idTokenFrag = fragParams['id_token']; // Fluxo implícito legado

    // Verificar erro do Google
    if (erro) {
      mostrarErro('Google recusou: ' + erro);
    }
    // ── Fluxo PKCE: Google retornou code ──────────────────────────────────────
    else if (code) {
      // Verificar state CSRF
      var savedState = localStorage.getItem('google_pkce_state');
      if (savedState && state !== savedState) {
        mostrarErro('Erro de segurança (state inválido). Tente novamente.');
      } else {
        var codeVerifier = localStorage.getItem('google_pkce_verifier');
        localStorage.removeItem('google_pkce_verifier');
        localStorage.removeItem('google_pkce_state');
        localStorage.removeItem('google_pkce_nonce');

        if (!codeVerifier) {
          mostrarErro('Sessão expirada. Tente fazer login novamente.');
        } else {
          // Trocar code + code_verifier por id_token via nosso servidor (evita expor client_secret)
          fetch('/api/auth/google-code', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              code: code,
              code_verifier: codeVerifier,
              redirect_uri: 'https://rotaposto.com.br/auth/google/callback'
            })
          })
          .then(function(r) { return r.json(); })
          .then(function(data) {
            if (data.error === 'client_secret_missing') {
              // GOOGLE_CLIENT_SECRET não está configurado — mostrar instrução
              mostrarErro('Configuração pendente: entre em contato com o suporte. (client_secret não configurado)');
              return;
            }
            if (data.error) { mostrarErro('Erro ao trocar código: ' + data.error + (data.detail ? ' — ' + data.detail : '')); return; }
            _finalizarLoginComIdToken(data.id_token);
          })
          .catch(function(e) { mostrarErro('Erro de rede: ' + e.message); });
        }
      }
    }
    // ── Fluxo implícito legado: id_token no fragment ──────────────────────────
    else if (idTokenFrag) {
      localStorage.removeItem('google_oauth_nonce');
      _finalizarLoginComIdToken(idTokenFrag);
    }
    else {
      mostrarErro('Resposta inesperada do Google. Tente novamente.');
    }

    // Fazer signInWithCredential Firebase com o id_token e redirecionar para /app
    function _finalizarLoginComIdToken(idToken) {
      var tentativas = 0;
      var t = setInterval(function() {
        tentativas++;
        if (window._fbAuth && window._fbSignInWithCredential && window._fbGoogleAuthProvider) {
          clearInterval(t);
          var cred = window._fbGoogleAuthProvider.credential(idToken);
          window._fbSignInWithCredential(window._fbAuth, cred)
            .then(function(result) {
              var user = result.user;
              var userData = {
                uid: user.uid,
                name: user.displayName || (user.email||'').split('@')[0] || 'Usuário',
                email: user.email || '',
                photo: user.photoURL || '',
                provider: 'google.com'
              };
              localStorage.setItem('rp_user', JSON.stringify(userData));
              fetch('/api/auth/session', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ uid: user.uid, name: userData.name, email: userData.email, photo: userData.photo })
              }).catch(function(){}).finally(function() {
                var v = localStorage.getItem('rp_vehicle');
                if (v) { window.location.href = '/app'; return; }
                fetch('/api/usuario/veiculo/' + user.uid)
                  .then(function(r){ return r.json(); })
                  .then(function(d) {
                    if (d.veiculo) localStorage.setItem('rp_vehicle', JSON.stringify(d.veiculo));
                    window.location.href = '/app';
                  })
                  .catch(function(){ window.location.href = '/app'; });
              });
            })
            .catch(function(err){ mostrarErro('Erro Firebase: ' + (err.code||err.message)); });
        } else if (tentativas > 80) {
          clearInterval(t);
          mostrarErro('Firebase não carregou. Tente novamente.');
        }
      }, 100);
    }
  </script>
</body>
</html>`)
})

app.get('/', (c) => {
  // Redirecionar domínio antigo para rotaposto.com.br
  const host = c.req.header('host') || ''
  if (host.includes('pages.dev') || host.includes('gensparksite.com')) {
    return c.redirect('https://rotaposto.com.br/', 301)
  }
  const firebaseScripts = getFirebaseAuthScripts()
  return c.html(getLandingOnboardingHTML(firebaseScripts))
})

