// ═══════════════════════════════════════════════════════════════════════════════
// CONFIG DE PAGAMENTO — gateway ativo, métodos, credenciais
// KV key: "admin:config_pagamento"
// ═══════════════════════════════════════════════════════════════════════════════

const PAGAMENTO_CONFIG_KEY = 'admin:config_pagamento'

interface ConfigPagamento {
  gateway: 'woovi' | 'mercadopago' | 'asaas'  // gateway ativo
  pixAtivo: boolean
  cartaoAtivo: boolean
  // Credenciais salvas pelo admin (fallback para env secrets)
  wooviAppId?: string      // App ID / API Key da Woovi/OpenPix
  mpAccessToken?: string   // Access Token do Mercado Pago (APP_USR-...)
  mpPublicKey?: string     // Public Key do Mercado Pago (APP_USR-...)
  mpClientId?: string      // Client ID do Mercado Pago (numérico)
  mpClientSecret?: string  // Client Secret do Mercado Pago
  asaasApiKey?: string     // API Key do Asaas ($aact_prod_...)
  // Status: definido ao testar conexão
  statusWoovi?:   'ok' | 'erro' | 'nao_configurado'
  statusMP?:      'ok' | 'erro' | 'nao_configurado'
  statusAsaas?:   'ok' | 'erro' | 'nao_configurado'
  atualizadoEm?: number
}

async function getConfigPagamento(kv: KVNamespace): Promise<ConfigPagamento> {
  try {
    const raw = await kv.get(PAGAMENTO_CONFIG_KEY)
    if (raw) return JSON.parse(raw) as ConfigPagamento
  } catch {}
  return { gateway: 'woovi', pixAtivo: true, cartaoAtivo: true }
}

// GET /api/admin/config/pagamento
app.get('/api/admin/config/pagamento', async (c) => {
  const key = c.req.query('key') || c.req.header('X-Admin-Key') || ''
  const ADMIN_PASS = (c.env as Record<string,unknown>)?.ADMIN_PASS as string || 'rotaposto@admin2026'
  if (key !== ADMIN_PASS) return c.json({ erro: 'Não autorizado' }, 401)
  const kv = getKV(c.env as any)
  if (!kv) return c.json({ erro: 'KV não disponível' }, 500)
  const config = await getConfigPagamento(kv)
  // Verificar credenciais nos env secrets
  const wooviKey  = (c.env as any)?.WOOVI_APP_ID || (c.env as any)?.OPENPIX_KEY || (c.env as any)?.WOOVI_API_KEY || ''
  const mpKey     = (c.env as any)?.MP_ACCESS_TOKEN || ''
  const asaasKey  = (c.env as any)?.ASAAS_API_KEY || ''
  const temWooviEnv  = Boolean(wooviKey)
  const temMPEnv     = Boolean(mpKey)
  const temAsaasEnv  = Boolean(asaasKey)
  // Prefixo seguro para diagnóstico (6 chars + **)
  const mask = (s: string) => s ? s.slice(0, 6) + '****' : ''
  return c.json({
    config,
    temWooviEnv, temMPEnv, temAsaasEnv,
    // prefixos para diagnóstico de chaves inválidas (nunca expõem a chave completa)
    _diag: { woovi: mask(wooviKey), mp: mask(mpKey), asaas: mask(asaasKey) }
  })
})

// POST /api/admin/config/pagamento
app.post('/api/admin/config/pagamento', async (c) => {
  const key = c.req.query('key') || c.req.header('X-Admin-Key') || ''
  const ADMIN_PASS = (c.env as Record<string,unknown>)?.ADMIN_PASS as string || 'rotaposto@admin2026'
  if (key !== ADMIN_PASS) return c.json({ erro: 'Não autorizado' }, 401)
  const kv = getKV(c.env as any)
  if (!kv) return c.json({ erro: 'KV não disponível' }, 500)
  const body = await c.req.json() as Partial<ConfigPagamento>
  const atual = await getConfigPagamento(kv)
  const nova: ConfigPagamento = {
    ...atual,
    ...body,
    atualizadoEm: Date.now()
  }
  await kv.put(PAGAMENTO_CONFIG_KEY, JSON.stringify(nova), { expirationTtl: 365 * 24 * 3600 })
  return c.json({ ok: true, config: nova })
})

// POST /api/admin/config/pagamento/testar — testa conexão com o gateway
app.post('/api/admin/config/pagamento/testar', async (c) => {
  const key = c.req.query('key') || c.req.header('X-Admin-Key') || ''
  const ADMIN_PASS = (c.env as Record<string,unknown>)?.ADMIN_PASS as string || 'rotaposto@admin2026'
  if (key !== ADMIN_PASS) return c.json({ erro: 'Não autorizado' }, 401)
  const kv = getKV(c.env as any)
  if (!kv) return c.json({ erro: 'KV não disponível' }, 500)
  const { gateway } = await c.req.json() as { gateway: string }
  const config = await getConfigPagamento(kv)

  if (gateway === 'woovi') {
    const wooviKey = (c.env as any)?.WOOVI_APP_ID || (c.env as any)?.OPENPIX_KEY || (c.env as any)?.WOOVI_API_KEY || config.wooviAppId || ''
    if (!wooviKey) {
      await kv.put(PAGAMENTO_CONFIG_KEY, JSON.stringify({ ...config, statusWoovi: 'nao_configurado', atualizadoEm: Date.now() }))
      return c.json({ ok: false, status: 'nao_configurado', mensagem: 'App ID da Woovi não configurado. Insira a chave no campo Credenciais.' })
    }
    try {
      const r = await fetch('https://api.openpix.com.br/api/v1/customer?limit=1', {
        headers: { Authorization: wooviKey },
        signal: AbortSignal.timeout(8000)
      })
      const statusWoovi = r.ok ? 'ok' : 'erro'
      await kv.put(PAGAMENTO_CONFIG_KEY, JSON.stringify({ ...config, statusWoovi, atualizadoEm: Date.now() }))
      let mensagemWoovi = r.ok ? '✅ Woovi conectado!' : ''
      if (!r.ok) {
        if (r.status === 401) {
          mensagemWoovi = `❌ AppID inválido (HTTP 401). Verifique o AppID no painel Woovi/OpenPix → Configurações → API.`
        } else {
          mensagemWoovi = `❌ Erro HTTP ${r.status}`
        }
      }
      return c.json({ ok: r.ok, status: statusWoovi, mensagem: mensagemWoovi })
    } catch (e) {
      await kv.put(PAGAMENTO_CONFIG_KEY, JSON.stringify({ ...config, statusWoovi: 'erro', atualizadoEm: Date.now() }))
      return c.json({ ok: false, status: 'erro', mensagem: 'Falha de rede ao testar Woovi: ' + String(e) })
    }
  }

  if (gateway === 'mercadopago') {
    const mpToken = (c.env as any)?.MP_ACCESS_TOKEN || config.mpAccessToken || ''
    if (!mpToken) {
      await kv.put(PAGAMENTO_CONFIG_KEY, JSON.stringify({ ...config, statusMP: 'nao_configurado', atualizadoEm: Date.now() }))
      return c.json({ ok: false, status: 'nao_configurado', mensagem: 'Access Token do Mercado Pago não configurado. Insira a chave no campo Credenciais.' })
    }
    try {
      const r = await fetch('https://api.mercadopago.com/v1/payment_methods', {
        headers: { Authorization: `Bearer ${mpToken}` },
        signal: AbortSignal.timeout(8000)
      })
      const statusMP = r.ok ? 'ok' : 'erro'
      await kv.put(PAGAMENTO_CONFIG_KEY, JSON.stringify({ ...config, statusMP, atualizadoEm: Date.now() }))
      let mensagemMP = r.ok ? '✅ Mercado Pago conectado!' : ''
      if (!r.ok) {
        if (r.status === 400 || r.status === 401) {
          mensagemMP = `❌ Access Token inválido (HTTP ${r.status}). Verifique em mercadopago.com.br → Suas Integrações → Credenciais.`
        } else {
          mensagemMP = `❌ Erro HTTP ${r.status}`
        }
      }
      return c.json({ ok: r.ok, status: statusMP, mensagem: mensagemMP })
    } catch (e) {
      await kv.put(PAGAMENTO_CONFIG_KEY, JSON.stringify({ ...config, statusMP: 'erro', atualizadoEm: Date.now() }))
      return c.json({ ok: false, status: 'erro', mensagem: 'Falha de rede: ' + String(e) })
    }
  }

  if (gateway === 'asaas') {
    const asaasKey = (c.env as any)?.ASAAS_API_KEY || config.asaasApiKey || ''
    if (!asaasKey) {
      await kv.put(PAGAMENTO_CONFIG_KEY, JSON.stringify({ ...config, statusAsaas: 'nao_configurado', atualizadoEm: Date.now() }))
      return c.json({ ok: false, status: 'nao_configurado', mensagem: 'API Key Asaas não configurada. Insira a chave no campo Credenciais.' })
    }
    try {
      const r = await testarConexaoAsaas(asaasKey)
      const statusAsaas = r.ok ? 'ok' : 'erro'
      await kv.put(PAGAMENTO_CONFIG_KEY, JSON.stringify({ ...config, statusAsaas, atualizadoEm: Date.now() }))
      return c.json({ ok: r.ok, status: statusAsaas, mensagem: r.mensagem })
    } catch (e) {
      await kv.put(PAGAMENTO_CONFIG_KEY, JSON.stringify({ ...config, statusAsaas: 'erro', atualizadoEm: Date.now() }))
      return c.json({ ok: false, status: 'erro', mensagem: 'Falha de rede: ' + String(e) })
    }
  }

  return c.json({ erro: 'Gateway inválido' }, 400)
})

// POST /api/admin/config/pagamento/resetar-status — limpa o status de erro de um gateway no KV
app.post('/api/admin/config/pagamento/resetar-status', async (c) => {
  const key = c.req.query('key') || c.req.header('X-Admin-Key') || ''
  const ADMIN_PASS = (c.env as Record<string,unknown>)?.ADMIN_PASS as string || 'rotaposto@admin2026'
  if (key !== ADMIN_PASS) return c.json({ erro: 'Não autorizado' }, 401)
  const kv = getKV(c.env as any)
  if (!kv) return c.json({ erro: 'KV não disponível' }, 500)
  const { gateway } = await c.req.json() as { gateway: string }
  const config = await getConfigPagamento(kv)
  const update: Partial<ConfigPagamento> = { atualizadoEm: Date.now() }
  if (gateway === 'woovi')       update.statusWoovi = undefined
  else if (gateway === 'mercadopago') update.statusMP = undefined
  else if (gateway === 'asaas')  update.statusAsaas = undefined
  else return c.json({ erro: 'Gateway inválido' }, 400)
  const novaConfig = { ...config, ...update }
  // Remover o campo de status para volcar ao estado "não testado"
  if (gateway === 'woovi')       delete novaConfig.statusWoovi
  else if (gateway === 'mercadopago') delete novaConfig.statusMP
  else if (gateway === 'asaas')  delete novaConfig.statusAsaas
  await kv.put(PAGAMENTO_CONFIG_KEY, JSON.stringify({ ...novaConfig, atualizadoEm: Date.now() }))
  return c.json({ ok: true, mensagem: `Status de ${gateway} resetado para "não testado"` })
})

// POST /api/admin/planos/criar-no-gateway — cria plano/charge no gateway e salva ID externo no KV
app.post('/api/admin/planos/criar-no-gateway', async (c) => {
  const key = c.req.query('key') || c.req.header('X-Admin-Key') || ''
  const ADMIN_PASS = (c.env as Record<string,unknown>)?.ADMIN_PASS as string || 'rotaposto@admin2026'
  if (key !== ADMIN_PASS) return c.json({ erro: 'Não autorizado' }, 401)
  const kv = getKV(c.env as any)
  if (!kv) return c.json({ erro: 'KV não disponível' }, 500)
  const body = await c.req.json() as any
  const { planoId, tipoCatalogo } = body  // tipoCatalogo: 'app' | 'posto'
  const config = await getConfigPagamento(kv)

  // Buscar plano no catálogo correto
  let plano: any = null
  if (tipoCatalogo === 'app') {
    const planos = await getPlanosConfig(kv)
    plano = planos.find((p: any) => p.id === planoId)
  } else {
    const planos = await getPlanosPostoConfig(kv)
    plano = planos.find((p: any) => p.id === planoId)
  }
  if (!plano) return c.json({ erro: 'Plano não encontrado' }, 404)

  const valorCentavos = plano.valor || 0
  const ciclo = plano.ciclo || 'monthly'
  const nome = plano.nome || planoId

  if (config.gateway === 'woovi') {
    const wooviKey = (c.env as any)?.WOOVI_APP_ID || (c.env as any)?.OPENPIX_KEY || (c.env as any)?.WOOVI_API_KEY || config.wooviAppId || ''
    if (!wooviKey) return c.json({ erro: 'Woovi não configurado' }, 400)
    // Woovi Subscription Plan (plan recorrente)
    try {
      const r = await fetch('https://api.openpix.com.br/api/v1/subscriptionplan', {
        method: 'POST',
        headers: { Authorization: wooviKey, 'Content-Type': 'application/json' },
        body: JSON.stringify({
          name: nome,
          value: valorCentavos,
          interval: ciclo === 'yearly' ? 'YEARLY' : 'MONTHLY',
          description: plano.descricao || nome
        })
      })
      const data = await r.json() as any
      if (!r.ok) return c.json({ erro: data.error || `Erro Woovi ${r.status}` }, 500)
      const gatewayId = data.subscriptionPlan?.globalID || data.globalID || ('woovi_' + Date.now())
      // Salvar gatewayId no plano
      await _salvarGatewayIdNoPlano(kv, tipoCatalogo, planoId, 'wooviPlanId', gatewayId)
      return c.json({ ok: true, gateway: 'woovi', gatewayId, mensagem: `Plano criado na Woovi! ID: ${gatewayId}` })
    } catch (e) {
      return c.json({ erro: 'Erro ao criar plano na Woovi: ' + String(e) }, 500)
    }
  }

  if (config.gateway === 'mercadopago') {
    const mpToken = (c.env as any)?.MP_ACCESS_TOKEN || config.mpAccessToken || ''
    if (!mpToken) return c.json({ erro: 'Mercado Pago não configurado. Insira o Access Token no campo Credenciais.' }, 400)
    try {
      const r = await fetch('https://api.mercadopago.com/preapproval_plan', {
        method: 'POST',
        headers: { Authorization: `Bearer ${mpToken}`, 'Content-Type': 'application/json' },
        body: JSON.stringify({
          reason: nome,
          auto_recurring: {
            frequency: ciclo === 'yearly' ? 12 : 1,
            frequency_type: 'months',
            transaction_amount: valorCentavos / 100,
            currency_id: 'BRL'
          },
          back_url: 'https://rotaposto.com.br/app'
        })
      })
      const data = await r.json() as any
      if (!r.ok) return c.json({ erro: data.message || `Erro MP ${r.status}` }, 500)
      const gatewayId = data.id || ('mp_' + Date.now())
      await _salvarGatewayIdNoPlano(kv, tipoCatalogo, planoId, 'mpPlanId', gatewayId)
      return c.json({ ok: true, gateway: 'mercadopago', gatewayId, mensagem: `Plano criado no Mercado Pago! ID: ${gatewayId}` })
    } catch (e) {
      return c.json({ erro: 'Erro ao criar plano no Mercado Pago: ' + String(e) }, 500)
    }
  }

  return c.json({ erro: 'Gateway ativo inválido' }, 400)
})

async function _salvarGatewayIdNoPlano(kv: KVNamespace, tipoCatalogo: string, planoId: string, campo: string, valor: string) {
  if (tipoCatalogo === 'app') {
    const planos = await getPlanosConfig(kv)
    const idx = planos.findIndex((p: any) => p.id === planoId)
    if (idx !== -1) { planos[idx][campo] = valor; await kv.put(PLANOS_KV_KEY, JSON.stringify(planos)) }
  } else {
    const planos = await getPlanosPostoConfig(kv)
    const idx = planos.findIndex((p: any) => p.id === planoId)
    if (idx !== -1) { planos[idx][campo] = valor; await kv.put(PLANOS_POSTO_KV_KEY, JSON.stringify(planos)) }
  }
}

// ═══════════════════════════════════════════════════════════════════════════════
// PIX RECORRENTE B2B — POSTOS PARCEIROS
// KV key: "assin:posto:{postoId}" → JSON AssinaturaPostoPix
// KV index reverso: "sub:posto:{subscriptionId}" → postoId
// ═══════════════════════════════════════════════════════════════════════════════

interface AssinaturaPostoPix {
  postoId: string
  nomeFantasia: string
  email: string
  cnpj?: string
  plano: string         // ex: 'posto_basico', 'posto_plus'
  status: 'ACTIVE' | 'PENDING' | 'EXPIRED' | 'CANCELLED'
  subscriptionId?: string
  chargeId?: string
  qrCode?: string
  brcode?: string
  criadaEm: number
  ativadaEm?: number
  expiraEm?: number
  proximoPagamento?: number
  pagamentos: number
  avisoInadimplencia?: boolean
  inadimplenciaEm?: number
}

async function kvGetAssinaturaPostoPix(kv: KVNamespace, postoId: string): Promise<AssinaturaPostoPix | null> {
  try {
    const raw = await kv.get(`assin:posto:${postoId}`)
    return raw ? JSON.parse(raw) : null
  } catch { return null }
}

async function kvSetAssinaturaPostoPix(kv: KVNamespace, postoId: string, assin: AssinaturaPostoPix) {
  await kv.put(`assin:posto:${postoId}`, JSON.stringify(assin), { expirationTtl: 63072000 }) // 2 anos
  if (assin.subscriptionId) {
    await kv.put(`sub:posto:${assin.subscriptionId}`, postoId, { expirationTtl: 63072000 })
  }
  if (assin.chargeId) {
    await kv.put(`sub:posto:${assin.chargeId}`, postoId, { expirationTtl: 63072000 })
  }
}

// ─── POST /api/pix/posto/assinar — cria assinatura PIX para posto ────────────
app.post('/api/pix/posto/assinar', async (c) => {
  try {
    const body = await c.req.json() as any
    const { postoId, nomeFantasia, email, cnpj, plano } = body
    if (!postoId || !nomeFantasia) {
      return c.json({ sucesso: false, mensagem: 'postoId e nomeFantasia são obrigatórios' }, 400)
    }
    const kv = getKV(c.env)
    if (!kv) return c.json({ sucesso: false, mensagem: 'Serviço indisponível' }, 500)

    // Verificar plano válido (deve ser pago)
    const planosPostoConfig = await getPlanosPostoConfig(kv)
    const planoInfo = planosPostoConfig.find((p: any) => p.id === plano)
    if (!planoInfo || planoInfo.valor === 0) {
      return c.json({ sucesso: false, mensagem: 'Plano inválido ou gratuito' }, 400)
    }

    // Verificar assinatura existente
    const existente = await kvGetAssinaturaPostoPix(kv, postoId)
    if (existente?.status === 'ACTIVE') {
      return c.json({ sucesso: true, jaAssinante: true, plano: existente.plano, expiraEm: existente.expiraEm, mensagem: 'Posto já tem assinatura ativa!' })
    }
    if (existente?.status === 'PENDING' && existente.qrCode) {
      return c.json({ sucesso: true, jaPendente: true, qrCode: existente.qrCode, brcode: existente.brcode, subscriptionId: existente.subscriptionId, plano: existente.plano, valor: planoInfo.valor })
    }

    // CPF/CNPJ para Woovi — usar CNPJ como taxID ou gerar fallback
    const docLimpo = (cnpj || '').replace(/[^0-9]/g, '') || postoId.replace(/[^0-9]/g, '').slice(0, 14).padEnd(11, '0')
    const emailFinal = (email || '').trim() || `posto-${postoId.slice(-8)}@rotaposto.app`

    const resultado = await criarAssinaturaPIX(c.env as any, nomeFantasia, emailFinal, docLimpo.slice(0, 11), plano)
    if (!resultado.sucesso) {
      return c.json({ sucesso: false, mensagem: resultado.error || 'Erro ao gerar PIX' }, 500)
    }

    const assin: AssinaturaPostoPix = {
      postoId, nomeFantasia, email: emailFinal, cnpj: docLimpo,
      plano, status: 'PENDING',
      subscriptionId: resultado.subscriptionId,
      chargeId: resultado.chargeId,
      qrCode: resultado.qrCode, brcode: resultado.brcode,
      criadaEm: Date.now(), pagamentos: 0
    }
    await kvSetAssinaturaPostoPix(kv, postoId, assin)

    return c.json({
      sucesso: true, qrCode: resultado.qrCode, brcode: resultado.brcode,
      subscriptionId: resultado.subscriptionId, plano, valor: planoInfo.valor,
      demo: resultado.demo || false,
      mensagem: 'QR Code PIX gerado! Pague para ativar o plano ' + planoInfo.nome + '.'
    })
  } catch (e: any) {
    console.error('[PIX posto assinar]', e)
    return c.json({ sucesso: false, mensagem: 'Erro ao gerar PIX' }, 500)
  }
})

// ─── POST /api/pix/posto/renovar — gera novo PIX para posto inadimplente ─────
app.post('/api/pix/posto/renovar', async (c) => {
  try {
    const body = await c.req.json() as any
    const { postoId } = body
    if (!postoId) return c.json({ sucesso: false, mensagem: 'postoId obrigatório' }, 400)
    const kv = getKV(c.env)
    if (!kv) return c.json({ sucesso: false, mensagem: 'Serviço indisponível' }, 500)

    const assin = await kvGetAssinaturaPostoPix(kv, postoId)
    if (!assin) return c.json({ sucesso: false, mensagem: 'Nenhuma assinatura encontrada' }, 404)
    if (assin.status === 'ACTIVE') return c.json({ sucesso: false, mensagem: 'Assinatura já está ativa!', jaAtiva: true })

    const planosConfig = await getPlanosPostoConfig(kv)
    const planoInfo = planosConfig.find((p: any) => p.id === assin.plano) || planosConfig.find((p: any) => p.id === 'posto_basico')
    const docLimpo = (assin.cnpj || postoId.replace(/[^0-9]/g, '').slice(0, 11).padEnd(11, '0'))

    const resultado = await criarAssinaturaPIX(c.env as any, assin.nomeFantasia, assin.email, docLimpo.slice(0, 11), assin.plano)
    if (!resultado.sucesso) return c.json({ sucesso: false, mensagem: resultado.error || 'Erro ao gerar PIX' }, 500)

    assin.status = 'PENDING'
    assin.qrCode = resultado.qrCode
    assin.brcode = resultado.brcode
    assin.subscriptionId = resultado.subscriptionId
    assin.chargeId = resultado.chargeId
    await kvSetAssinaturaPostoPix(kv, postoId, assin)

    return c.json({
      sucesso: true, qrCode: resultado.qrCode, brcode: resultado.brcode,
      subscriptionId: resultado.subscriptionId,
      txid: resultado.chargeId, // Para polling de verificação
      plano: assin.plano,
      valor: planoInfo?.valor ?? 9900, demo: resultado.demo || false,
      mensagem: 'Novo QR Code gerado! Pague para reativar o plano do posto.'
    })
  } catch (e: any) {
    return c.json({ sucesso: false, mensagem: 'Erro ao renovar' }, 500)
  }
})

// ─── GET /api/pix/posto/status/:postoId — status da assinatura do posto ──────
app.get('/api/pix/posto/status/:postoId', async (c) => {
  const postoId = c.req.param('postoId')
  const kv = getKV(c.env)
  if (!kv) return c.json({ status: 'UNKNOWN', ativa: false })

  const assin = await kvGetAssinaturaPostoPix(kv, postoId)
  if (!assin) return c.json({ status: 'FREE', plano: 'posto_gratis', ativa: false })

  // Verificar expiração por tempo
  const agora = Date.now()
  const GRACE = 3 * 24 * 3600 * 1000 // 3 dias de carência
  if (assin.status === 'ACTIVE' && assin.expiraEm && agora > assin.expiraEm + GRACE) {
    assin.status = 'EXPIRED'
    assin.avisoInadimplencia = true
    assin.inadimplenciaEm = agora
    await kvSetAssinaturaPostoPix(kv, postoId, assin)
    // Rebaixar plano
    const parceiro = await kvGetParceiro(kv, postoId, undefined)
    if (parceiro) {
      (parceiro as any).plano = 'posto_gratis'
      await kvSetParceiro(kv, postoId, parceiro as Record<string,unknown>, undefined, undefined)
    }
  }

  return c.json({
    status: assin.status, plano: assin.plano, ativa: assin.status === 'ACTIVE',
    expiraEm: assin.expiraEm, pagamentos: assin.pagamentos,
    avisoInadimplencia: assin.avisoInadimplencia || false,
    qrCode: assin.status === 'PENDING' ? assin.qrCode : null,
    brcode: assin.status === 'PENDING' ? assin.brcode : null,
    subscriptionId: assin.status === 'PENDING' ? assin.subscriptionId : null
  })
})

// Atualizar webhook para processar pagamentos de postos também
// (handler unificado — a lógica de EXPIRADO para postos já está no webhook app acima)
// Pagamento PAGO de posto:
// O webhook do Woovi usa /api/pix/webhook — expandir lá o bloco PAGO para verificar postos
// via sub:posto:{id} index

// ─── DELETE /api/admin/postos/:id — remover posto parceiro do R2 + KV ──────────
app.delete('/api/admin/postos/:id', async (c) => {
  const key = c.req.query('key') || c.req.header('X-Admin-Key') || ''
  const ADMIN_PASS = (c.env as Record<string,unknown>)?.ADMIN_PASS as string || 'rotaposto@admin2026'
  if (key !== ADMIN_PASS) return c.json({ erro: 'Não autorizado' }, 401)
  const r2 = (c.env as Record<string,unknown>)?.ROTAPOSTO_R2 as R2Bucket | undefined
  const kv = getKV(c.env as any)
  const id = c.req.param('id')
  if (id === 'p_teste') return c.json({ erro: 'Posto de teste não pode ser removido' }, 400)
  // Apagar do R2
  try { if (r2) await r2.delete(`parceiro--${id}`) } catch {}
  // Apagar do KV (legado)
  try { if (kv) await kv.delete(`parceiro:${id}`) } catch {}
  // Apagar foto-bandeira do R2 (todas extensões)
  if (r2) {
    for (const ext of ['jpg', 'png', 'webp']) {
      try { await r2.delete(`posto-bandeira/${id}.${ext}`) } catch {}
    }
  }
  // Apagar preços e promos do KV
  try { if (kv) await kv.delete(`precos:${id}`) } catch {}
  try { if (r2) await r2.delete(`precos--${id}`) } catch {}
  return c.json({ ok: true, id })
})

// ─── POST /api/admin/script/propagar-logos — propaga fotoBandeira/fotoExterna para posto:band KV ──
app.post('/api/admin/script/propagar-logos', async (c) => {
  const key = c.req.query('key') || c.req.header('X-Admin-Key') || ''
  const ADMIN_PASS = (c.env as Record<string,unknown>)?.ADMIN_PASS as string || 'rotaposto@admin2026'
  if (key !== ADMIN_PASS) return c.json({ erro: 'Não autorizado' }, 401)

  const kv = getKV(c.env as any)
  const r2 = (c.env as Record<string,unknown>)?.ROTAPOSTO_R2 as R2Bucket | undefined
  if (!kv) return c.json({ ok: false, erro: 'KV indisponível' }, 500)

  const resultados: Array<Record<string,unknown>> = []
  let atualizados = 0, ignorados = 0, erros = 0

  // 1. Listar todos os parceiros do R2
  const listaR2: Array<{ id: string; data: Record<string,unknown> }> = []
  if (r2) {
    try {
      const listed = await r2.list({ prefix: 'parceiro--' })
      for (const obj of listed.objects) {
        const id = obj.key.replace('parceiro--', '')
        if (id.startsWith('email_') || id.startsWith('cnpj_')) continue
        try {
          const data = await r2Get(r2, `parceiro:${id}`) as Record<string,unknown> | null
          if (data && data.id) listaR2.push({ id: String(data.id), data })
        } catch {}
      }
    } catch(e) { console.warn('[propagar-logos] r2.list erro:', e) }
  }
  // Fallback KV
  if (listaR2.length === 0 && kv) {
    try {
      const kvList = await kv.list({ prefix: 'parceiro:' })
      for (const k of kvList.keys) {
        const seg = k.name.replace('parceiro:', '')
        if (seg.startsWith('sess_') || seg.startsWith('email_') || seg.startsWith('cnpj_')) continue
        try {
          const raw = await kv.get(k.name)
          if (!raw) continue
          const data = JSON.parse(raw) as Record<string,unknown>
          if (data?.id) listaR2.push({ id: String(data.id), data })
        } catch {}
      }
    } catch {}
  }

  // 2. Para cada parceiro com foto, propagar para posto:band:*
  for (const { id, data } of listaR2) {
    const fotoExterna  = data.fotoExterna  ? String(data.fotoExterna)  : null
    const fotoBandeira = data.fotoBandeira ? String(data.fotoBandeira) : null
    const fotoUrl = fotoExterna || fotoBandeira

    if (!fotoUrl) {
      ignorados++
      resultados.push({ id, nomePosto: data.nomePosto, status: 'sem_foto_pular' })
      continue
    }

    const fotoTs = data.fotoTs ? Number(data.fotoTs) : Date.now()

    try {
      const bandKey = `posto:band:${id}`
      const bandRaw = await kv.get(bandKey)
      let band: Record<string,unknown> = bandRaw ? JSON.parse(bandRaw) : { postoId: id }
      band.fotoUrl  = fotoUrl
      band.fotoTs   = fotoTs
      band.fotoExterna = fotoExterna || null
      await kv.put(bandKey, JSON.stringify(band), { expirationTtl: 365 * 24 * 3600 })

      const cnpjStr = data.cnpj ? String(data.cnpj).replace(/[^0-9]/g, '') : ''
      if (cnpjStr && cnpjStr.length >= 11) {
        const cnpjBandKey = `posto:band:posto_${cnpjStr}`
        const cnpjBandRaw = await kv.get(cnpjBandKey)
        let cnpjBand: Record<string,unknown> = cnpjBandRaw
          ? JSON.parse(cnpjBandRaw)
          : { postoId: `posto_${cnpjStr}`, cnpj: cnpjStr }
        cnpjBand.fotoUrl  = fotoUrl
        cnpjBand.fotoTs   = fotoTs
        cnpjBand.fotoExterna = fotoExterna || null
        cnpjBand.parceiroId  = id
        await kv.put(cnpjBandKey, JSON.stringify(cnpjBand), { expirationTtl: 365 * 24 * 3600 })
      }

      atualizados++
      resultados.push({
        id, nomePosto: data.nomePosto || id,
        cnpj: data.cnpj || null,
        fotoUrl, tipo: fotoExterna ? 'fotoExterna' : 'fotoBandeira',
        status: 'propagado'
      })
    } catch(e) {
      erros++
      resultados.push({ id, nomePosto: data.nomePosto, status: 'erro', msg: String(e) })
    }
  }

  return c.json({ ok: true, total: listaR2.length, atualizados, ignorados, erros, resultados })
})

// ─── POST /api/admin/script/auto-fotos — busca foto Google Places + logo SVG automaticamente ──
app.post('/api/admin/script/auto-fotos', async (c) => {
  const key = c.req.query('key') || c.req.header('X-Admin-Key') || ''
  const ADMIN_PASS = (c.env as Record<string,unknown>)?.ADMIN_PASS as string || 'rotaposto@admin2026'
  if (key !== ADMIN_PASS) return c.json({ erro: 'Não autorizado' }, 401)

  // ?forcar=true → re-busca mesmo se já tem foto/logo (útil para atualizar)
  const forcar = c.req.query('forcar') === 'true'

  const kv = getKV(c.env as any)
  const r2 = (c.env as Record<string,unknown>)?.ROTAPOSTO_R2 as R2Bucket | undefined
  const googleKey = (c.env as any)?.GOOGLE_PLACES_KEY as string || GOOGLE_API_KEY || ''
  if (!kv) return c.json({ ok: false, erro: 'KV indisponível' }, 500)

  // Mapa de bandeira → URL do logo SVG (mesmo mapeamento do app)
  const logoSvgPorBandeira = (bandeira: string): string | null => {
    if (!bandeira) return null
    const n = bandeira.toUpperCase()
    if (n.includes('SHELL'))                                             return 'https://rotaposto.com.br/static/logos/shell.svg'
    if (n.includes('PETROBRAS') || /\bBR\b/.test(n))                    return 'https://rotaposto.com.br/static/logos/br.svg'
    if (n.includes('IPIRANGA'))                                          return 'https://rotaposto.com.br/static/logos/ipiranga.svg'
    if (n.includes('RAIZEN') || n.includes('RAÍZEN'))                   return 'https://rotaposto.com.br/static/logos/raizen.svg'
    if (/\bALE\b/.test(n) || n.includes('ALEPOSTO'))                    return 'https://rotaposto.com.br/static/logos/ale.svg'
    if (n.includes('TEXACO'))                                            return 'https://rotaposto.com.br/static/logos/texaco.svg'
    if (n.includes('VIBRA'))                                             return 'https://rotaposto.com.br/static/logos/vibra.svg'
    if (n.includes('ESSO'))                                              return 'https://rotaposto.com.br/static/logos/esso.svg'
    if (n.includes('PITSTOP') || n.includes('PIT STOP'))                return 'https://rotaposto.com.br/static/logos/pitstop.svg'
    if (n.includes('BANDEIRANTE'))                                       return 'https://rotaposto.com.br/static/logos/bandeirante.svg'
    if (n.includes('COPAGAZ'))                                           return 'https://rotaposto.com.br/static/logos/copagaz.svg'
    if (n.includes('ULTRAGAZ'))                                          return 'https://rotaposto.com.br/static/logos/ultragaz.svg'
    if (n.includes('SUPERGASBRAS') || n.includes('SUPER GAS'))          return 'https://rotaposto.com.br/static/logos/supergasbras.svg'
    return null // Independente → sem logo automático
  }

  // Busca foto real + rating do Google Places por nome+cidade (Text Search)
  const buscarFotoGoogle = async (nomePosto: string, cidade: string, lat?: number | null, lng?: number | null): Promise<{ fotoUrl: string | null; rating: number | null; placeId: string | null }> => {
    if (!googleKey) return { fotoUrl: null, rating: null, placeId: null }
    try {
      // Se temos coordenadas, usar Nearby Search (mais preciso)
      if (lat && lng) {
        const res = await fetch('https://places.googleapis.com/v1/places:searchNearby', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'X-Goog-Api-Key': googleKey,
            'X-Goog-FieldMask': 'places.id,places.displayName,places.photos,places.rating',
            'Accept-Language': 'pt-BR'
          },
          body: JSON.stringify({
            includedTypes: ['gas_station'],
            maxResultCount: 3,
            locationRestriction: { circle: { center: { latitude: lat, longitude: lng }, radius: 100 } },
            rankPreference: 'DISTANCE'
          }),
          signal: AbortSignal.timeout(8000)
        })
        if (res.ok) {
          const json = await res.json() as any
          const place = (json.places || [])[0]
          if (place) {
            let fotoUrl: string | null = null
            if (place.photos?.length > 0) {
              const photoRef = place.photos[0].name
              fotoUrl = `https://places.googleapis.com/v1/${photoRef}/media?key=${googleKey}&maxWidthPx=800`
            }
            return { fotoUrl, rating: place.rating || null, placeId: place.id || null }
          }
        }
      }
      // Fallback: Text Search por nome + cidade
      const query = encodeURIComponent(`${nomePosto} ${cidade} posto combustivel`)
      const res2 = await fetch(`https://places.googleapis.com/v1/places:searchText`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'X-Goog-Api-Key': googleKey,
          'X-Goog-FieldMask': 'places.id,places.displayName,places.photos,places.rating',
          'Accept-Language': 'pt-BR'
        },
        body: JSON.stringify({ textQuery: `${nomePosto} ${cidade}`, includedType: 'gas_station', maxResultCount: 1 }),
        signal: AbortSignal.timeout(8000)
      })
      if (!res2.ok) return { fotoUrl: null, rating: null, placeId: null }
      const json2 = await res2.json() as any
      const place2 = (json2.places || [])[0]
      if (!place2) return { fotoUrl: null, rating: null, placeId: null }
      let fotoUrl2: string | null = null
      if (place2.photos?.length > 0) {
        const photoRef = place2.photos[0].name
        fotoUrl2 = `https://places.googleapis.com/v1/${photoRef}/media?key=${googleKey}&maxWidthPx=800`
      }
      return { fotoUrl: fotoUrl2, rating: place2.rating || null, placeId: place2.id || null }
    } catch { return { fotoUrl: null, rating: null, placeId: null } }
  }

  // 1. Listar todos os parceiros
  const listaR2: Array<{ id: string; data: Record<string,unknown> }> = []
  if (r2) {
    try {
      const listed = await r2.list({ prefix: 'parceiro--' })
      for (const obj of listed.objects) {
        const id = obj.key.replace('parceiro--', '')
        if (id.startsWith('email_') || id.startsWith('cnpj_')) continue
        try {
          const data = await r2Get(r2, `parceiro:${id}`) as Record<string,unknown> | null
          if (data && data.id) listaR2.push({ id: String(data.id), data })
        } catch {}
      }
    } catch {}
  }
  if (listaR2.length === 0 && kv) {
    try {
      const kvList = await kv.list({ prefix: 'parceiro:' })
      for (const k of kvList.keys) {
        const seg = k.name.replace('parceiro:', '')
        if (seg.startsWith('sess_') || seg.startsWith('email_') || seg.startsWith('cnpj_')) continue
        try {
          const raw = await kv.get(k.name)
          if (!raw) continue
          const data = JSON.parse(raw) as Record<string,unknown>
          if (data?.id) listaR2.push({ id: String(data.id), data })
        } catch {}
      }
    } catch {}
  }

  const resultados: Array<Record<string,unknown>> = []
  let logosSalvos = 0, fotosSalvas = 0, jaOkCount = 0, erros = 0

  for (const { id, data } of listaR2) {
    if (id === 'p_teste') continue
    const nomePosto = String(data.nomePosto || '')
    const bandeira  = String(data.bandeira  || '')
    const cidade    = String(data.cidade    || '')
    const lat       = data.lat  ? Number(data.lat)  : null
    const lng       = data.lng  ? Number(data.lng)  : null

    let modificado = false
    const res: Record<string,unknown> = { id, nomePosto, bandeira, acoes: [] as string[] }

    try {
      // ── A) Logo da bandeira automático ──
      // forcar=true: só re-busca logo se a atual é SVG (não é upload manual do admin)
      const logoAtualEhSvg = data.fotoBandeira && String(data.fotoBandeira).includes('/static/logos/')
      const logoAtualEhUpload = data.fotoBandeira && String(data.fotoBandeira).startsWith('/api/posto/foto-bandeira/')
      if (!data.fotoBandeira || (forcar && logoAtualEhSvg && !logoAtualEhUpload)) {
        const logoUrl = logoSvgPorBandeira(bandeira || nomePosto)
        if (logoUrl) {
          data.fotoBandeira = logoUrl
          ;(res.acoes as string[]).push('logo_svg:' + logoUrl.split('/').pop())
          logosSalvos++
          modificado = true
        }
      }

      // ── B) Foto panorâmica do Google ──
      // forcar=true: re-busca sempre (atualiza foto do Google mesmo se já tem)
      if (!data.fotoExterna || forcar) {
        const { fotoUrl, rating, placeId } = await buscarFotoGoogle(nomePosto, cidade, lat, lng)
        if (fotoUrl) {
          data.fotoExterna = fotoUrl
          ;(res.acoes as string[]).push('foto_google:ok')
          fotosSalvas++
          modificado = true
        } else {
          ;(res.acoes as string[]).push('foto_google:nao_encontrada')
        }
        if (rating) { data.rating = rating; if (!modificado) modificado = true }
        if (placeId) { data.googlePlaceId = placeId; if (!modificado) modificado = true }
        res.rating = rating
        res.placeId = placeId
      }

      if (!modificado) {
        jaOkCount++
        res.status = 'ja_tem_foto'
        resultados.push(res)
        continue
      }

      // Salvar parceiro atualizado
      if (r2) {
        await r2Put(r2, `parceiro:${id}`, data)
      } else if (kv) {
        await kv.put(`parceiro:${id}`, JSON.stringify(data), { expirationTtl: 365 * 24 * 3600 })
      }

      // Propagar para posto:band KV (usado na lista/mapa)
      const fotoFinal = data.fotoExterna ? String(data.fotoExterna) : (data.fotoBandeira ? String(data.fotoBandeira) : null)
      if (fotoFinal) {
        const bandKey = `posto:band:${id}`
        const bandRaw = await kv.get(bandKey)
        const band: Record<string,unknown> = bandRaw ? JSON.parse(bandRaw) : { postoId: id }
        band.fotoUrl = fotoFinal
        band.fotoTs  = Date.now()
        await kv.put(bandKey, JSON.stringify(band), { expirationTtl: 365 * 24 * 3600 })
        const cnpjStr = data.cnpj ? String(data.cnpj).replace(/[^0-9]/g, '') : ''
        if (cnpjStr && cnpjStr.length >= 11) {
          const ck = `posto:band:posto_${cnpjStr}`
          const cr = await kv.get(ck)
          const cb: Record<string,unknown> = cr ? JSON.parse(cr) : { postoId: `posto_${cnpjStr}` }
          cb.fotoUrl = fotoFinal; cb.fotoTs = Date.now(); cb.parceiroId = id
          await kv.put(ck, JSON.stringify(cb), { expirationTtl: 365 * 24 * 3600 })
        }
      }

      res.status = 'atualizado'
      resultados.push(res)
    } catch(e) {
      erros++
      resultados.push({ id, nomePosto, status: 'erro', msg: String(e) })
    }
  }

  return c.json({
    ok: true,
    total: listaR2.length,
    logosSalvos,
    fotosSalvas,
    jaOkCount,
    erros,
    googleKeyDisponivel: !!googleKey,
    resultados
  })
})

// ─── POST /api/admin/script/auto-fotos-postos-band — logo SVG + foto Google para posto:band:* ──
// Processa TODOS os postos do KV (ANP, OSM, Google) que não têm fotoUrl ou logoUrl
app.post('/api/admin/script/auto-fotos-postos-band', async (c) => {
  const key = c.req.query('key') || c.req.header('X-Admin-Key') || ''
  const ADMIN_PASS = (c.env as Record<string,unknown>)?.ADMIN_PASS as string || 'rotaposto@admin2026'
  if (key !== ADMIN_PASS) return c.json({ erro: 'Não autorizado' }, 401)

  // ?forcar=true → re-busca foto Google mesmo se já tem fotoUrl
  const forcar = c.req.query('forcar') === 'true'

  const kv = getKV(c.env as any)
  const googleKey = (c.env as any)?.GOOGLE_PLACES_KEY as string || GOOGLE_API_KEY || ''
  if (!kv) return c.json({ ok: false, erro: 'KV indisponível' }, 500)

  // Limite de postos processados por chamada (evitar timeout dos Workers)
  const limite = parseInt(c.req.query('limite') || '60')

  // Mapa bandeira → logo SVG
  const logoSvgPorBandeira = (bandeira: string, nome: string): string | null => {
    const n = (bandeira + ' ' + nome).toUpperCase()
    if (n.includes('SHELL'))                                          return 'https://rotaposto.com.br/static/logos/shell.svg'
    if (n.includes('PETROBRAS') || /\bBR\b/.test(n) || n.includes('BR DISTRIBUIDORA')) return 'https://rotaposto.com.br/static/logos/br.svg'
    if (n.includes('IPIRANGA'))                                       return 'https://rotaposto.com.br/static/logos/ipiranga.svg'
    if (n.includes('RAIZEN') || n.includes('RAÍZEN'))                 return 'https://rotaposto.com.br/static/logos/raizen.svg'
    if (/\bALE\b/.test(n) || n.includes('ALEPOSTO'))                  return 'https://rotaposto.com.br/static/logos/ale.svg'
    if (n.includes('TEXACO'))                                         return 'https://rotaposto.com.br/static/logos/texaco.svg'
    if (n.includes('VIBRA'))                                          return 'https://rotaposto.com.br/static/logos/vibra.svg'
    if (n.includes('ESSO'))                                           return 'https://rotaposto.com.br/static/logos/esso.svg'
    if (n.includes('PITSTOP') || n.includes('PIT STOP'))             return 'https://rotaposto.com.br/static/logos/pitstop.svg'
    if (n.includes('BANDEIRANTE'))                                    return 'https://rotaposto.com.br/static/logos/bandeirante.svg'
    if (n.includes('COPAGAZ'))                                        return 'https://rotaposto.com.br/static/logos/copagaz.svg'
    if (n.includes('ULTRAGAZ'))                                       return 'https://rotaposto.com.br/static/logos/ultragaz.svg'
    if (n.includes('SUPERGASBRAS') || n.includes('SUPER GAS'))       return 'https://rotaposto.com.br/static/logos/supergasbras.svg'
    return null
  }

  // Busca foto Google por coordenadas (Nearby Search) ou nome+cidade (Text Search)
  const buscarFotoGoogle = async (nome: string, cidade: string, lat?: number | null, lng?: number | null): Promise<string | null> => {
    if (!googleKey) return null
    try {
      if (lat && lng) {
        const res = await fetch('https://places.googleapis.com/v1/places:searchNearby', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'X-Goog-Api-Key': googleKey,
            'X-Goog-FieldMask': 'places.id,places.photos',
            'Accept-Language': 'pt-BR'
          },
          body: JSON.stringify({
            includedTypes: ['gas_station'],
            maxResultCount: 1,
            locationRestriction: { circle: { center: { latitude: lat, longitude: lng }, radius: 80 } },
            rankPreference: 'DISTANCE'
          }),
          signal: AbortSignal.timeout(7000)
        })
        if (res.ok) {
          const j = await res.json() as any
          const place = (j.places || [])[0]
          if (place?.photos?.length > 0) {
            return `https://places.googleapis.com/v1/${place.photos[0].name}/media?key=${googleKey}&maxWidthPx=800`
          }
        }
      }
      // Fallback: Text Search
      const res2 = await fetch('https://places.googleapis.com/v1/places:searchText', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'X-Goog-Api-Key': googleKey,
          'X-Goog-FieldMask': 'places.id,places.photos',
          'Accept-Language': 'pt-BR'
        },
        body: JSON.stringify({ textQuery: `${nome} ${cidade} posto combustivel`, includedType: 'gas_station', maxResultCount: 1 }),
        signal: AbortSignal.timeout(7000)
      })
      if (!res2.ok) return null
      const j2 = await res2.json() as any
      const place2 = (j2.places || [])[0]
      if (place2?.photos?.length > 0) {
        return `https://places.googleapis.com/v1/${place2.photos[0].name}/media?key=${googleKey}&maxWidthPx=800`
      }
      return null
    } catch { return null }
  }

  // Cursor de entrada para paginação — cliente passa o cursor retornado pela chamada anterior
  const cursorIn = c.req.query('cursor') || undefined

  // Listar posto:band:* do KV (todos os postos do mapa)
  const resultados: Array<Record<string, unknown>> = []
  let logosSalvos = 0, fotosSalvas = 0, jaOkCount = 0, erros = 0, processados = 0
  let cursor: string | undefined = cursorIn
  let listComplete = false

  while (processados < limite) {
    const batch = Math.min(20, limite - processados)
    const list = await kv.list({ prefix: 'posto:band:', limit: batch, cursor })
    if (!list.keys.length) { listComplete = true; break }

    for (const kkey of list.keys) {
      if (processados >= limite) break
      processados++

      const raw = await kv.get(kkey.name)
      if (!raw) continue
      let dado: Record<string, unknown>
      try { dado = JSON.parse(raw) } catch { continue }

      const postoId  = String(dado.postoId || kkey.name.replace('posto:band:', ''))
      const nome     = String(dado.postoNome || dado.nome || '')
      const bandeira = String(dado.bandeiraNome || dado.bandeira || '')
      const cidade   = String(dado.cidade || '')
      const lat      = dado.lat ? Number(dado.lat) : null
      const lng      = dado.lng ? Number(dado.lng) : null

      // Verificar se já tem logo E foto
      const temLogo = !!(dado.logoUrl || dado.fotoUrl)
      const temFoto = !!(dado.fotoUrl)

      // Pular só se tem tudo e não está forçando re-busca
      if (temLogo && temFoto && !forcar) {
        jaOkCount++
        resultados.push({ postoId, nome, status: 'ja_ok' })
        continue
      }

      let modificado = false
      const acoes: string[] = []

      try {
        // A) Logo SVG pela bandeira (só se não tem logoUrl — logo SVG não é re-buscado no forcar)
        if (!dado.logoUrl) {
          const logoUrl = logoSvgPorBandeira(bandeira, nome)
          if (logoUrl) {
            dado.logoUrl = logoUrl
            acoes.push('logo_svg:' + logoUrl.split('/').pop())
            logosSalvos++
            modificado = true
          }
        }

        // B) Foto do Google Maps — busca se não tem fotoUrl OU se forcar=true
        // Preservar fotoUrl que vem de upload admin (/api/posto/foto-bandeira/)
        const fotoUrlAtualEhAdmin = dado.fotoUrl && String(dado.fotoUrl).startsWith('/api/posto/foto-bandeira/')
        if (!dado.fotoUrl || (forcar && !fotoUrlAtualEhAdmin)) {
          const fotoUrl = await buscarFotoGoogle(nome, cidade, lat, lng)
          if (fotoUrl) {
            dado.fotoUrl = fotoUrl
            dado.fotoTs  = new Date().toISOString()
            acoes.push('foto_google:ok')
            fotosSalvas++
            modificado = true
          } else {
            acoes.push('foto_google:nao_encontrada')
          }
        }

        if (modificado) {
          await kv.put(kkey.name, JSON.stringify(dado), { expirationTtl: 365 * 24 * 3600 })
          resultados.push({ postoId, nome, status: 'atualizado', acoes })
        } else {
          jaOkCount++
          resultados.push({ postoId, nome, status: 'ja_ok', acoes })
        }

        // Pausa para não estourar rate limit
        await new Promise(r => setTimeout(r, 80))
      } catch(e) {
        erros++
        resultados.push({ postoId, nome, status: 'erro', msg: String(e) })
      }
    }

    if (list.list_complete) { listComplete = true; break }
    cursor = (list as any).cursor
    if (!cursor) { listComplete = true; break }
  }

  return c.json({
    ok: true,
    total: processados,
    logosSalvos,
    fotosSalvas,
    jaOkCount,
    erros,
    googleKeyDisponivel: !!googleKey,
    listComplete,
    // cursor null = acabou tudo; string = tem mais para processar
    cursor: listComplete ? null : cursor,
    resultados
  })
})

// ─── POST /api/admin/script/aplicar-logos-bandeira — aplica logo SVG em massa nos posto:band:* sem logo ──
// Varre TODOS os posto:band:* que não têm logoUrl e aplica o SVG pela bandeira (sem tocar quem já tem)
app.post('/api/admin/script/aplicar-logos-bandeira', async (c) => {
  const key = c.req.query('key') || c.req.header('X-Admin-Key') || ''
  const ADMIN_PASS = (c.env as Record<string,unknown>)?.ADMIN_PASS as string || 'rotaposto@admin2026'
  if (key !== ADMIN_PASS) return c.json({ erro: 'Não autorizado' }, 401)

  const kv = getKV(c.env as any)
  if (!kv) return c.json({ ok: false, erro: 'KV indisponível' }, 500)

  // Limite por chamada para não estourar CPU (30s Workers limit)
  const limite = parseInt(c.req.query('limite') || '500')
  // Cursor para paginação — cliente envia o cursor da resposta anterior
  const cursorIn = c.req.query('cursor') || undefined

  const logoSvgPorBandeira = (bandeira: string, nome: string): string | null => {
    const n = (bandeira + ' ' + nome).toUpperCase()
    if (n.includes('SHELL'))                                              return 'https://rotaposto.com.br/static/logos/shell.svg'
    if (n.includes('PETROBRAS') || /\bBR\b/.test(n) || n.includes('BR DISTRIBUIDORA')) return 'https://rotaposto.com.br/static/logos/br.svg'
    if (n.includes('IPIRANGA'))                                           return 'https://rotaposto.com.br/static/logos/ipiranga.svg'
    if (n.includes('RAIZEN') || n.includes('RAÍZEN'))                    return 'https://rotaposto.com.br/static/logos/raizen.svg'
    if (/\bALE\b/.test(n) || n.includes('ALEPOSTO'))                     return 'https://rotaposto.com.br/static/logos/ale.svg'
    if (n.includes('TEXACO'))                                             return 'https://rotaposto.com.br/static/logos/texaco.svg'
    if (n.includes('VIBRA'))                                              return 'https://rotaposto.com.br/static/logos/vibra.svg'
    if (n.includes('ESSO'))                                               return 'https://rotaposto.com.br/static/logos/esso.svg'
    if (n.includes('PITSTOP') || n.includes('PIT STOP'))                 return 'https://rotaposto.com.br/static/logos/pitstop.svg'
    if (n.includes('BANDEIRANTE'))                                        return 'https://rotaposto.com.br/static/logos/bandeirante.svg'
    if (n.includes('COPAGAZ'))                                            return 'https://rotaposto.com.br/static/logos/copagaz.svg'
    if (n.includes('ULTRAGAZ') || n.includes('ULTRA GAZ'))               return 'https://rotaposto.com.br/static/logos/ultragaz.svg'
    if (n.includes('SUPERGASBRAS') || n.includes('SUPER GAS'))           return 'https://rotaposto.com.br/static/logos/supergasbras.svg'
    return null
  }

  let logosSalvos = 0, jaOkCount = 0, semLogo = 0, erros = 0, processados = 0
  let cursorOut: string | undefined = undefined
  let listComplete = false

  // Uma única passagem paginada — limite postos por chamada
  while (processados < limite) {
    const batch = Math.min(50, limite - processados)
    const list = await kv.list({ prefix: 'posto:band:', limit: batch, cursor: cursorOut || cursorIn })

    for (const kkey of list.keys) {
      if (processados >= limite) break
      processados++

      try {
        const raw = await kv.get(kkey.name)
        if (!raw) continue
        const dado: Record<string, unknown> = JSON.parse(raw)

        // ── Nunca tocar quem já tem logoUrl ──
        if (dado.logoUrl) { jaOkCount++; continue }

        const bandeira = String(dado.bandeiraNome || dado.bandeira || '')
        const nome     = String(dado.postoNome    || dado.nome    || '')
        const logoUrl  = logoSvgPorBandeira(bandeira, nome)

        if (!logoUrl) { semLogo++; continue }

        dado.logoUrl = logoUrl
        await kv.put(kkey.name, JSON.stringify(dado), { expirationTtl: 365 * 24 * 3600 })
        logosSalvos++
      } catch { erros++ }
    }

    if (list.list_complete) { listComplete = true; break }
    cursorOut = (list as any).cursor
    if (!cursorOut) { listComplete = true; break }
  }

  return c.json({
    ok: true,
    total: processados,
    logosSalvos,
    jaOkCount,
    semLogo,
    erros,
    listComplete,
    // cursor para próxima chamada (null se acabou)
    cursor: listComplete ? null : cursorOut
  })
})

// ─── GET /api/admin/parceiros — lista TODOS os postos (R2 + KV fallback + p_teste persistido) ──
app.get('/api/admin/parceiros', async (c) => {
  const key = c.req.query('key') || c.req.header('X-Admin-Key') || ''
  const ADMIN_PASS = (c.env as Record<string,unknown>)?.ADMIN_PASS as string || 'rotaposto@admin2026'
  if (key !== ADMIN_PASS) return c.json({ erro: 'Não autorizado' }, 401)
  const kv  = getKV(c.env as any)
  const r2  = (c.env as Record<string,unknown>)?.ROTAPOSTO_R2 as R2Bucket | undefined

  const parceiros: Record<string,unknown>[] = []
  const vistos = new Set<string>()

  // 1. Listar objetos R2 com prefixo parceiro--
  if (r2) {
    try {
      const listed = await r2.list({ prefix: 'parceiro--' })
      for (const obj of listed.objects) {
        const id = obj.key.replace('parceiro--', '')
        if (id.startsWith('email_') || id.startsWith('cnpj_')) continue
        try {
          const data = await r2Get(r2, `parceiro:${id}`) as Record<string,unknown> | null
          if (data && data.id) {
            vistos.add(String(data.id))
            parceiros.push(normalizarParceiro(data, id, obj.uploaded))
          }
        } catch {}
      }
    } catch(e) { console.warn('[admin/parceiros] r2.list erro:', e) }
  }

  // 2. Fallback: varrer KV por parceiro:* (legado)
  if (kv) {
    try {
      const kvList = await kv.list({ prefix: 'parceiro:' })
      for (const k of kvList.keys) {
        const seg = k.name.replace('parceiro:', '')
        if (seg.startsWith('sess_') || seg.startsWith('email_') || seg.startsWith('cnpj_')) continue
        if (vistos.has(seg)) continue
        try {
          const raw = await kv.get(k.name)
          if (!raw) continue
          const data = JSON.parse(raw) as Record<string,unknown>
          if (data && data.id) {
            vistos.add(seg)
            parceiros.push(normalizarParceiro(data, seg, null))
          }
        } catch {}
      }
    } catch {}
  }

  // 3. p_teste: garante que está salvo no R2 (auto-persiste na primeira vez)
  if (!vistos.has('p_teste')) {
    const testeDefault: Record<string,unknown> = {
      id: 'p_teste',
      nomePosto: 'Posto Teste RotaPosto',
      email: 'teste@rotaposto.com.br',
      plano: 'premium',
      tel: '(27) 99999-9999',
      telTelemarketing: '(27) 3000-0000',
      cidade: 'Vitória',
      estado: 'ES',
      bairro: 'Centro',
      cnpj: '00.000.000/0001-00',
      bandeira: 'Independente',
      status: 'ativo',
      seloVerificado: true,
      criadoEm: '2025-01-01T00:00:00.000Z',
      precos: { gasolina: 0, gasolinaAditivada: 0, etanol: 0, diesel: 0, dieselS10: 0, gnv: 0 }
    }
    // Salvar no R2/KV para persistir
    try { await kvSetParceiro(kv, 'p_teste', testeDefault, undefined, r2) } catch {}
    parceiros.push(normalizarParceiro(testeDefault, 'p_teste', null))
  }

  // Ordenar: mais recentes primeiro
  parceiros.sort((a, b) => {
    const da = a.criadoEm ? new Date(String(a.criadoEm)).getTime() : 0
    const db = b.criadoEm ? new Date(String(b.criadoEm)).getTime() : 0
    return db - da
  })

  return c.json({ total: parceiros.length, parceiros })
})

function normalizarParceiro(data: Record<string,unknown>, id: string, uploaded: Date | null | undefined): Record<string,unknown> {
  const precos = (data.precos as Record<string,unknown>) || {}
  return {
    id: String(data.id || id),
    nomePosto:        data.nomePosto        || data.nome || '—',
    email:            data.email            || '—',
    plano:            data.plano            || 'visibilidade',
    tel:              data.tel              || data.whatsapp || '—',
    telTelemarketing: data.telTelemarketing || '—',
    cidade:           data.cidade           || '—',
    estado:           data.estado           || '—',
    bairro:           data.bairro           || '—',
    cnpj:             data.cnpj             || '—',
    bandeira:         data.bandeira         || '—',
    status:           data.status           || 'pendente',
    seloVerificado:   Boolean(data.seloVerificado),
    pinDourado:       Boolean(data.pinDourado),
    topoLista:        Boolean(data.topoLista),
    cuponsAtivos:     Boolean(data.cuponsAtivos),
    criadoEm:         data.criadoEm         || uploaded?.toISOString() || '—',
    atualizadoEm:     data.atualizadoEm     || '—',
    // Preços combustível
    precos: {
      gasolina:         Number(precos.gasolina         || 0),
      gasolinaAditivada:Number(precos.gasolinaAditivada|| 0),
      etanol:           Number(precos.etanol           || 0),
      diesel:           Number(precos.diesel           || 0),
      dieselS10:        Number(precos.dieselS10        || 0),
      gnv:              Number(precos.gnv              || 0),
    },
    // Métricas
    totalCliques:     data.totalCliques     || 0,
    totalCupons:      data.totalCupons      || 0,
    totalImpressoes:  data.totalImpressoes  || 0,
    // Foto de bandeira (só retorna se realmente salva — nunca gera URL automática)
    fotoBandeira:     data.fotoBandeira     || null,
    fotoTs:           data.fotoTs           || null,   // timestamp do último upload (cache-bust)
    fotoExterna:      data.fotoExterna      || null,   // URL externa de foto do posto (admin cola)
    endereco:         data.endereco         || {},
    lat:              data.lat              || null,
    lng:              data.lng              || null,
  }
}

// ─── PUT /api/admin/parceiros/:id — editar dados + preços do posto ─────────────
app.put('/api/admin/parceiros/:id', async (c) => {
  const key = c.req.query('key') || c.req.header('X-Admin-Key') || ''
  const ADMIN_PASS = (c.env as Record<string,unknown>)?.ADMIN_PASS as string || 'rotaposto@admin2026'
  if (key !== ADMIN_PASS) return c.json({ erro: 'Não autorizado' }, 401)
  const kv = getKV(c.env as any)
  const r2 = (c.env as Record<string,unknown>)?.ROTAPOSTO_R2 as R2Bucket | undefined
  const id = c.req.param('id')
  const body = await c.req.json() as Record<string,unknown>

  // Carregar dados atuais — se não existir, cria novo (upsert para postos vindos da ANP)
  const atual = await kvGetParceiro(kv, id, r2) as Record<string,unknown> | null
  const base: Record<string,unknown> = atual || {
    id,
    criadoEm: new Date().toISOString(),
    status: 'ativo',
    plano: 'visibilidade',
    precos: {},
    totalCliques: 0,
    totalCupons: 0,
    totalImpressoes: 0,
  }

  // Campos editáveis pelo admin
  const campos = [
    'nomePosto','email','tel','telTelemarketing',
    'cidade','estado','bairro','cnpj','bandeira',
    'plano','status','seloVerificado','pinDourado',
    'notificacoesAtivas','cuponsAtivos','topoLista',
    'fotoExterna'
  ]
  const atualizado: Record<string,unknown> = { ...base }
  for (const campo of campos) {
    if (campo in body) atualizado[campo] = body[campo]
  }
  // Preservar sempre fotoBandeira existente (nunca apagar foto salva via upload)
  if (!atualizado.fotoBandeira && base.fotoBandeira) {
    atualizado.fotoBandeira = base.fotoBandeira
  }

  // Preços combustível (objeto aninhado)
  if (body.precos && typeof body.precos === 'object') {
    const precosAntigos = ((atual?.precos) as Record<string,unknown>) || {}
    const precosNovos   = body.precos as Record<string,unknown>
    atualizado.precos = {
      gasolina:          Number(precosNovos.gasolina          ?? precosAntigos.gasolina          ?? 0),
      gasolinaAditivada: Number(precosNovos.gasolinaAditivada ?? precosAntigos.gasolinaAditivada ?? 0),
      etanol:            Number(precosNovos.etanol            ?? precosAntigos.etanol            ?? 0),
      diesel:            Number(precosNovos.diesel            ?? precosAntigos.diesel            ?? 0),
      dieselS10:         Number(precosNovos.dieselS10         ?? precosAntigos.dieselS10         ?? 0),
      gnv:               Number(precosNovos.gnv               ?? precosAntigos.gnv               ?? 0),
    }
    atualizado.precosAtualizadoEm = new Date().toISOString()
  }

  atualizado.atualizadoEm = new Date().toISOString()

  await kvSetParceiro(kv, id, atualizado, undefined, r2)

  // Manter índice CNPJ → id atualizado (permite lookup por CNPJ no /api/postos)
  const cnpjAtualizado = String(atualizado.cnpj || '').replace(/[^0-9]/g, '')
  if (cnpjAtualizado && kv) {
    try {
      await kvSetParceiro(kv, 'cnpj_' + cnpjAtualizado, { id, cnpj: cnpjAtualizado })
    } catch {}
  }

  // Atualizar senha do parceiro se fornecida pelo admin
  if (body.novaSenha && typeof body.novaSenha === 'string' && (body.novaSenha as string).length >= 6) {
    atualizado.senhaHash = hashSimples(body.novaSenha as string)
    await kvSetParceiro(kv, id, atualizado, undefined, r2)
  }

  return c.json({ ok: true, parceiro: normalizarParceiro(atualizado, id, null) })
})

// ─── POST /api/admin/parceiros/:id/convite — gera token de convite para o posto ─
app.post('/api/admin/parceiros/:id/convite', async (c) => {
  const key = c.req.query('key') || c.req.header('X-Admin-Key') || ''
  const ADMIN_PASS = (c.env as Record<string,unknown>)?.ADMIN_PASS as string || 'rotaposto@admin2026'
  if (key !== ADMIN_PASS) return c.json({ erro: 'Não autorizado' }, 401)

  const kv = getKV(c.env as any)
  const r2 = (c.env as Record<string,unknown>)?.ROTAPOSTO_R2 as R2Bucket | undefined
  const id  = c.req.param('id')

  const parceiro = await kvGetParceiro(kv, id, r2) as Record<string,unknown> | null
  if (!parceiro) return c.json({ erro: 'Posto não encontrado' }, 404)

  // Gerar token único: 32 chars hex
  const token = Array.from(crypto.getRandomValues(new Uint8Array(16)))
    .map(b => b.toString(16).padStart(2,'0')).join('')

  const convite = {
    token,
    parceiroId: id,
    nomePosto:  parceiro.nomePosto || 'Posto Parceiro',
    cidade:     parceiro.cidade || '',
    estado:     parceiro.estado || '',
    criadoEm:  new Date().toISOString(),
    expiraEm:  new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString(), // 30 dias
    usado:     false,
  }

  // Salvar convite no KV com TTL de 30 dias
  if (kv) await kv.put(`convite:${token}`, JSON.stringify(convite), { expirationTtl: 30 * 24 * 3600 })

  // Atualizar parceiro com token de convite
  const atualizado = { ...parceiro, conviteToken: token, conviteCriadoEm: convite.criadoEm }
  await kvSetParceiro(kv, id, atualizado, undefined, r2)

  const baseUrl = new URL(c.req.url).origin
  return c.json({ ok: true, token, link: `${baseUrl}/convite/${token}` })
})

