function abrirPainelEnriquecimento() {
  var p = document.getElementById('painel-enriquecimento');
  if (p) p.style.display = 'block';
}
function fecharPainelEnriquecimento() {
  var p = document.getElementById('painel-enriquecimento');
  if (p) p.style.display = 'none';
}

// ── Etapa 1: Logos por Bandeira em Massa (auto-paginado, só sem logo) ──────────────────────
async function rodarLogosEmMassa() {
  var btn = document.getElementById('btn-logos-bandeira');
  var wrap = document.getElementById('logos-prog-wrap');
  var bar  = document.getElementById('logos-prog-bar');
  var stat = document.getElementById('logos-prog-status');
  var cnt  = document.getElementById('logos-prog-count');
  if (!btn || !wrap) return;

  btn.disabled = true;
  btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Rodando…';
  wrap.style.display = 'block';
  if (bar)  bar.style.width = '5%';
  if (stat) stat.textContent = 'Iniciando…';
  if (cnt)  cnt.textContent  = '0 logos salvos';

  var totalLogos = 0, totalProcessados = 0, lote = 0;
  var cursor = null;

  try {
    while (true) {
      lote++;
      var url = '/api/admin/script/aplicar-logos-bandeira?key=' + encodeURIComponent(ADMIN_KEY) + '&limite=500';
      if (cursor) url += '&cursor=' + encodeURIComponent(cursor);
      var r = await fetch(url, { method: 'POST' });
      var d = await r.json();
      if (!r.ok || !d.ok) throw new Error(d.erro || 'Erro no servidor');

      totalLogos      += d.logosSalvos || 0;
      totalProcessados += d.total      || 0;

      if (cnt)  cnt.textContent  = totalLogos + ' logos salvos';
      if (stat) stat.textContent = 'Lote ' + lote + ' — ' + totalProcessados + ' postos varridos';

      // Progresso animado: avança enquanto não sabe o total
      if (bar) {
        var pct = d.listComplete ? 100 : Math.min(95, 5 + lote * 8);
        bar.style.width = pct + '%';
      }

      cursor = d.cursor || null;
      if (d.listComplete || !cursor) break;

      // Pausa leve entre lotes para não travar
      await new Promise(function(res) { setTimeout(res, 200); });
    }

    if (bar)  bar.style.width = '100%';
    if (stat) stat.innerHTML  = '<span style="color:#FFD600">✅ Concluído!</span> ' + totalProcessados + ' postos varridos';
    if (cnt)  cnt.innerHTML   = '<b style="color:#FFD600">' + totalLogos + '</b> logos salvos';
    showToast('🏷️ ' + totalLogos + ' logos aplicados em ' + totalProcessados + ' postos!', 'ok');
  } catch(e) {
    if (stat) stat.innerHTML = '<span style="color:#FF5252">❌ Erro: ' + (e.message||e) + '</span>';
    showToast('❌ Erro logos: ' + (e.message||e), 'err');
  } finally {
    btn.disabled = false;
    btn.innerHTML = '<i class="fas fa-play"></i> Aplicar logos agora';
  }
}

// ── Etapa 2: Fotos Google em Massa (auto-paginado, só sem foto) ────────────────────────────
var _fotosGoogleRodando = false;
var _fotosGooglePausar  = false;

function pausarFotosGoogle() {
  _fotosGooglePausar = true;
  var btn = document.getElementById('btn-fotos-google-pause');
  if (btn) btn.innerHTML = '<i class="fas fa-hourglass-half"></i> Pausando…';
}

async function rodarFotosGoogleEmMassa() {
  if (_fotosGoogleRodando) return;
  _fotosGoogleRodando = true;
  _fotosGooglePausar  = false;

  var btnPlay  = document.getElementById('btn-fotos-google');
  var btnPause = document.getElementById('btn-fotos-google-pause');
  var wrap     = document.getElementById('fotos-prog-wrap');
  var bar      = document.getElementById('fotos-prog-bar');
  var stat     = document.getElementById('fotos-prog-status');
  var cnt      = document.getElementById('fotos-prog-count');
  var loteEl   = document.getElementById('fotos-prog-lote');
  var logEl    = document.getElementById('fotos-log');

  if (!btnPlay || !wrap) { _fotosGoogleRodando = false; return; }

  btnPlay.disabled = true;
  btnPlay.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Rodando…';
  if (btnPause) { btnPause.style.display = 'flex'; btnPause.innerHTML = '<i class="fas fa-pause"></i> Pausar'; }
  wrap.style.display = 'block';
  if (logEl) logEl.style.display = 'block';
  if (bar)   bar.style.width = '2%';
  if (stat)  stat.textContent = 'Iniciando…';
  if (cnt)   cnt.textContent  = '0 fotos salvas';

  var totalFotos = 0, totalLotes = 0, totalProcessados = 0;
  var cursor = null;

  function addLog(txt) {
    if (!logEl) return;
    logEl.innerHTML = txt + '<br>' + logEl.innerHTML;
  }

  try {
    while (true) {
      if (_fotosGooglePausar) {
        if (stat) stat.innerHTML = '<span style="color:#FFA726">⏸ Pausado — clique em Buscar fotos para continuar</span>';
        if (btnPause) btnPause.style.display = 'none';
        break;
      }

      totalLotes++;
      var url = '/api/admin/script/auto-fotos-postos-band?key=' + encodeURIComponent(ADMIN_KEY) + '&limite=30';
      if (cursor) url += '&cursor=' + encodeURIComponent(cursor);
      // Não passa forcar=true — só processa quem não tem foto
      var r = await fetch(url, { method: 'POST' });
      var d = await r.json();
      if (!r.ok || !d.ok) throw new Error(d.erro || 'Erro no servidor');

      totalFotos       += d.fotosSalvas || 0;
      totalProcessados += d.total       || 0;

      if (cnt)    cnt.textContent    = totalFotos + ' fotos salvas';
      if (loteEl) loteEl.textContent = 'Lote ' + totalLotes + ' | ' + totalProcessados + ' postos processados | Já ok: ' + (d.jaOkCount || 0);
      if (stat)   stat.textContent   = 'Buscando… lote ' + totalLotes;

      // Log das últimas ações do lote
      var novos = (d.resultados || []).filter(function(x) { return x.status === 'atualizado'; });
      if (novos.length) {
        var linha = novos.map(function(x) {
          var ac = (x.acoes || []).map(function(a) {
            if (a === 'foto_google:ok')             return '📸✓';
            if (a === 'foto_google:nao_encontrada') return '📸✗';
            if (a.startsWith('logo_svg:'))          return '🏷️';
            return a;
          }).join(' ');
          return '<span style="color:rgba(255,255,255,0.7)">' + (x.nome || x.postoId).substring(0,28) + '</span> ' + ac;
        }).join(' &nbsp;·&nbsp; ');
        addLog(linha);
      }

      // Progresso animado
      if (bar) {
        var pct = d.listComplete ? 100 : Math.min(95, 2 + totalLotes * 3);
        bar.style.width = pct + '%';
      }

      cursor = d.cursor || null;
      if (d.listComplete || !cursor) {
        if (bar)  bar.style.width = '100%';
        if (stat) stat.innerHTML  = '<span style="color:#69F0AE">✅ Todos os postos processados!</span>';
        if (loteEl) loteEl.textContent = totalProcessados + ' postos | ' + totalFotos + ' fotos salvas | ' + totalLotes + ' lotes';
        showToast('📸 ' + totalFotos + ' fotos Google salvas em ' + totalProcessados + ' postos!', 'ok');
        break;
      }

      // Pausa entre lotes (Google Places rate limit)
      await new Promise(function(res) { setTimeout(res, 400); });
    }
  } catch(e) {
    if (stat) stat.innerHTML = '<span style="color:#FF5252">❌ Erro: ' + (e.message||e) + '</span>';
    showToast('❌ Erro fotos Google: ' + (e.message||e), 'err');
  } finally {
    _fotosGoogleRodando = false;
    _fotosGooglePausar  = false;
    if (btnPlay)  { btnPlay.disabled = false; btnPlay.innerHTML = '<i class="fas fa-play"></i> Buscar fotos'; }
    if (btnPause) btnPause.style.display = 'none';
  }
}

// ─── Auto-fotos para seção ANP — mantido para compatibilidade (chamado após salvar posto ANP) ─
async function rodarAutoFotosANP() {
  // Redireciona para o painel de enriquecimento
  abrirPainelEnriquecimento();
}

// ─── Upload de logo para postos do mapa (google-*, osm-*, anp-*) ─────────────
var _logoBandPostoId = null;
var _logoBandFile = null;

function abrirUploadLogoPostoBand(postoId, nome) {
  _logoBandPostoId = postoId;
  _logoBandFile = null;
  document.getElementById('logo-band-nome').textContent = nome || postoId;
  // Resetar UI
  var inp = document.getElementById('logo-band-input');
  if (inp) inp.value = '';
  var st = document.getElementById('logo-band-status');
  if (st) { st.style.display='none'; st.textContent=''; }
  var btn = document.getElementById('logo-band-btn-enviar');
  if (btn) { btn.disabled=true; btn.style.opacity='0.4'; }
  var img = document.getElementById('logo-band-preview-img');
  var wrap = document.getElementById('logo-band-preview-wrap');
  if (img) { img.src=''; img.style.display='none'; }
  if (wrap) wrap.style.fontSize='28px';
  document.getElementById('modal-logo-posto-band').style.display='flex';
}

function fecharModalLogoBand() {
  document.getElementById('modal-logo-posto-band').style.display='none';
  _logoBandPostoId = null;
  _logoBandFile = null;
}

function logoHandleChange(inp) {
  var f = inp.files && inp.files[0];
  if (!f) return;
  var st = document.getElementById('logo-band-status');
  if (f.size > 3 * 1024 * 1024) {
    if (st) { st.textContent='⚠️ Imagem muito grande (máx. 3 MB).'; st.style.color='#FF5252'; st.style.display='block'; }
    return;
  }
  _logoBandFile = f;
  var reader = new FileReader();
  reader.onload = function(e) {
    var img = document.getElementById('logo-band-preview-img');
    var wrap = document.getElementById('logo-band-preview-wrap');
    if (img) { img.src = e.target.result; img.style.display='block'; }
    if (wrap) wrap.style.fontSize='0';
  };
  reader.readAsDataURL(f);
  if (st) { st.textContent='📸 ' + f.name + ' — clique em "Enviar Logo".'; st.style.color='rgba(255,255,255,0.5)'; st.style.display='block'; }
  var btn = document.getElementById('logo-band-btn-enviar');
  if (btn) { btn.disabled=false; btn.style.opacity='1'; }
}

async function enviarLogoBand() {
  if (!_logoBandFile || !_logoBandPostoId) return;
  var st  = document.getElementById('logo-band-status');
  var btn = document.getElementById('logo-band-btn-enviar');
  if (btn) { btn.disabled=true; btn.innerHTML='<i class="fas fa-spinner fa-spin"></i> Enviando...'; }
  if (st)  { st.textContent='⏳ Enviando logo...'; st.style.color='rgba(255,255,255,0.5)'; st.style.display='block'; }
  try {
    var form = new FormData();
    form.append('logo', _logoBandFile);
    form.append('postoId', _logoBandPostoId);
    var r = await fetch('/api/admin/posto-band/logo?key=' + encodeURIComponent(ADMIN_KEY), {
      method: 'POST', body: form
    });
    var d = await r.json();
    if (!r.ok || !d.ok) throw new Error(d.erro || 'Erro ao enviar');
    if (st) { st.textContent='✅ Logo salvo! Já aparece no mapa e lista.'; st.style.color='#00C853'; }
    showToast('✅ Logo do posto salvo com sucesso!', 'ok');
    var logoFinal = d.logoUrl + '?t=' + Date.now();
    // Atualizar preview no modal
    var img = document.getElementById('logo-band-preview-img');
    if (img) { img.src = logoFinal; img.style.display='block'; }
    _logoBandFile = null;
    var inp = document.getElementById('logo-band-input');
    if (inp) inp.value = '';
    // Atualizar célula da tabela imediatamente (sem recarregar toda a lista)
    // A tabela tem células na coluna 0 de cada linha com data-posto-id
    var rows = document.querySelectorAll('#postos-tbody tr');
    rows.forEach(function(row) {
      var btn = row.querySelector('button[onclick*="' + _logoBandPostoId + '"]');
      if (btn) {
        var cell = row.querySelector('td:first-child');
        if (cell) {
          var _img = document.createElement('img');
          _img.src = logoFinal;
          _img.style.cssText = 'width:32px;height:32px;object-fit:contain;border-radius:6px;background:#fff;padding:2px';
          _img.onerror = function(){ this.style.display='none'; };
          cell.innerHTML = '';
          cell.appendChild(_img);
        }
      }
    });
    // Fechar modal após 1.5s e recarregar lista
    setTimeout(function() {
      fecharModalLogoBand();
      carregarPostos();
    }, 1500);
  } catch(e) {
    if (st) { st.textContent='❌ ' + (e.message||e); st.style.color='#FF5252'; }
    showToast('❌ Erro ao enviar logo: ' + (e.message||e), 'err');
  } finally {
    if (btn) { btn.disabled=false; btn.style.opacity='1'; btn.innerHTML='<i class="fas fa-cloud-upload-alt"></i> Enviar Logo'; }
  }
}

// ─── Toggle ativar/desativar posto direto na tabela ───────────────────────────
async function toggleStatusParceiro(el) {
  const id = el.dataset.pid;
  const statusAtual = el.dataset.status || 'ativo';
  const novoStatus = statusAtual === 'ativo' ? 'inativo' : 'ativo';
  const isAtivo = novoStatus === 'ativo';
  // Feedback visual imediato (spinner enquanto salva)
  const htmlOriginal = el.innerHTML;
  el.innerHTML = '<i class="fas fa-spinner fa-spin" style="margin-right:4px"></i>...';
  el.style.pointerEvents = 'none';
  try {
    const res = await fetch('/api/admin/parceiros/' + encodeURIComponent(id) + '?key=' + encodeURIComponent(ADMIN_KEY), {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ status: novoStatus })
    });
    const d = await res.json();
    if (!res.ok || d.erro) throw new Error(d.erro || 'Erro ao salvar');
    // Atualiza visual inline
    el.dataset.status = novoStatus;
    el.style.background = isAtivo ? 'rgba(105,240,174,0.15)' : 'rgba(255,82,82,0.12)';
    el.style.color = isAtivo ? '#69F0AE' : '#FF5252';
    el.style.border = isAtivo ? '1px solid rgba(105,240,174,0.3)' : '1px solid rgba(255,82,82,0.25)';
    el.innerHTML = '<i class="fas ' + (isAtivo ? 'fa-toggle-on' : 'fa-toggle-off') + '" style="margin-right:4px"></i>' + (isAtivo ? 'Ativo' : 'Inativo');
    // Atualiza _parceiros em memória
    const p = _parceiros.find(x => x.id === id);
    if (p) p.status = novoStatus;
    showToast(isAtivo ? '✅ Posto ativado!' : '⚠️ Posto desativado!', isAtivo ? 'ok' : '');
  } catch(e) {
    // Restaura visual original em caso de erro
    el.innerHTML = htmlOriginal;
    showToast('❌ Erro: ' + e.message, 'err');
  } finally {
    el.style.pointerEvents = '';
  }
}

// ─── Modal Editar Parceiro ────────────────────────────────────────────────────
let _parceiroEditandoId = null;
let _postoVeioDaANP = false; // flag: posto foi selecionado via "Usar dados" na seção ANP

// Popula o select de planos do modal de posto com os planos B2B de postos
async function popularSelectPlanosModal(planoAtual) {
  const sel = document.getElementById('ep-plano');
  if (!sel) return;
  // Usa _planosData (planos de postos) — carrega da rota planos-posto se vazio
  let planos = _planosData || [];
  if (!planos.length) {
    try {
      const r = await fetch('/api/admin/planos-posto?key=' + encodeURIComponent(ADMIN_KEY));
      const d = await r.json();
      planos = d.planos || [];
      _planosData = planos;
    } catch {}
  }
  if (!planos.length) {
    // Fallback estático
    sel.innerHTML = '<option value="visibilidade">Visibilidade (Grátis)</option>'
      + '<option value="basico">Básico</option>'
      + '<option value="premium">Premium</option>'
      + '<option value="pro">Pro</option>';
  } else {
    sel.innerHTML = planos.filter(p => p.ativo !== false).map(p => {
      const valorFmt = p.valor === 0 ? 'Grátis' : 'R$ ' + (p.valor / 100).toFixed(2).replace('.',',') + '/' + (p.ciclo === 'monthly' ? 'mês' : p.ciclo === 'yearly' ? 'ano' : p.ciclo === 'trial' ? 'teste' : '∞');
      return '<option value="' + p.id + '">' + (p.emoji || '') + ' ' + p.nome + ' — ' + valorFmt + '</option>';
    }).join('');
  }
  if (planoAtual) sel.value = planoAtual;
  if (!sel.value && sel.options.length) sel.value = sel.options[0].value;
  // Atualiza preview logo após popular
  epAtualizarPreviewPlano();
}

// Atualiza o preview visual de benefícios ao trocar o plano no modal do posto
function epAtualizarPreviewPlano() {
  const sel     = document.getElementById('ep-plano');
  const preview = document.getElementById('ep-plano-preview');
  const vazio   = document.getElementById('ep-plano-vazio');
  if (!sel || !preview || !vazio) return;

  const planoId = sel.value;
  const plano   = (_planosData || []).find(x => x.id === planoId);

  if (!plano) {
    preview.style.display = 'none';
    vazio.style.display   = 'block';
    return;
  }

  vazio.style.display   = 'none';
  preview.style.display = 'block';

  const cor        = plano.cor || '#FF6D00';
  const beneficios = Array.isArray(plano.beneficios) ? plano.beneficios : [];
  const features   = Array.isArray(plano.features)   ? plano.features   : [];
  const valorFmt   = plano.valor === 0 ? 'Grátis' : 'R$ ' + (plano.valor / 100).toFixed(2).replace('.', ',');
  const cicloLabel = { forever:'para sempre', monthly:'/mês', yearly:'/ano', trial:'período de teste' };
  const cicloFmt   = cicloLabel[plano.ciclo] || plano.ciclo;

  // Badge de período
  let periodoBadge = '';
  if (plano.ciclo === 'trial' && plano.diasTeste > 0) {
    periodoBadge = '<span style="background:rgba(255,214,0,0.15);color:#FFD600;border:1px solid rgba(255,214,0,0.3);border-radius:100px;padding:2px 10px;font-size:10px;font-weight:800">⏱️ ' + plano.diasTeste + ' dias de teste</span>';
  } else if (plano.ciclo === 'forever') {
    periodoBadge = '<span style="background:rgba(0,200,83,0.12);color:#00C853;border:1px solid rgba(0,200,83,0.25);border-radius:100px;padding:2px 10px;font-size:10px;font-weight:800">♾️ Para sempre</span>';
  } else if (plano.valor > 0) {
    periodoBadge = '<span style="background:rgba(66,165,245,0.1);color:#42A5F5;border:1px solid rgba(66,165,245,0.2);border-radius:100px;padding:2px 10px;font-size:10px;font-weight:800">💳 ' + cicloFmt + '</span>';
  }

  // Benefícios fixos do plano
  const bAtivos = BENEFICIOS_POSTO.filter(b => beneficios.includes(b.id));
  const bHTML = bAtivos.length > 0
    ? bAtivos.map(b =>
        '<div style="display:flex;align-items:center;gap:8px;font-size:11px;color:rgba(255,255,255,0.8)">'
        + '<i class="' + b.icon + '" style="color:' + cor + ';width:14px;text-align:center;font-size:11px;flex-shrink:0"></i>'
        + '<span>' + b.label + '</span>'
        + '</div>'
      ).join('')
    : '';

  // Features extras (legado)
  const fAtivos = features.filter(f => f.incluido);
  const fHTML = fAtivos.length > 0
    ? fAtivos.map(f =>
        '<div style="display:flex;align-items:center;gap:8px;font-size:11px;color:rgba(255,255,255,0.65)">'
        + '<i class="fas fa-check" style="color:' + cor + ';width:14px;text-align:center;font-size:10px;flex-shrink:0"></i>'
        + '<span>' + f.texto + '</span>'
        + '</div>'
      ).join('')
    : '';

  const totalBeneficios = bAtivos.length + fAtivos.length;

  preview.innerHTML =
    // Cabeçalho do plano
    '<div style="display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:8px;margin-bottom:12px">'
    + '<div style="display:flex;align-items:center;gap:10px">'
    +   '<div style="font-size:28px;line-height:1">' + (plano.emoji || '📦') + '</div>'
    +   '<div>'
    +     '<div style="font-size:14px;font-weight:900;color:#fff">' + plano.nome + '</div>'
    +     '<div style="font-size:18px;font-weight:900;color:' + cor + ';line-height:1.2">' + valorFmt
    +       (plano.valor > 0 ? '<span style="font-size:11px;color:rgba(255,255,255,0.35)"> ' + cicloFmt + '</span>' : '')
    +     '</div>'
    +   '</div>'
    + '</div>'
    + periodoBadge
    + '</div>'
    // Benefícios
    + (totalBeneficios > 0
      ? '<div style="background:rgba(0,0,0,0.2);border-radius:10px;padding:12px">'
        + '<div style="font-size:10px;font-weight:800;color:rgba(255,255,255,0.4);text-transform:uppercase;letter-spacing:.5px;margin-bottom:8px">Benefícios incluídos</div>'
        + '<div style="display:grid;grid-template-columns:1fr 1fr;gap:6px">' + bHTML + fHTML + '</div>'
        + '</div>'
      : '<div style="color:rgba(255,255,255,0.25);font-size:11px;font-style:italic;text-align:center;padding:8px">Nenhum benefício configurado neste plano</div>'
    )
    ;
}

// Navega para a aba de Produtos & Planos e fecha o modal do posto
function irParaGerenciarPlanos() {
  fecharModalParceiro();
  setTimeout(() => {
    const navBtn = document.getElementById('nav-planos');
    if (navBtn) navBtn.click();
  }, 150);
}

// Navega para Produtos & Planos e abre o modal de edição do plano específico
function irParaEditarPlano(planoId) {
  fecharModalParceiro();
  setTimeout(() => {
    const navBtn = document.getElementById('nav-planos');
    if (navBtn) navBtn.click();
    setTimeout(() => { abrirModalEditarPlano(planoId); }, 400);
  }, 150);
}

function abrirModalEditarParceiro(id) {
  const p = _parceiros.find(x => x.id === id);
  if (!p) return;
  _parceiroEditandoId = id;
  _postoVeioDaANP = false; // edição normal, não veio da ANP
  const pr = p.precos || {};
  const end = p.endereco || {};

  document.getElementById('ep-id-display').textContent = 'ID: ' + id;
  document.getElementById('ep-nomePosto').value          = p.nomePosto        !== '—' ? (p.nomePosto        || '') : '';
  document.getElementById('ep-email').value              = p.email            !== '—' ? (p.email            || '') : '';
  document.getElementById('ep-tel').value                = p.tel              !== '—' ? (p.tel              || '') : '';
  document.getElementById('ep-telTelemarketing').value   = p.telTelemarketing !== '—' ? (p.telTelemarketing || '') : '';
  document.getElementById('ep-cnpj').value               = p.cnpj             !== '—' ? (p.cnpj             || '') : '';
  document.getElementById('ep-status').value             = p.status           || 'pendente';
  // Bandeira — select
  const epBand = document.getElementById('ep-bandeira');
  const bandVal = p.bandeira !== '—' ? (p.bandeira || '') : '';
  for (let o of epBand.options) { if (o.value === bandVal || o.text === bandVal) { o.selected = true; break; } }
  // Endereço
  document.getElementById('ep-cep').value    = end.cep    || (p.cep    !== '—' ? (p.cep    || '') : '');
  document.getElementById('ep-rua').value    = end.rua    || (p.rua    !== '—' ? (p.rua    || '') : '');
  document.getElementById('ep-num').value    = end.numero || '';
  document.getElementById('ep-bairro').value = end.bairro || (p.bairro !== '—' ? (p.bairro || '') : '');
  document.getElementById('ep-cidade').value = end.cidade || (p.cidade !== '—' ? (p.cidade || '') : '');
  const epEst = document.getElementById('ep-estado');
  const estVal = end.estado || (p.estado !== '—' ? (p.estado || '') : '');
  for (let o of epEst.options) { if (o.value === estVal || o.text === estVal) { o.selected = true; break; } }
  // Lat / Lng
  document.getElementById('ep-lat').value = p.lat ? String(p.lat) : '';
  document.getElementById('ep-lng').value = p.lng ? String(p.lng) : '';
  // Mapa — se tem coords, mostrar
  const epMapaWrap = document.getElementById('ep-mapa-wrap');
  epMapaWrap.style.display = 'none';
  document.getElementById('ep-geo-status').textContent = '';
  // Aviso de sem coordenadas
  const avisoSemCoords = document.getElementById('ep-sem-coords-aviso');
  if (avisoSemCoords) avisoSemCoords.style.display = (p.lat && p.lng) ? 'none' : 'block';
  if (p.lat && p.lng) {
    _epAtualizarMapa(p.lat, p.lng, [end.rua || p.rua, end.numero, end.cidade || p.cidade].filter(Boolean).join(', '));
  }
  document.getElementById('ep-seloVerificado').checked   = !!p.seloVerificado;
  document.getElementById('ep-pinDourado').checked       = !!p.pinDourado;
  document.getElementById('ep-topoLista').checked        = !!p.topoLista;
  document.getElementById('ep-cuponsAtivos').checked     = !!p.cuponsAtivos;
  // Preços
  document.getElementById('ep-preco-gasolina').value          = pr.gasolina          > 0 ? pr.gasolina          : '';
  document.getElementById('ep-preco-gasolinaAditivada').value = pr.gasolinaAditivada > 0 ? pr.gasolinaAditivada : '';
  document.getElementById('ep-preco-etanol').value            = pr.etanol            > 0 ? pr.etanol            : '';
  document.getElementById('ep-preco-diesel').value            = pr.diesel            > 0 ? pr.diesel            : '';
  document.getElementById('ep-preco-dieselS10').value         = pr.dieselS10         > 0 ? pr.dieselS10         : '';
  document.getElementById('ep-preco-gnv').value               = pr.gnv               > 0 ? pr.gnv               : '';

  popularSelectPlanosModal(p.plano || '');
  document.getElementById('ep-deletar-btn').style.display = (id === 'p_teste') ? 'none' : 'inline-flex';

  // Foto de bandeira — resetar e carregar se existir
  _epFotoFile = null;
  // Limpar campo de nova senha sempre que o modal abre
  const epNovaSenha = document.getElementById('ep-nova-senha');
  if (epNovaSenha) epNovaSenha.value = '';
  const epFotoInput = document.getElementById('ep-foto-input');
  if (epFotoInput) epFotoInput.value = '';
  const epFotoStatus = document.getElementById('ep-foto-status');
  if (epFotoStatus) { epFotoStatus.style.display='none'; epFotoStatus.textContent=''; }
  const epFotoBtnEnviar = document.getElementById('ep-foto-btn-enviar');
  if (epFotoBtnEnviar) epFotoBtnEnviar.style.display='none';
  // Preview da foto atual
  const epFotoImg = document.getElementById('ep-foto-preview-img');
  const epFotoWrap = document.getElementById('ep-foto-preview-wrap');
  if (epFotoImg && epFotoWrap) {
    // Prioridade: fotoBandeira real → SVG da bandeira cadastrada
    var fotoReal = p.fotoBandeira && (
      p.fotoBandeira.startsWith('http') ||
      p.fotoBandeira.startsWith('/api/parceiros') ||
      p.fotoBandeira.startsWith('/api/posto')
    );
    var svgFallback = _adminBandeiraLogoUrl(p.bandeira || p.nomePosto);
    if (fotoReal) {
      epFotoImg.src = p.fotoBandeira + '?t=' + Date.now();
      epFotoImg.style.display = 'block';
      epFotoImg.style.padding = '0';
      epFotoImg.style.objectFit = 'cover';
      epFotoWrap.style.fontSize = '0';
    } else if (svgFallback) {
      epFotoImg.src = svgFallback;
      epFotoImg.style.display = 'block';
      epFotoImg.style.padding = '10px';
      epFotoImg.style.objectFit = 'contain';
      epFotoWrap.style.fontSize = '0';
    } else {
      epFotoImg.src = '';
      epFotoImg.style.display = 'none';
      epFotoWrap.style.fontSize = '28px';
    }
  }

  // Foto externa (URL colada pelo admin)
  const epFotoExterna = document.getElementById('ep-fotoExterna');
  if (epFotoExterna) epFotoExterna.value = p.fotoExterna || '';
  epPreviewFotoExterna(p.fotoExterna || '');

  const _mel = document.getElementById('modal-parceiro-edit');
  _mel.style.display = 'flex'; _mel.scrollTop = 0;
  const _min = _mel.querySelector('.modal-inner'); if (_min) _min.scrollTop = 0;
}

// ── Foto de bandeira no Admin ─────────────────────────────
var _epFotoFile = null;

function epHandleFotoChange(inp) {
  const f = inp.files && inp.files[0];
  if (!f) return;
  const st  = document.getElementById('ep-foto-status');
  const btn = document.getElementById('ep-foto-btn-enviar');
  if (f.size > 3 * 1024 * 1024) {
    if (st) { st.textContent='⚠️ Imagem muito grande (máx. 3 MB).'; st.style.color='#FF5252'; st.style.display='block'; }
    return;
  }
  _epFotoFile = f;
  const reader = new FileReader();
  reader.onload = function(e) {
    const img = document.getElementById('ep-foto-preview-img');
    const wrap = document.getElementById('ep-foto-preview-wrap');
    if (img) { img.src = e.target.result; img.style.display='block'; }
    if (wrap) wrap.style.fontSize='0';
  };
  reader.readAsDataURL(f);
  if (st) { st.textContent='📸 ' + f.name + ' — clique em "Enviar foto".'; st.style.color='rgba(255,255,255,0.5)'; st.style.display='block'; }
  if (btn) btn.style.display='inline-flex';
}

async function epUploadFotoBandeira() {
  if (!_epFotoFile || !_parceiroEditandoId) return;
  const st  = document.getElementById('ep-foto-status');
  const btn = document.getElementById('ep-foto-btn-enviar');
  if (btn) { btn.disabled=true; btn.innerHTML='<i class="fas fa-spinner fa-spin"></i> Enviando...'; }
  if (st)  { st.textContent='⏳ Enviando foto...'; st.style.color='rgba(255,255,255,0.5)'; st.style.display='block'; }
  try {
    const form = new FormData();
    form.append('foto', _epFotoFile);
    form.append('postoId', _parceiroEditandoId);
    const r = await fetch('/api/parceiros/foto-bandeira?key=' + encodeURIComponent(ADMIN_KEY), {
      method: 'POST', body: form
    });
    const d = await r.json();
    if (!r.ok || !d.ok) throw new Error(d.erro || 'Erro ao enviar');
    if (st) { st.textContent='✅ Foto salva! Já aparece no mapa e lista para os usuários.'; st.style.color='#00C853'; }
    _epFotoFile = null;
    if (btn) btn.style.display='none';
    // Atualiza no objeto _parceiros local
    const idx = _parceiros.findIndex(x => x.id === _parceiroEditandoId);
    // Usa fotoUrlComTs do servidor (inclui ?v=uploadTs) — garante cache-bust consistente
    const fotoUrlComTs = d.fotoUrlComTs || (d.fotoUrl ? d.fotoUrl + '?t=' + Date.now() : null);
    if (idx !== -1 && fotoUrlComTs) _parceiros[idx].fotoBandeira = fotoUrlComTs;
    // Atualiza o preview com a nova foto (sem cache)
    const previewImg = document.getElementById('ep-foto-preview-img');
    const previewWrap = document.getElementById('ep-foto-preview-wrap');
    if (previewImg && fotoUrlComTs) {
      previewImg.src = fotoUrlComTs;
      previewImg.style.display = 'block';
      previewImg.style.padding = '0';
      previewImg.style.objectFit = 'cover';
      if (previewWrap) previewWrap.style.fontSize = '0';
    }
    // Recarregar linha da tabela admin para refletir nova foto imediatamente
    try { if (typeof carregarParceiros === 'function') carregarParceiros(); } catch {}
  } catch(e) {
    if (st) { st.textContent='❌ ' + e.message; st.style.color='#FF5252'; }
  } finally {
    if (btn) { btn.disabled=false; btn.innerHTML='<i class="fas fa-cloud-upload-alt"></i> Enviar foto'; }
    const inp = document.getElementById('ep-foto-input');
    if (inp) inp.value='';
  }
}

// ── Foto externa (URL colada pelo admin) ──────────────────
function epPreviewFotoExterna(url) {
  const prev = document.getElementById('ep-foto-externa-preview');
  const img  = document.getElementById('ep-foto-externa-img');
  if (!prev || !img) return;
  if (url && url.startsWith('http')) {
    img.src = url;
    prev.style.display = 'flex';
    prev.style.alignItems = 'center';
    prev.style.gap = '8px';
  } else {
    prev.style.display = 'none';
  }
}

async function epSalvarFotoExterna() {
  const inp = document.getElementById('ep-fotoExterna');
  if (!inp) return;
  const url = inp.value.trim();
  if (!_parceiroEditandoId) { showToast('❌ Nenhum posto selecionado', 'err'); return; }
  if (url && !url.startsWith('http')) { showToast('⚠️ URL inválida. Deve começar com http', 'err'); return; }
  try {
    const r = await fetch('/api/admin/parceiros/' + encodeURIComponent(_parceiroEditandoId) + '?key=' + encodeURIComponent(ADMIN_KEY), {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ fotoExterna: url || null })
    });
    const d = await r.json();
    if (!r.ok || !d.ok) throw new Error(d.erro || 'Erro ao salvar');
    const idx = _parceiros.findIndex(x => x.id === _parceiroEditandoId);
    if (idx !== -1) _parceiros[idx].fotoExterna = url || null;
    showToast(url ? '✅ URL de foto salva! Aparece na página do posto.' : '✅ Foto externa removida.', 'ok');
  } catch(e) {
    showToast('❌ ' + e.message, 'err');
  }
}

// ── Helpers de formatação (aplicados no onblur) ───────────
// oninput: APENAS filtra não-dígitos — sem reformatar durante digitação
// onblur:  aplica máscara completa — sem bug de cursor
function _fmtCnpj(raw) {
  const v = (raw||'').replace(/[^0-9]/g,'').slice(0,14);
  if (v.length === 14) return v.slice(0,2)+'.'+v.slice(2,5)+'.'+v.slice(5,8)+'/'+v.slice(8,12)+'-'+v.slice(12);
  return v;
}
function _fmtCep(raw) {
  const v = (raw||'').replace(/[^0-9]/g,'').slice(0,8);
  return v.length === 8 ? v.slice(0,5)+'-'+v.slice(5) : v;
}
function _fmtTel(raw) {
  const v = (raw||'').replace(/[^0-9]/g,'').slice(0,11);
  if (v.length === 11) return '('+v.slice(0,2)+') '+v.slice(2,7)+'-'+v.slice(7);
  if (v.length === 10) return '('+v.slice(0,2)+') '+v.slice(2,6)+'-'+v.slice(6);
  return v;
}
// oninput — só dígitos, sem reformatar
function epMaskCnpj(inp) { inp.value = inp.value.replace(/[^0-9]/g,'').slice(0,14); }
function epBlurCnpj(inp)  { inp.value = _fmtCnpj(inp.value); }
function epMaskCep(inp)   { inp.value = inp.value.replace(/[^0-9]/g,'').slice(0,8); }
function epBlurCep(inp)   { inp.value = _fmtCep(inp.value); }

async function epBuscarCep() {
  const cep = (document.getElementById('ep-cep').value||'').replace(/[^0-9]/g,'');
  if (cep.length !== 8) return;
  const stat = document.getElementById('ep-geo-status');
  stat.textContent = '🔍 Buscando CEP...';
  try {
    const r = await fetch('https://viacep.com.br/ws/' + cep + '/json/');
    const d = await r.json();
    if (d.erro) { stat.textContent = '❌ CEP não encontrado.'; return; }
    document.getElementById('ep-rua').value    = d.logradouro || '';
    document.getElementById('ep-bairro').value = d.bairro     || '';
    document.getElementById('ep-cidade').value = d.localidade || '';
    const epEst = document.getElementById('ep-estado');
    for (let o of epEst.options) { if (o.value === d.uf || o.text === d.uf) { o.selected = true; break; } }
    stat.textContent = '✅ CEP encontrado. Adicione o número e clique em Localizar.';
    stat.style.color = '#69F0AE';
  } catch { stat.textContent = '❌ Erro ao buscar CEP.'; }
}

async function epGeocodificar() {
  const rua    = document.getElementById('ep-rua').value.trim();
  const num    = document.getElementById('ep-num').value.trim();
  const cidade = document.getElementById('ep-cidade').value.trim();
  const estado = document.getElementById('ep-estado').value.trim();
  const stat   = document.getElementById('ep-geo-status');
  if (!rua || !cidade) { stat.textContent = '⚠️ Preencha a rua e cidade antes de localizar.'; stat.style.color='#FF5252'; return; }
  const endStr = [rua, num, cidade, estado, 'Brasil'].filter(Boolean).join(', ');
  stat.textContent = '🔍 Geocodificando...'; stat.style.color = 'rgba(255,255,255,0.4)';
  try {
    const url = 'https://nominatim.openstreetmap.org/search?format=json&limit=1&q=' + encodeURIComponent(endStr);
    const r = await fetch(url, { headers: { 'Accept-Language':'pt-BR' } });
    const d = await r.json();
    if (!d.length) { stat.textContent = '❌ Endereço não localizado. Tente ajustar a rua ou cidade.'; stat.style.color='#FF5252'; return; }
    const lat = parseFloat(d[0].lat);
    const lng = parseFloat(d[0].lon);
    document.getElementById('ep-lat').value = lat.toFixed(6);
    document.getElementById('ep-lng').value = lng.toFixed(6);
    stat.textContent = '✅ Localizado: ' + lat.toFixed(5) + ', ' + lng.toFixed(5);
    stat.style.color = '#69F0AE';
    const avisoCoords = document.getElementById('ep-sem-coords-aviso');
    if (avisoCoords) avisoCoords.style.display = 'none';
    _epAtualizarMapa(lat, lng, endStr);
  } catch(e) { stat.textContent = '❌ Erro: ' + e.message; stat.style.color = '#FF5252'; }
}

function _epAtualizarMapa(lat, lng, label) {
  const wrap = document.getElementById('ep-mapa-wrap');
  const frame = document.getElementById('ep-mapa-frame');
  const lbl = document.getElementById('ep-mapa-label');
  if (!wrap || !frame) return;
  frame.src = 'https://www.openstreetmap.org/export/embed.html?bbox=' +
    (lng-0.003) + '%2C' + (lat-0.003) + '%2C' + (lng+0.003) + '%2C' + (lat+0.003) +
    '&layer=mapnik&marker=' + lat + '%2C' + lng;
  if (lbl) lbl.textContent = label || 'Localização confirmada';
  wrap.style.display = 'block';
}

function fecharModalParceiro() {
  document.getElementById('modal-parceiro-edit').style.display = 'none';
  document.getElementById('ep-convite-area').style.display = 'none';
  document.getElementById('ep-convite-link').value = '';
  _parceiroEditandoId = null;
}

async function salvarParceiroModal() {
  if (!_parceiroEditandoId) return;
  const btn = document.querySelector('#modal-parceiro-edit button[onclick="salvarParceiroModal()"]');
  if (btn) { btn.disabled = true; btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Salvando...'; }

  const fv = (id) => document.getElementById(id).value.trim();
  const fn = (id) => { const v = parseFloat(document.getElementById(id).value); return isNaN(v) ? 0 : v; };

  // Derivar flags de configuração a partir dos benefícios do plano selecionado
  const planoSel   = document.getElementById('ep-plano').value;
  const planoObj   = (_planosData || []).find(x => x.id === planoSel);
  const bPlano     = Array.isArray(planoObj?.beneficios) ? planoObj.beneficios : [];
  const temBeneficio = (id) => bPlano.includes(id);

  const latVal = fv('ep-lat');
  const lngVal = fv('ep-lng');
  const novaSenhaVal = (document.getElementById('ep-nova-senha') ? document.getElementById('ep-nova-senha').value.trim() : '');
  const body = {
    nomePosto:        fv('ep-nomePosto'),
    email:            fv('ep-email'),
    ...(novaSenhaVal.length >= 6 ? { novaSenha: novaSenhaVal } : {}),
    tel:              fv('ep-tel'),
    telTelemarketing: fv('ep-telTelemarketing'),
    bandeira:         document.getElementById('ep-bandeira').value,
    cnpj:             fv('ep-cnpj'),
    plano:            planoSel,
    status:           document.getElementById('ep-status').value,
    // Endereço estruturado
    endereco: {
      cep:    fv('ep-cep'),
      rua:    fv('ep-rua'),
      numero: fv('ep-num'),
      bairro: fv('ep-bairro'),
      cidade: fv('ep-cidade'),
      estado: document.getElementById('ep-estado').value
    },
    // Manter campos legados para compatibilidade
    cidade:   fv('ep-cidade'),
    estado:   document.getElementById('ep-estado').value,
    bairro:   fv('ep-bairro'),
    // Flags derivadas automaticamente dos benefícios do plano
    seloVerificado:   temBeneficio('selo_verificado'),
    pinDourado:       temBeneficio('pin_dourado'),
    topoLista:        temBeneficio('topo_lista'),
    cuponsAtivos:     temBeneficio('cupons_ativos'),
    notificacoesAtivas: temBeneficio('notificacoes'),
    precos: {
      gasolina:          fn('ep-preco-gasolina'),
      gasolinaAditivada: fn('ep-preco-gasolinaAditivada'),
      etanol:            fn('ep-preco-etanol'),
      diesel:            fn('ep-preco-diesel'),
      dieselS10:         fn('ep-preco-dieselS10'),
      gnv:               fn('ep-preco-gnv'),
    }
  };
  if (latVal && lngVal) { body.lat = parseFloat(latVal); body.lng = parseFloat(lngVal); }

  // Geocodificação automática: se não tem lat/lng mas tem endereço, buscar coordenadas
  if (!body.lat && !body.lng) {
    const rua    = body.endereco?.rua    || '';
    const cidade = body.endereco?.cidade || body.cidade || '';
    const estado = body.endereco?.estado || body.estado || '';
    const num    = body.endereco?.numero || '';
    const q = [rua, num, cidade, estado, 'Brasil'].filter(Boolean).join(', ');
    if (rua && cidade) {
      if (btn) btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Geocodificando...';
      try {
        const geoRes = await fetch('/api/geocode?q=' + encodeURIComponent(q));
        const geoData = await geoRes.json();
        if (geoData.resultados && geoData.resultados.length > 0) {
          body.lat = parseFloat(geoData.resultados[0].lat);
          body.lng = parseFloat(geoData.resultados[0].lng);
          document.getElementById('ep-lat').value = body.lat.toFixed(6);
          document.getElementById('ep-lng').value = body.lng.toFixed(6);
          showToast('📍 Coordenadas geocodificadas automaticamente!', 'ok');
        }
      } catch {}
      if (btn) btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Salvando...';
    }
  }

  try {
    const res = await fetch('/api/admin/parceiros/' + encodeURIComponent(_parceiroEditandoId) + '?key=' + encodeURIComponent(ADMIN_KEY), {
      method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body)
    });
    const data = await res.json();
    if (!res.ok || data.erro) throw new Error(data.erro || 'Erro ao salvar');
      const coordMsg = body.lat ? ' (coords: ' + body.lat.toFixed(4) + ', ' + body.lng.toFixed(4) + ')' : ' - sem coordenadas, posto nao aparece na busca';
    showToast('Posto atualizado!' + coordMsg, 'ok');
    fecharModalParceiro();
    await carregarParceirosCadastrados();
    // Se o posto veio da seleção ANP → rodar auto-fotos automaticamente (parceiros + postos do mapa)
    if (_postoVeioDaANP) {
      _postoVeioDaANP = false;
      showToast('🪄 Buscando logo e foto Google Maps automaticamente...', 'ok');
      // Pequeno delay para garantir que o parceiro foi salvo no KV
      setTimeout(async () => {
        const anpResultDiv = document.getElementById('auto-fotos-anp-resultado');
        if (anpResultDiv) {
          anpResultDiv.style.display = 'block';
          anpResultDiv.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Buscando logos e fotos Google Maps automaticamente...';
        }
        try {
          // 1. Auto-fotos para parceiros (salva fotoBandeira + fotoExterna no R2/KV)
          const fr1 = await fetch('/api/admin/script/auto-fotos?key=' + encodeURIComponent(ADMIN_KEY), { method: 'POST' });
          const fd1 = await fr1.json().catch(() => ({}));
          // 2. Auto-fotos para posto:band:* (postos do mapa — ANP/OSM/Google)
          const fr2 = await fetch('/api/admin/script/auto-fotos-postos-band?key=' + encodeURIComponent(ADMIN_KEY) + '&limite=60', { method: 'POST' });
          const fd2 = await fr2.json().catch(() => ({}));
          const logosTot  = (fd1.logosSalvos || 0) + (fd2.logosSalvos || 0);
          const fotosTot  = (fd1.fotosSalvas || 0) + (fd2.fotosSalvas || 0);
          const googleOk  = (fd1.googleKeyDisponivel || fd2.googleKeyDisponivel)
            ? '<span style="color:#69F0AE">✓ Google API</span>'
            : '<span style="color:#FF8A65">⚠️ sem Google API KEY — só logos SVG</span>';
          if (anpResultDiv) {
            // Linhas atualizadas dos postos do mapa
            const linhasMapa = (fd2.resultados || []).filter(function(x) { return x.status === 'atualizado'; }).map(function(x) {
              const acoes = (x.acoes || []).map(function(a) {
                if (a.startsWith('logo_svg:'))          return '🏷️ ' + a.replace('logo_svg:','');
                if (a === 'foto_google:ok')              return '📸 foto ✓';
                if (a === 'foto_google:nao_encontrada')  return '—';
                return a;
              }).join(' ');
              return '✅ <b>' + (x.nome || x.postoId) + '</b> ' + acoes;
            }).join('<br>');
            // Linhas atualizadas dos parceiros
            const linhasParceiros = (fd1.resultados || []).filter(function(x) { return x.status === 'atualizado'; }).map(function(x) {
              const acoes = (x.acoes || []).map(function(a) {
                if (a.startsWith('logo_svg:'))          return '🏷️ ' + a.replace('logo_svg:','');
                if (a === 'foto_google:ok')              return '📸 foto ✓';
                if (a === 'foto_google:nao_encontrada')  return '—';
                return a;
              }).join(' ');
              return '✅ <b>' + (x.nomePosto || x.id) + '</b> ' + acoes;
            }).join('<br>');
            const linhas = [linhasParceiros, linhasMapa].filter(Boolean).join('<br>');
            anpResultDiv.innerHTML =
              '<b style="color:#fff">✅ Fotos buscadas automaticamente!</b> ' + googleOk + '<br>' +
              '🏷️ Logos: <b>' + logosTot + '</b> &nbsp;|&nbsp; ' +
              '📸 Fotos Google: <b>' + fotosTot + '</b> &nbsp;|&nbsp; ' +
              'Parceiros: <b>' + (fd1.total || 0) + '</b> &nbsp;|&nbsp; ' +
              'Postos mapa: <b>' + (fd2.total || 0) + '</b>' +
              (linhas ? '<div style="margin-top:8px;font-size:11px;line-height:2;max-height:160px;overflow-y:auto">' + linhas + '</div>' : '');
          }
          showToast('✅ ' + fotosTot + ' fotos | ' + logosTot + ' logos buscados automaticamente!', 'ok');
          // Propagar para mapa/lista do usuário
          setTimeout(rodarPropagacaoLogos, 700);
        } catch(fe) {
          if (anpResultDiv) anpResultDiv.innerHTML = '❌ Erro ao buscar fotos: ' + fe.message;
          showToast('❌ Erro ao buscar fotos automáticas: ' + fe.message, 'err');
        }
      }, 1200);
    }
  } catch(e) {
    showToast('❌ Erro: ' + e.message, 'err');
  } finally {
    if (btn) { btn.disabled = false; btn.innerHTML = '<i class="fas fa-save"></i> Salvar'; }
  }
}

async function gerarConviteParceiro() {
  if (!_parceiroEditandoId) { showToast('⚠️ Preencha os dados do posto primeiro', ''); return; }
  const btn = document.getElementById('ep-convite-btn');
  if (btn) { btn.disabled = true; btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Salvando...'; }
  try {
    // 1. Salvar o posto automaticamente antes de gerar o convite
    const fv = (id) => (document.getElementById(id)||{value:''}).value.trim();
    const fn = (id) => { const v = parseFloat((document.getElementById(id)||{value:'0'}).value); return isNaN(v) ? 0 : v; };
    const planoSel2  = (document.getElementById('ep-plano')||{value:''}).value;
    const planoObj2  = (_planosData || []).find(x => x.id === planoSel2);
    const bPlano2    = Array.isArray(planoObj2?.beneficios) ? planoObj2.beneficios : [];
    const tem2 = (id) => bPlano2.includes(id);
    const body = {
      nomePosto: fv('ep-nomePosto'), email: fv('ep-email'), tel: fv('ep-tel'),
      telTelemarketing: fv('ep-telTelemarketing'), cidade: fv('ep-cidade'),
      estado: (document.getElementById('ep-estado')||{value:''}).value,
      bairro: fv('ep-bairro'), bandeira: fv('ep-bandeira'), cnpj: fv('ep-cnpj'),
      plano:  planoSel2,
      status: (document.getElementById('ep-status')||{value:'ativo'}).value,
      seloVerificado:    tem2('selo_verificado'),
      pinDourado:        tem2('pin_dourado'),
      topoLista:         tem2('topo_lista'),
      cuponsAtivos:      tem2('cupons_ativos'),
      notificacoesAtivas: tem2('notificacoes'),
      precos: {
        gasolina: fn('ep-preco-gasolina'), gasolinaAditivada: fn('ep-preco-gasolinaAditivada'),
        etanol: fn('ep-preco-etanol'), diesel: fn('ep-preco-diesel'),
        dieselS10: fn('ep-preco-dieselS10'), gnv: fn('ep-preco-gnv'),
      }
    };
    const resSalvar = await fetch('/api/admin/parceiros/' + encodeURIComponent(_parceiroEditandoId) + '?key=' + encodeURIComponent(ADMIN_KEY), {
      method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body)
    });
    const dataSalvar = await resSalvar.json();
    if (!resSalvar.ok || dataSalvar.erro) throw new Error(dataSalvar.erro || 'Erro ao salvar posto');

    // 2. Agora gerar o convite
    if (btn) btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Gerando convite...';
    const res = await fetch('/api/admin/parceiros/' + encodeURIComponent(_parceiroEditandoId) + '/convite?key=' + encodeURIComponent(ADMIN_KEY), { method: 'POST' });
    const data = await res.json();
    if (!res.ok || data.erro) throw new Error(data.erro || 'Erro ao gerar convite');

    // 3. Mostrar link gerado
    const area = document.getElementById('ep-convite-area');
    document.getElementById('ep-convite-link').value = data.link;
    area.style.display = 'block';
    area.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    showToast('✅ Posto salvo e convite gerado!', 'ok');
    carregarParceirosCadastrados();
  } catch(e) {
    showToast('❌ Erro: ' + e.message, 'err');
  } finally {
    if (btn) { btn.disabled = false; btn.innerHTML = '<i class="fas fa-paper-plane"></i> Gerar Convite'; }
  }
}

function copiarConvite() {
  const link = document.getElementById('ep-convite-link').value;
  if (!link) return;
  navigator.clipboard.writeText(link).then(() => showToast('✅ Link copiado!', 'ok')).catch(() => {
    document.getElementById('ep-convite-link').select();
    document.execCommand('copy');
    showToast('✅ Link copiado!', 'ok');
  });
}

function compartilharWhatsApp() {
  const link = document.getElementById('ep-convite-link').value;
  if (!link) return;
  const p = _parceiros.find(x => x.id === _parceiroEditandoId);
  const nome = p ? p.nomePosto : 'seu posto';
  const texto = 'Ola! ' + nome + ' foi cadastrado no RotaPosto. Acesse o link abaixo para confirmar seu cadastro e baixar o app: ' + link;
  window.open('https://wa.me/?text=' + encodeURIComponent(texto), '_blank');
}

async function deletarParceiroModal() {
  if (!_parceiroEditandoId) return;
  const p = _parceiros.find(x => x.id === _parceiroEditandoId);
  await deletarParceiro(_parceiroEditandoId, p ? p.nomePosto : _parceiroEditandoId);
  fecharModalParceiro();
}

async function deletarParceiro(id, nome) {
  if (id === 'p_teste') { showToast('⚠️ Posto de teste nao pode ser removido', ''); return; }
  if (!confirm('Remover o posto "' + nome + '"? Esta acao e irreversivel.')) return;
  try {
    const res = await fetch('/api/admin/postos/' + encodeURIComponent(id) + '?key=' + encodeURIComponent(ADMIN_KEY), { method: 'DELETE' });
    if (!res.ok) throw new Error('HTTP ' + res.status);
    showToast('✅ Posto removido!', 'ok');
    carregarParceirosCadastrados();
  } catch(e) { showToast('❌ Erro: ' + e.message, 'err'); }
}

