function mostrarToastPagamentos(msg, cor) {
  const t = document.getElementById('pagamentos-toast');
  if (!t) return;
  t.textContent = msg;
  t.style.background = cor || '#00C853';
  t.style.display = 'block';
  t.style.opacity = '1';
  setTimeout(function() { t.style.opacity = '0'; setTimeout(function() { t.style.display = 'none'; t.style.opacity = '1'; }, 400); }, 3500);
}

// ─── CREDENCIAIS dos Gateways ────────────────────────────────────────────────
// Mapa de chave → campo KV
// Mapa: id do input → campo no KV (ConfigPagamento)
var _credMap = {
  'woovi':   'wooviAppId',
  'mp':      'mpAccessToken',
  'mp-pk':   'mpPublicKey',
  'mp-cid':  'mpClientId',
  'mp-cs':   'mpClientSecret',
  'pb':      'asaasApiKey'
};
// Cor de destaque por gateway
var _credCors = { woovi: '#00C853', 'mp': '#42A5F5', 'mp-pk': '#42A5F5', 'mp-cid': '#42A5F5', 'mp-cs': '#42A5F5', pb: '#00BD7E' };
// Gateway pai de cada campo (para atualizar status do card-pai)
var _credGateway = { 'woovi': 'woovi', 'mp': 'mp', 'mp-pk': 'mp', 'mp-cid': 'mp', 'mp-cs': 'mp', 'pb': 'pb' };

// Chamada após carregar config — preenche os inputs com valor mascarado
function _popularInputsCredenciais(config) {
  var contadores = { woovi: 0, mp: 0, pb: 0 };
  var totais     = { woovi: 1, mp: 4, pb: 1 };

  Object.keys(_credMap).forEach(function(id) {
    var kvField = _credMap[id];
    var val = config[kvField] || '';
    var el = document.getElementById('cred-input-' + id);
    var btn = document.getElementById('btn-cred-' + id);
    if (!el) return;
    if (val) {
      contadores[_credGateway[id]]++;
      var masked = val.length > 10 ? '••••••••••••' + val.slice(-6) : val;
      el.value = masked;
      el.placeholder = masked;
      el.dataset.original = val;
      el.dataset.preenchido = '1';
    } else {
      el.value = '';
      el.dataset.original = '';
      el.dataset.preenchido = '';
    }
    if (btn) { btn.disabled = true; btn.style.opacity = '0.4'; btn.style.pointerEvents = 'none'; }
  });

  // Atualizar status + borda de cada card-gateway
  var gatewayInfo = {
    woovi: { cor: '#00C853', borderOk: 'rgba(0,200,83,0.35)', borderWarn: 'rgba(255,179,0,0.25)' },
    mp:    { cor: '#42A5F5', borderOk: 'rgba(66,165,245,0.35)', borderWarn: 'rgba(255,179,0,0.25)' },
    pb:    { cor: '#00BD7E', borderOk: 'rgba(0,189,126,0.45)', borderWarn: 'rgba(0,189,126,0.25)' }
  };
  ['woovi', 'mp', 'pb'].forEach(function(gw) {
    var cnt = contadores[gw];
    var tot = totais[gw];
    var info = gatewayInfo[gw];
    var statusEl = document.getElementById('cred-status-' + gw);
    var cardEl   = document.getElementById('card-cred-' + gw);
    if (statusEl) {
      if (cnt === tot) {
        statusEl.textContent = cnt === 1 ? '✅ Configurada' : '✅ Todas (' + cnt + '/' + tot + ')';
        statusEl.style.color = '#00C853';
      } else if (cnt > 0) {
        statusEl.textContent = cnt + '/' + tot + ' configuradas';
        statusEl.style.color = '#FFB300';
      } else {
        statusEl.textContent = '⚠ Insira as chaves';
        statusEl.style.color = '#FF5252';
      }
    }
    if (cardEl) {
      cardEl.style.borderColor = cnt === tot ? info.borderOk : info.borderWarn;
    }
  });

  // Badge do header geral
  var totalGeral = contadores.woovi + contadores.mp + contadores.pb;
  var maxGeral   = totais.woovi + totais.mp + totais.pb; // 1+4+1 = 6 (Woovi+4 MP+Asaas)
  var badge = document.getElementById('badge-cred-resumo');
  if (badge) {
    if (totalGeral === maxGeral) {
      badge.textContent = '✅ Todas (' + maxGeral + '/' + maxGeral + ') configuradas';
      badge.style.color = '#00C853';
    } else if (totalGeral > 0) {
      badge.textContent = totalGeral + '/' + maxGeral + ' chaves configuradas';
      badge.style.color = '#FFB300';
    } else {
      badge.textContent = '⚠ Nenhuma chave inserida';
      badge.style.color = '#FF5252';
    }
  }
}

// Copia URL de webhook para o clipboard
function copiarWebhook(gw) {
  var el = document.getElementById('wh-url-' + gw);
  var btn = document.getElementById('btn-copy-' + gw);
  if (!el) return;
  navigator.clipboard.writeText(el.textContent.trim()).then(function() {
    if (btn) {
      var orig = btn.innerHTML;
      btn.innerHTML = '<i class="fas fa-check" style="margin-right:5px"></i>Copiado!';
      btn.style.background = 'rgba(0,200,83,0.2)';
      btn.style.color = '#00C853';
      btn.style.borderColor = 'rgba(0,200,83,0.4)';
      setTimeout(function() {
        btn.innerHTML = orig;
        var cores = { woovi: { bg:'rgba(0,200,83,0.15)', c:'#00C853', b:'rgba(0,200,83,0.3)' }, mp: { bg:'rgba(66,165,245,0.15)', c:'#42A5F5', b:'rgba(66,165,245,0.3)' }, pb: { bg:'rgba(255,179,0,0.15)', c:'#FFB300', b:'rgba(255,179,0,0.3)' } };
        if (cores[gw]) { btn.style.background = cores[gw].bg; btn.style.color = cores[gw].c; btn.style.borderColor = cores[gw].b; }
      }, 2500);
    }
  }).catch(function() {
    // fallback sem clipboard API
    var ta = document.createElement('textarea');
    ta.value = el.textContent.trim();
    document.body.appendChild(ta);
    ta.select();
    document.execCommand('copy');
    document.body.removeChild(ta);
    if (btn) { btn.innerHTML = '<i class="fas fa-check" style="margin-right:5px"></i>Copiado!'; setTimeout(function(){ btn.innerHTML = '<i class="fas fa-copy" style="margin-right:5px"></i>Copiar'; }, 2000); }
  });
}

function marcarCredAlterada(id) {
  var btn = document.getElementById('btn-cred-' + id);
  var el = document.getElementById('cred-input-' + id);
  if (!btn || !el) return;
  var val = el.value.trim();
  var mudou = val !== '' && (!el.dataset.preenchido || !val.startsWith('••'));
  if (mudou) {
    btn.disabled = false;
    btn.style.opacity = '1';
    btn.style.pointerEvents = 'auto';
  } else {
    btn.disabled = true;
    btn.style.opacity = '0.4';
    btn.style.pointerEvents = 'none';
  }
}

function toggleVerChave(id) {
  var el = document.getElementById('cred-input-' + id);
  var eye = document.getElementById('eye-' + id);
  if (!el) return;
  if (el.type === 'password') {
    el.type = 'text';
    if (eye) eye.textContent = '🙈';
  } else {
    el.type = 'password';
    if (eye) eye.textContent = '👁';
  }
}

async function salvarCredencial(id) {
  var el = document.getElementById('cred-input-' + id);
  var btn = document.getElementById('btn-cred-' + id);
  // statusEl aponta para o status do gateway-pai (woovi/mp/pb)
  var gwPai = _credGateway[id] || id;
  var statusEl = document.getElementById('cred-status-' + gwPai);
  var msg = document.getElementById('cred-msg-global');
  if (!el) return;
  var val = el.value.trim();
  // Se valor ainda está mascarado (não alterado), não salvar
  if (val.startsWith('••')) { return; }
  if (!val) {
    if (msg) { msg.textContent = '❌ Chave não pode ser vazia.'; msg.style.color = '#FF5252'; }
    return;
  }
  if (btn) { btn.disabled = true; btn.style.opacity = '0.7'; btn.textContent = '...'; }
  var kvField = _credMap[id];
  var payload = {};
  payload[kvField] = val;
  try {
    const res = await fetch('/api/admin/config/pagamento?key=' + encodeURIComponent(ADMIN_KEY), {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    });
    const data = await res.json();
    if (data.ok) {
      // Mascarar novamente após salvar
      var masked = val.length > 10 ? '••••••••••••' + val.slice(-6) : val;
      el.value = masked;
      el.placeholder = masked;
      el.dataset.original = val;
      el.dataset.preenchido = '1';
      el.type = 'password';
      var eyeEl = document.getElementById('eye-' + id);
      if (eyeEl) eyeEl.textContent = '👁';
      if (msg) { msg.textContent = '✅ Chave salva com sucesso!'; msg.style.color = '#00C853'; }
      mostrarToastPagamentos('✅ Credencial salva!', _credCors[id] || '#00C853');
      // Atualizar flags temEnv locais
      if (gwPai === 'woovi') _pgTemWooviEnv = true;
      if (gwPai === 'mp')    _pgTemMPEnv    = true;
      if (gwPai === 'pb')    _pgTemAsaasEnv = true;
      // Re-popular todos os inputs para atualizar contadores e bordas
      if (data.config) _popularInputsCredenciais(data.config);
      renderIntegracaoStatus();
      renderGatewayCards();
    } else {
      if (msg) { msg.textContent = '❌ Erro ao salvar: ' + (data.erro || ''); msg.style.color = '#FF5252'; }
    }
  } catch(e) {
    if (msg) { msg.textContent = '❌ ' + e.message; msg.style.color = '#FF5252'; }
  } finally {
    if (btn) { btn.disabled = true; btn.style.opacity = '0.4'; btn.style.pointerEvents = 'none'; btn.textContent = 'Salvar'; }
    setTimeout(function() { if (msg) msg.textContent = ''; }, 4500);
  }
}

// ─── PLANOS DO APP (B2C) — edição de preços e benefícios ────────────────────
let _planosAppData = [];
var _planoAppTabIdx = null;

async function carregarPlanosApp() {
  var panel = document.getElementById('planos-app-panel');
  if (panel) panel.innerHTML = '<div style="color:rgba(255,255,255,0.3);padding:40px;text-align:center"><i class="fas fa-spinner fa-spin" style="font-size:24px;margin-bottom:12px;display:block"></i>Carregando...</div>';
  try {
    const res = await fetch('/api/admin/planos?key=' + encodeURIComponent(ADMIN_KEY));
    const data = await res.json();
    _planosAppData = data.planos || [];
    if (_planoAppTabIdx === null && _planosAppData.length > 0) _planoAppTabIdx = 0;
    renderizarAbasPlanosApp();
    renderizarPlanoAppSelecionado();
  } catch(e) {
    if (panel) panel.innerHTML = '<div style="color:#FF5252;padding:40px;text-align:center"><i class="fas fa-exclamation-triangle"></i> Erro ao carregar: ' + e.message + '</div>';
  }
}

function renderizarAbasPlanosApp() {
  var tabs = document.getElementById('planos-app-tabs');
  if (!tabs) return;
  var cards = _planosAppData.map(function(p, i) {
    var cor = p.cor || '#42A5F5';
    var isAtivo = i === _planoAppTabIdx;
    var preco = p.valor ? 'R$ ' + (p.valor/100).toFixed(2).replace('.',',') : 'Grátis';
    var cicloLabel = { forever:'', monthly:'/mês', yearly:'/ano', weekly:'/sem' }[p.ciclo] || '';
    return '<div onclick="selecionarPlanoAppTab(' + i + ')" style="'
      + 'cursor:pointer;border-radius:8px;padding:10px 16px;flex-shrink:0;'
      + 'border:1px solid ' + (isAtivo ? cor : 'rgba(255,255,255,0.08)') + ';'
      + 'background:' + (isAtivo ? 'rgba(255,255,255,0.07)' : 'rgba(255,255,255,0.02)') + ';'
      + 'transition:all 0.15s ease;position:relative;'
      + 'display:flex;align-items:center;gap:10px;min-width:140px;'
      + '">'
      // Indicador lateral colorido quando selecionado
      + (isAtivo ? '<div style="position:absolute;left:0;top:0;bottom:0;width:3px;background:' + cor + ';border-radius:8px 0 0 8px"></div>' : '')
      // Emoji pequeno
      + '<div style="font-size:20px;line-height:1;flex-shrink:0;padding-left:' + (isAtivo ? '6px' : '0') + ';opacity:' + (isAtivo ? '1' : '0.5') + '">' + (p.emoji || '📦') + '</div>'
      // Info
      + '<div style="flex:1;min-width:0">'
      +   '<div style="font-size:12px;font-weight:700;color:' + (isAtivo ? '#fff' : 'rgba(255,255,255,0.5)') + ';white-space:nowrap;overflow:hidden;text-overflow:ellipsis">' + p.nome + '</div>'
      +   '<div style="font-size:11px;color:' + (isAtivo ? cor : 'rgba(255,255,255,0.2)') + ';margin-top:1px">' + preco + '<span style="opacity:0.7">' + cicloLabel + '</span></div>'
      + '</div>'
      // Badge TOP
      + (p.destaque ? '<div style="font-size:9px;font-weight:800;color:#FFD600;background:rgba(255,214,0,0.12);padding:2px 6px;border-radius:4px;flex-shrink:0">TOP</div>' : '')
      + '</div>';
  }).join('');

  // Botão Novo Plano — estilo link discreto
  cards += '<div onclick="abrirModalNovoPlanoApp()" style="'
    + 'cursor:pointer;border-radius:8px;padding:10px 16px;flex-shrink:0;'
    + 'border:1px dashed rgba(255,255,255,0.1);background:transparent;'
    + 'transition:all 0.15s;display:flex;align-items:center;gap:8px'
    + '" class="plano-novo-card">'
    + '<i class="fas fa-plus" style="font-size:12px;color:rgba(255,255,255,0.25)"></i>'
    + '<span style="font-size:12px;font-weight:600;color:rgba(255,255,255,0.25)">Novo Plano</span>'
    + '</div>';

  tabs.innerHTML = cards;
}

function selecionarPlanoAppTab(idx) {
  _planoAppTabIdx = idx;
  renderizarAbasPlanosApp();
  renderizarPlanoAppSelecionado();
}

function renderizarPlanoAppSelecionado() {
  var panel = document.getElementById('planos-app-panel');
  if (!panel) return;
  if (!_planosAppData.length) {
    panel.innerHTML = '<div style="color:rgba(255,255,255,0.3);padding:60px;text-align:center"><i class="fas fa-layer-group" style="font-size:36px;display:block;margin-bottom:16px;opacity:0.3"></i>Nenhum plano encontrado.</div>';
    return;
  }
  var i = (_planoAppTabIdx !== null && _planoAppTabIdx < _planosAppData.length) ? _planoAppTabIdx : 0;
  var p = _planosAppData[i];
  var cor = p.cor || '#42A5F5';
  var rgb = _hexToRgb(cor);
  var isGratis = p.id === 'free';
  var isProtected = ['free','premium','anual'].includes(p.id);
  var CICLO_OPTS = [
    { v:'forever', l:'Grátis (sem cobrança)' },
    { v:'monthly', l:'Mensal' },
    { v:'yearly',  l:'Anual' },
    { v:'weekly',  l:'Semanal' }
  ];
  var cicloOpts = CICLO_OPTS.map(function(o) {
    return '<option value="' + o.v + '"' + (p.ciclo === o.v ? ' selected' : '') + '>' + o.l + '</option>';
  }).join('');
  var featuresHtml = (p.features || []).map(function(f, fi) {
    return '<div style="display:flex;align-items:center;gap:10px;padding:10px 14px;border-radius:10px;background:rgba(255,255,255,0.03);border:1px solid ' + (f.incluido ? 'rgba(' + rgb + ',0.2)' : 'rgba(255,255,255,0.06)') + ';margin-bottom:6px;transition:border-color 0.15s">'
      + '<input type="checkbox" id="paf-' + i + '-' + fi + '" ' + (f.incluido ? 'checked' : '') + ' onchange="toggleFeatureApp(' + i + ',' + fi + ',this.checked)" style="accent-color:' + cor + ';width:16px;height:16px;cursor:pointer;flex-shrink:0">'
      + '<span style="color:' + (f.incluido ? cor : 'rgba(255,255,255,0.3)') + ';font-size:12px;flex-shrink:0">' + (f.incluido ? '✓' : '○') + '</span>'
      + '<input type="text" value="' + f.texto.replace(/"/g, '&quot;') + '" oninput="editarTextoFeatureApp(' + i + ',' + fi + ',this.value)" style="background:transparent;border:none;color:rgba(255,255,255,0.85);font-size:13px;flex:1;outline:none;font-family:inherit" placeholder="Descrição do benefício...">'
      + '<button onclick="removerFeatureApp(' + i + ',' + fi + ')" style="background:rgba(255,82,82,0.1);border:none;color:rgba(255,82,82,0.6);cursor:pointer;padding:4px 8px;font-size:11px;border-radius:6px;flex-shrink:0" title="Remover"><i class="fas fa-times"></i></button>'
      + '</div>';
  }).join('');

  panel.innerHTML = ''
  // Wrapper — mesma linguagem visual do section-card
  + '<div style="border-top:1px solid rgba(255,255,255,0.06);margin-top:8px">'
  // Faixa colorida fina sinalizando plano selecionado
  + '<div style="height:3px;background:' + cor + ';opacity:0.6;margin-bottom:0"></div>'

  // ── Cabeçalho do editor ──
  + '<div style="padding:20px 24px 16px;border-bottom:1px solid rgba(255,255,255,0.06);display:flex;align-items:center;gap:14px;flex-wrap:wrap">'
  // Emoji picker
  +   '<input id="pa-emoji-' + i + '" type="text" maxlength="4" value="' + (p.emoji||'📦') + '" style="background:rgba(255,255,255,0.05);border:1px solid rgba(255,255,255,0.1);border-radius:10px;color:#fff;font-size:26px;text-align:center;padding:8px;width:56px;height:56px;font-family:inherit;outline:none;cursor:pointer;box-sizing:border-box;flex-shrink:0">'
  // Nome + descrição
  +   '<div style="flex:1;min-width:180px">'
  +     '<label style="font-size:10px;color:rgba(255,255,255,0.35);font-weight:700;text-transform:uppercase;letter-spacing:0.5px;display:block;margin-bottom:5px">Nome do Plano</label>'
  +     '<input id="pa-nome-' + i + '" type="text" value="' + p.nome.replace(/"/g, '&quot;') + '" style="width:100%;background:rgba(255,255,255,0.04);border:1px solid rgba(255,255,255,0.1);border-radius:8px;color:#fff;font-size:16px;font-weight:700;padding:7px 12px;font-family:inherit;outline:none;margin-bottom:6px;box-sizing:border-box" placeholder="Nome do plano">'
  +     '<input id="pa-desc-' + i + '" type="text" value="' + (p.descricao||'').replace(/"/g, '&quot;') + '" style="width:100%;background:rgba(255,255,255,0.03);border:1px solid rgba(255,255,255,0.06);border-radius:8px;color:rgba(255,255,255,0.45);font-size:12px;padding:6px 12px;font-family:inherit;outline:none;box-sizing:border-box" placeholder="Subtítulo exibido no app...">'
  +   '</div>'
  // Cor
  +   '<div style="display:flex;flex-direction:column;align-items:center;gap:4px;flex-shrink:0">'
  +     '<label style="font-size:9px;color:rgba(255,255,255,0.3);font-weight:600;text-transform:uppercase;letter-spacing:0.4px">Cor</label>'
  +     '<input id="pa-cor-' + i + '" type="color" value="' + cor + '" style="width:44px;height:44px;border:1px solid rgba(255,255,255,0.1);border-radius:8px;background:rgba(255,255,255,0.04);padding:3px;cursor:pointer">'
  +   '</div>'
  + '</div>'

  // ── Preço + Ciclo ──
  + '<div style="padding:16px 24px;border-bottom:1px solid rgba(255,255,255,0.06);display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:16px">'
  +   '<div>'
  +     '<label style="font-size:10px;color:rgba(255,255,255,0.35);font-weight:700;text-transform:uppercase;letter-spacing:0.5px;display:block;margin-bottom:8px">Preço (centavos)</label>'
  +     '<div style="display:flex;align-items:center;gap:6px">'
  +       '<span style="font-size:16px;font-weight:700;color:rgba(255,255,255,0.3)">R$</span>'
  +       '<input id="pa-valor-' + i + '" type="number" min="0" step="1" value="' + p.valor + '" ' + (isGratis ? 'disabled' : '') + ' style="background:rgba(255,255,255,0.05);border:1px solid rgba(255,255,255,0.1);border-radius:8px;color:#fff;font-size:22px;font-weight:800;padding:8px 12px;width:130px;font-family:inherit;outline:none;' + (isGratis ? 'opacity:0.3;cursor:not-allowed' : '') + '">'
  +     '</div>'
  +     '<div style="font-size:10px;color:rgba(255,255,255,0.2);margin-top:5px">ex: 9900 → R$ 99,00</div>'
  +   '</div>'
  +   '<div>'
  +     '<label style="font-size:10px;color:rgba(255,255,255,0.35);font-weight:700;text-transform:uppercase;letter-spacing:0.5px;display:block;margin-bottom:8px">Ciclo de Cobrança</label>'
  +     '<select id="pa-ciclo-' + i + '" ' + (isGratis ? 'disabled' : '') + ' style="width:100%;background:#0d1f33;border:1px solid rgba(255,255,255,0.1);border-radius:8px;color:#fff;font-size:13px;font-weight:600;padding:10px 12px;font-family:inherit;outline:none;cursor:pointer;' + (isGratis ? 'opacity:0.3;cursor:not-allowed' : '') + '">' + cicloOpts + '</select>'
  +   '</div>'
  + '</div>'

  // ── Toggles: Ativo + Destaque ──
  + '<div style="padding:12px 24px;border-bottom:1px solid rgba(255,255,255,0.06);display:flex;flex-wrap:wrap;gap:18px;align-items:center">'
  +   '<label style="display:flex;align-items:center;gap:10px;cursor:pointer">'
  +     '<input id="pa-ativo-' + i + '" type="checkbox" ' + (p.ativo !== false ? 'checked' : '') + ' style="accent-color:#00C853;width:16px;height:16px;cursor:pointer">'
  +     '<span style="font-size:13px;font-weight:600;color:rgba(255,255,255,0.7)">✅ Plano Ativo</span>'
  +     '<span style="font-size:11px;color:rgba(255,255,255,0.3)">— exibido no app</span>'
  +   '</label>'
  +   '<label style="display:flex;align-items:center;gap:10px;cursor:pointer">'
  +     '<input id="pa-destaque-' + i + '" type="checkbox" ' + (p.destaque ? 'checked' : '') + ' style="accent-color:#FFD600;width:16px;height:16px;cursor:pointer">'
  +     '<span style="font-size:13px;font-weight:600;color:rgba(255,255,255,0.7)">⭐ Plano em Destaque</span>'
  +     '<span style="font-size:11px;color:rgba(255,255,255,0.3)">— aparece primeiro</span>'
  +   '</label>'
  + '</div>'

  // ── Benefícios/Features ──
  + '<div style="padding:16px 24px;border-bottom:1px solid rgba(255,255,255,0.06)">'
  +   '<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:12px">'
  +     '<label style="font-size:10px;color:rgba(255,255,255,0.35);font-weight:700;text-transform:uppercase;letter-spacing:0.5px"><i class="fas fa-mobile-alt" style="margin-right:6px;opacity:0.6"></i>Benefícios exibidos no App</label>'
  +     '<button onclick="adicionarFeatureApp(' + i + ')" style="background:rgba(255,255,255,0.05);color:rgba(255,255,255,0.7);border:1px solid rgba(255,255,255,0.1);border-radius:7px;padding:5px 12px;font-size:11px;font-weight:600;cursor:pointer;font-family:inherit"><i class="fas fa-plus" style="margin-right:4px"></i>Adicionar</button>'
  +   '</div>'
  +   '<div id="pa-features-' + i + '">' + (featuresHtml || '<div style="text-align:center;padding:20px;color:rgba(255,255,255,0.2);font-size:12px">Nenhum benefício cadastrado.</div>') + '</div>'
  + '</div>'

  // ── Rodapé: ID + gateway + ações ──
  + '<div style="padding:14px 24px;border-top:1px solid rgba(255,255,255,0.06)">'
  // Info gateway externo
  +   '<div style="display:flex;align-items:center;gap:8px;margin-bottom:12px;flex-wrap:wrap">'
  +     '<span style="font-size:10px;color:rgba(255,255,255,0.2);font-family:monospace">ID: ' + p.id + '</span>'
  +     (p.wooviPlanId ? '<span style="font-size:10px;background:rgba(0,200,83,0.1);color:#00C853;padding:2px 8px;border-radius:4px;font-family:monospace">🟢 Woovi: ' + p.wooviPlanId + '</span>' : '')
  +     (p.mpPlanId    ? '<span style="font-size:10px;background:rgba(66,165,245,0.1);color:#42A5F5;padding:2px 8px;border-radius:4px;font-family:monospace">🔵 MP: ' + p.mpPlanId + '</span>' : '')
  +   '</div>'
  // Botões de ação
  +   '<div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap">'
  +     '<button onclick="criarPlanoNoGateway(&apos;' + p.id + '&apos;,&apos;app&apos;,this)" style="background:rgba(255,255,255,0.05);color:rgba(255,255,255,0.6);border:1px solid rgba(255,255,255,0.12);padding:8px 16px;border-radius:8px;cursor:pointer;font-size:12px;font-weight:700;font-family:inherit"><i class="fas fa-plug" style="margin-right:5px"></i>Criar no Gateway</button>'
  +     (!isProtected ? '<button onclick="deletarPlanoApp(&apos;' + p.id + '&apos;)" style="background:rgba(255,82,82,0.08);color:rgba(255,82,82,0.8);border:1px solid rgba(255,82,82,0.15);padding:8px 16px;border-radius:8px;cursor:pointer;font-size:12px;font-weight:700;font-family:inherit"><i class="fas fa-trash" style="margin-right:5px"></i>Excluir</button>' : '')
  +     '<button onclick="salvarPlanoApp(' + i + ',&apos;' + p.id + '&apos;)" id="pa-save-btn-' + i + '" class="plano-save-btn" style="background:#FF6D00;color:#fff;border:none;padding:9px 24px;border-radius:8px;font-weight:800;font-size:13px;cursor:pointer;font-family:inherit;transition:transform 0.15s,filter 0.15s"><i class="fas fa-save" style="margin-right:7px"></i>Salvar alterações</button>'
  +     '<span id="pa-gateway-msg-' + i + '" style="font-size:12px;font-weight:700"></span>'
  +   '</div>'
  + '</div>'
  + '</div>';
}

// renderPlanosAppGrid substituída por renderizarAbasPlanosApp + renderizarPlanoAppSelecionado

function toggleFeatureApp(planoIdx, featIdx, checked) {
  if (_planosAppData[planoIdx] && _planosAppData[planoIdx].features[featIdx] !== undefined) {
    _planosAppData[planoIdx].features[featIdx].incluido = checked;
  }
}

function editarTextoFeatureApp(planoIdx, featIdx, texto) {
  if (_planosAppData[planoIdx] && _planosAppData[planoIdx].features[featIdx] !== undefined) {
    _planosAppData[planoIdx].features[featIdx].texto = texto;
  }
}

function removerFeatureApp(planoIdx, featIdx) {
  if (!_planosAppData[planoIdx]) return;
  _planosAppData[planoIdx].features.splice(featIdx, 1);
  renderizarPlanoAppSelecionado();
}

function adicionarFeatureApp(planoIdx) {
  if (!_planosAppData[planoIdx]) return;
  _planosAppData[planoIdx].features.push({ texto: '', incluido: true });
  renderizarPlanoAppSelecionado();
  // Focar no novo input
  setTimeout(function() {
    var container = document.getElementById('pa-features-' + planoIdx);
    if (container) {
      var inputs = container.querySelectorAll('input[type=text]');
      if (inputs.length) inputs[inputs.length - 1].focus();
    }
  }, 50);
}

async function salvarPlanoApp(idx, id) {
  const nomeEl    = document.getElementById('pa-nome-' + idx);
  const descEl    = document.getElementById('pa-desc-' + idx);
  const valorEl   = document.getElementById('pa-valor-' + idx);
  const cicloEl   = document.getElementById('pa-ciclo-' + idx);
  const emojiEl   = document.getElementById('pa-emoji-' + idx);
  const corEl     = document.getElementById('pa-cor-' + idx);
  const destaqueEl= document.getElementById('pa-destaque-' + idx);
  const ativoEl   = document.getElementById('pa-ativo-' + idx);
  if (!nomeEl) return;
  const body = {
    nome:     nomeEl.value.trim(),
    descricao: descEl ? descEl.value.trim() : '',
    valor:    parseInt(valorEl ? valorEl.value : '0') || 0,
    ciclo:    cicloEl ? cicloEl.value : 'monthly',
    emoji:    emojiEl ? emojiEl.value.trim() : '',
    cor:      corEl   ? corEl.value : '',
    destaque: destaqueEl ? destaqueEl.checked : false,
    ativo:    ativoEl   ? ativoEl.checked   : true,
    features: _planosAppData[idx] ? _planosAppData[idx].features : []
  };
  try {
    const res = await fetch('/api/admin/planos/' + encodeURIComponent(id) + '?key=' + encodeURIComponent(ADMIN_KEY), {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body)
    });
    const data = await res.json();
    if (data.ok) {
      mostrarToastPlanosApp('✅ Plano "' + body.nome + '" salvo com sucesso!', '#00C853');
      var savedIdx = _planoAppTabIdx;
      await carregarPlanosApp();
      _planoAppTabIdx = savedIdx;
      renderizarAbasPlanosApp();
      renderizarPlanoAppSelecionado();
    } else {
      mostrarToastPlanosApp('❌ Erro: ' + (data.erro || 'Falha ao salvar'), '#FF5252');
    }
  } catch(e) {
    mostrarToastPlanosApp('❌ Erro de rede: ' + e.message, '#FF5252');
  }
}

async function criarPlanoNoGateway(planoId, tipoCatalogo, btnEl) {
  if (!confirm('Criar o plano "' + planoId + '" no gateway de pagamento ativo? Isso cria um produto no Woovi/MP.')) return;
  var msgEl = document.getElementById((tipoCatalogo === 'app' ? 'pa' : 'pp') + '-gateway-msg-' + (_planoAppTabIdx !== null ? _planoAppTabIdx : _planoTabIdx));
  if (btnEl) { btnEl.disabled = true; btnEl.innerHTML = '<i class="fas fa-spinner fa-spin"></i>'; }
  try {
    const res = await fetch('/api/admin/planos/criar-no-gateway?key=' + encodeURIComponent(ADMIN_KEY), {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ planoId, tipoCatalogo })
    });
    const data = await res.json();
    if (data.ok) {
      if (msgEl) { msgEl.textContent = '✅ ' + (data.mensagem || 'Criado!'); msgEl.style.color = '#00C853'; }
      mostrarToastPlanosApp('✅ ' + data.mensagem, '#00C853');
      // Recarregar para mostrar o ID externo
      if (tipoCatalogo === 'app') { var sv = _planoAppTabIdx; await carregarPlanosApp(); _planoAppTabIdx = sv; renderizarAbasPlanosApp(); renderizarPlanoAppSelecionado(); }
      else { var sv2 = _planoTabIdx; await carregarEstatisticasPlanos(); _planoTabIdx = sv2; renderizarAbasPlanos(); renderizarPlanoSelecionado(); }
    } else {
      if (msgEl) { msgEl.textContent = '❌ ' + (data.erro || 'Falhou'); msgEl.style.color = '#FF5252'; }
      mostrarToastPlanosApp('❌ ' + (data.erro || 'Falha ao criar no gateway'), '#FF5252');
    }
  } catch(e) {
    if (msgEl) { msgEl.textContent = '❌ ' + e.message; msgEl.style.color = '#FF5252'; }
    mostrarToastPlanosApp('❌ Erro: ' + e.message, '#FF5252');
  } finally {
    if (btnEl) { btnEl.disabled = false; btnEl.innerHTML = '<i class="fas fa-plug" style="margin-right:5px"></i>Criar no Gateway'; }
    setTimeout(function() { if (msgEl) msgEl.textContent = ''; }, 6000);
  }
}

async function deletarPlanoApp(id) {
  if (!confirm('Remover o plano "' + id + '"? Esta ação não pode ser desfeita.')) return;
  try {
    const res = await fetch('/api/admin/planos/' + encodeURIComponent(id) + '?key=' + encodeURIComponent(ADMIN_KEY), { method: 'DELETE' });
    const data = await res.json();
    if (data.ok) {
      _planoAppTabIdx = 0;
      mostrarToastPlanosApp('🗑️ Plano removido.', '#FF6D00');
      await carregarPlanosApp();
    } else {
      mostrarToastPlanosApp('❌ Erro: ' + (data.erro || 'Falha ao remover'), '#FF5252');
    }
  } catch(e) {
    mostrarToastPlanosApp('❌ Erro: ' + e.message, '#FF5252');
  }
}

function mostrarToastPlanosApp(msg, cor) {
  const t = document.getElementById('planos-app-toast');
  if (!t) return;
  t.textContent = msg;
  t.style.background = cor || '#00C853';
  t.style.display = 'block';
  t.style.opacity = '1';
  setTimeout(() => { t.style.opacity = '0'; setTimeout(() => { t.style.display = 'none'; t.style.opacity = '1'; }, 400); }, 3000);
}

function abrirModalNovoPlanoApp() {
  const m = document.getElementById('modal-novo-plano-app');
  if (!m) return;
  // Limpar campos
  const npa = function(id) { return document.getElementById(id); };
  if (npa('npa-emoji')) npa('npa-emoji').value = '💎';
  if (npa('npa-nome'))  npa('npa-nome').value  = '';
  if (npa('npa-desc'))  npa('npa-desc').value  = '';
  if (npa('npa-valor')) npa('npa-valor').value = '0';
  if (npa('npa-ciclo')) npa('npa-ciclo').value = 'monthly';
  if (npa('npa-cor'))   npa('npa-cor').value   = '#42A5F5';
  if (npa('npa-destaque')) npa('npa-destaque').checked = false;
  m.style.display = 'flex';
  setTimeout(() => { if (npa('npa-nome')) npa('npa-nome').focus(); }, 100);
}

function fecharModalNovoPlanoApp() {
  const m = document.getElementById('modal-novo-plano-app');
  if (m) m.style.display = 'none';
}

async function criarNovoPlanoApp() {
  const get = function(id) { return document.getElementById(id); };
  const nome = (get('npa-nome')||{value:''}).value.trim();
  if (!nome) { alert('Informe o nome do plano.'); return; }
  const ciclo = (get('npa-ciclo')||{value:'monthly'}).value;
  const body = {
    nome,
    emoji:     (get('npa-emoji')||{value:'💎'}).value.trim() || '💎',
    cor:       (get('npa-cor')||{value:'#42A5F5'}).value,
    valor:     parseInt((get('npa-valor')||{value:'0'}).value) || 0,
    ciclo,
    descricao: (get('npa-desc')||{value:''}).value.trim(),
    destaque:  (get('npa-destaque')||{checked:false}).checked,
    features:  []
  };
  body.id = 'app_' + nome.toLowerCase().replace(/[^a-z0-9]/g,'_').replace(/_+/g,'_').replace(/^_|_$/g,'') + '_' + Date.now();
  const btn = document.querySelector('#modal-novo-plano-app button[onclick="criarNovoPlanoApp()"]');
  if (btn) { btn.disabled = true; btn.textContent = 'Criando...'; }
  try {
    const res = await fetch('/api/admin/planos?key=' + encodeURIComponent(ADMIN_KEY), {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body)
    });
    const data = await res.json();
    if (!res.ok || data.erro) throw new Error(data.erro || 'Erro ao criar');
    fecharModalNovoPlanoApp();
    mostrarToastPlanosApp('✅ Plano "' + nome + '" criado!', '#00C853');
    await carregarPlanosApp();
    // Selecionar o novo plano (último)
    _planoAppTabIdx = _planosAppData.length - 1;
    renderizarAbasPlanosApp();
    renderizarPlanoAppSelecionado();
  } catch(e) {
    alert('Erro ao criar plano: ' + e.message);
  } finally {
    if (btn) { btn.disabled = false; btn.innerHTML = '<i class="fas fa-plus" style="margin-right:6px"></i>Criar Plano'; }
  }
}

// ─── PLANOS DOS POSTOS (B2B) ────────────────────────────────────────────────
// _planosData declarado globalmente acima (junto com _parceiros)
let _planoEditandoId = null;  // id do plano em edição (null = novo)

const CICLO_LABEL = { forever: 'Grátis', monthly: '/mês', yearly: '/ano', weekly: '/semana' };


// Índice do plano selecionado na aba (null = nenhum ainda)
var _planoTabIdx = null;

async function carregarEstatisticasPlanos() {
  // 1. Carregar planos primeiro para montar as abas
  await carregarPlanosGrid();

  // 2. KPIs: contar postos por plano e atualizar contadores nas abas
  try {
    const parcsRes = await fetch('/api/admin/parceiros?key=' + encodeURIComponent(ADMIN_KEY));
    const parcsData = await parcsRes.json();
    const parceiros = parcsData.parceiros || [];
    _planosData.forEach(function(p, i) {
      var n = parceiros.filter(function(parc) { return (parc.plano || 'posto_gratis') === p.id; }).length;
      var el = document.getElementById('plano-tab-count-' + i);
      if (el) el.textContent = n + ' posto' + (n !== 1 ? 's' : '');
    });
  } catch(e) { /* sem contadores é ok */ }
}

async function carregarPlanosGrid() {
  const grid = document.getElementById('planos-grid');
  if (!grid) return;
  try {
    const res = await fetch('/api/admin/planos-posto?key=' + encodeURIComponent(ADMIN_KEY));
    const data = await res.json();
    _planosData = data.planos || [];
    // Selecionar primeiro plano se nenhum estiver selecionado
    if (_planoTabIdx === null && _planosData.length > 0) _planoTabIdx = 0;
    renderizarAbasPlanos();
    renderizarPlanoSelecionado();
  } catch(e) {
    grid.innerHTML = '<div style="color:#FF5252;padding:20px;text-align:center">Erro ao carregar planos: ' + e.message + '</div>';
  }
}

function renderizarAbasPlanos() {
  var tabs = document.getElementById('planos-tabs');
  if (!tabs) return;
  var cards = _planosData.map(function(p, i) {
    var cor = p.cor || '#FF6D00';
    var isAtivo = i === _planoTabIdx;
    return '<div onclick="selecionarPlanoTab(' + i + ')" style="'
      + 'cursor:pointer;border-radius:8px;padding:10px 16px;flex-shrink:0;'
      + 'border:1px solid ' + (isAtivo ? cor : 'rgba(255,255,255,0.08)') + ';'
      + 'background:' + (isAtivo ? 'rgba(255,255,255,0.07)' : 'rgba(255,255,255,0.02)') + ';'
      + 'transition:all 0.15s ease;position:relative;'
      + 'display:flex;align-items:center;gap:10px;min-width:140px;'
      + '">'
      // Indicador lateral colorido quando selecionado
      + (isAtivo ? '<div style="position:absolute;left:0;top:0;bottom:0;width:3px;background:' + cor + ';border-radius:8px 0 0 8px"></div>' : '')
      // Emoji pequeno
      + '<div style="font-size:20px;line-height:1;flex-shrink:0;padding-left:' + (isAtivo ? '6px' : '0') + ';opacity:' + (isAtivo ? '1' : '0.5') + '">' + (p.emoji || '📦') + '</div>'
      // Info
      + '<div style="flex:1;min-width:0">'
      +   '<div style="font-size:12px;font-weight:700;color:' + (isAtivo ? '#fff' : 'rgba(255,255,255,0.5)') + ';white-space:nowrap;overflow:hidden;text-overflow:ellipsis">' + p.nome + '</div>'
      +   '<div style="font-size:11px;color:rgba(255,255,255,0.3);margin-top:1px" id="plano-tab-count-' + i + '">– postos</div>'
      + '</div>'
      // Badge TOP
      + (p.destaque ? '<div style="font-size:9px;font-weight:800;color:#FFD600;background:rgba(255,214,0,0.12);padding:2px 6px;border-radius:4px;flex-shrink:0">TOP</div>' : '')
      + '</div>';
  }).join('');

  // Botão Novo Plano — estilo link discreto
  cards += '<div id="btn-novo-plano-tab" onclick="abrirModalNovoPLano()" style="'
    + 'cursor:pointer;border-radius:8px;padding:10px 16px;flex-shrink:0;'
    + 'border:1px dashed rgba(255,255,255,0.1);background:transparent;'
    + 'transition:all 0.15s;display:flex;align-items:center;gap:8px'
    + '" class="plano-novo-card">'
    + '<i class="fas fa-plus" style="font-size:12px;color:rgba(255,255,255,0.25)"></i>'
    + '<span style="font-size:12px;font-weight:600;color:rgba(255,255,255,0.25)">Novo Plano</span>'
    + '</div>';

  tabs.innerHTML = cards;
}

function _hexToRgb(hex) {
  hex = hex.replace('#','');
  if (hex.length === 3) hex = hex[0]+hex[0]+hex[1]+hex[1]+hex[2]+hex[2];
  var r = parseInt(hex.substring(0,2),16);
  var g = parseInt(hex.substring(2,4),16);
  var b = parseInt(hex.substring(4,6),16);
  return r + ',' + g + ',' + b;
}

function selecionarPlanoTab(idx) {
  _planoTabIdx = idx;
  renderizarAbasPlanos();
  renderizarPlanoSelecionado();
}

