// ── POST /api/parceiros/foto-bandeira — upload da foto/logo do posto ──────────
app.post('/api/parceiros/foto-bandeira', async (c) => {
  try {
    const kv = getKV(c.env) ?? undefined
    const r2 = (c.env as Record<string, unknown>)?.ROTAPOSTO_R2 as R2Bucket | undefined
    const ADMIN_PASS = (c.env as Record<string,unknown>)?.ADMIN_PASS as string || 'rotaposto@admin2026'
    const token = c.req.header('Authorization')?.replace('Bearer ', '') || ''
    const adminKey = c.req.query('key') || ''
    const isAdmin = adminKey === ADMIN_PASS

    // Auth via token de parceiro OU chave admin
    let parceiroId = ''
    if (!isAdmin && token) {
      const sess = await kvGetParceiro(kv, `sess_${token}`, r2) as Record<string, unknown> | null
      if (!sess || (sess.exp as number) < Date.now()) return c.json({ ok: false, erro: 'Sessão expirada' }, 401)
      parceiroId = String(sess.parceiroId)
    }

    const formData = await c.req.formData()
    // postoId manual (admin ou fallback)
    const bodyPostoId = formData.get('postoId') as string || ''
    if (!parceiroId) parceiroId = bodyPostoId
    if (!parceiroId) return c.json({ ok: false, erro: 'postoId obrigatório' }, 400)
    if (!isAdmin && !token) return c.json({ ok: false, erro: 'Não autorizado' }, 401)

    const file = formData.get('foto') as File | null
    if (!file) return c.json({ ok: false, erro: 'Arquivo não encontrado' }, 400)
    if (file.size > 3 * 1024 * 1024) return c.json({ ok: false, erro: 'Imagem muito grande (máx. 3 MB)' }, 400)

    const mime = file.type || 'image/jpeg'
    const ext  = mime.includes('png') ? 'png' : mime.includes('webp') ? 'webp' : 'jpg'
    const bytes = await file.arrayBuffer()
    const r2Key = `posto-bandeira/${parceiroId}.${ext}`

    if (!r2) return c.json({ ok: false, erro: 'Storage não configurado' }, 500)

    // Deletar arquivos antigos de outras extensões para evitar servir versão velha
    for (const oldExt of ['jpg', 'png', 'webp']) {
      if (oldExt !== ext) {
        try { await r2.delete(`posto-bandeira/${parceiroId}.${oldExt}`) } catch {}
      }
    }
    await r2.put(r2Key, bytes, { httpMetadata: { contentType: mime } })

    // Timestamp do upload — usado como ETag no GET para forçar re-fetch após troca
    const uploadTs = Date.now()
    const fotoUrl = `/api/posto/foto-bandeira/${parceiroId}`
    // Versão com timestamp para bust de cache imediato no frontend
    const fotoUrlComTs = `${fotoUrl}?v=${uploadTs}`

    // Atualizar parceiro no KV/R2 com fotoBandeira e timestamp do upload
    const parceiro = await kvGetParceiro(kv, parceiroId, r2) as Record<string, unknown> | null
    if (parceiro) {
      parceiro.fotoBandeira = fotoUrl
      parceiro.fotoTs = uploadTs          // timestamp para ETag dinâmico
      await kvSetParceiro(kv, parceiroId, parceiro, undefined, r2)
    } else {
      const minimo = { id: parceiroId, fotoBandeira: fotoUrl, fotoTs: uploadTs, criadoEm: new Date().toISOString() }
      await kvSetParceiro(kv, parceiroId, minimo, undefined, r2)
    }

    // Atualizar cache posto:band no KV (fonte do fotoUrl para usuários)
    try {
      const bandKey = `posto:band:${parceiroId}`
      const bandRaw = await kv?.get(bandKey)
      if (bandRaw) {
        const band = JSON.parse(bandRaw) as Record<string, unknown>
        band.fotoUrl = fotoUrl
        band.fotoTs  = uploadTs
        await kv?.put(bandKey, JSON.stringify(band), { expirationTtl: 30 * 24 * 3600 })
      } else {
        await kv?.put(bandKey, JSON.stringify({ postoId: parceiroId, fotoUrl, fotoTs: uploadTs, ts: uploadTs }), { expirationTtl: 30 * 24 * 3600 })
      }
    } catch {}

    return c.json({ ok: true, fotoUrl, fotoUrlComTs, uploadTs })
  } catch(e) {
    console.error('[foto-bandeira] erro:', e)
    return c.json({ ok: false, erro: 'Erro interno: ' + String(e) }, 500)
  }
})

// ── POST /api/admin/posto-band/logo — upload de logo para qualquer posto:band:* do KV ──────────
// Usado para postos Google/OSM que não têm parceiroId cadastrado
app.post('/api/admin/posto-band/logo', async (c) => {
  try {
    const kv = getKV(c.env) ?? undefined
    const r2 = (c.env as Record<string, unknown>)?.ROTAPOSTO_R2 as R2Bucket | undefined
    const ADMIN_PASS = (c.env as Record<string,unknown>)?.ADMIN_PASS as string || 'rotaposto@admin2026'
    const adminKey = c.req.query('key') || ''
    if (adminKey !== ADMIN_PASS) return c.json({ ok: false, erro: 'Não autorizado' }, 401)
    if (!kv) return c.json({ ok: false, erro: 'KV indisponível' }, 500)
    if (!r2) return c.json({ ok: false, erro: 'Storage não configurado' }, 500)

    const formData = await c.req.formData()
    const postoId = (formData.get('postoId') as string || '').trim()
    if (!postoId) return c.json({ ok: false, erro: 'postoId obrigatório' }, 400)

    const file = formData.get('logo') as File | null
    if (!file) return c.json({ ok: false, erro: 'Arquivo não encontrado' }, 400)
    if (file.size > 3 * 1024 * 1024) return c.json({ ok: false, erro: 'Imagem muito grande (máx. 3 MB)' }, 400)

    const mime = file.type || 'image/jpeg'
    const ext  = mime.includes('png') ? 'png' : mime.includes('webp') ? 'webp' : 'jpg'
    const bytes = await file.arrayBuffer()

    // Salvar no R2: usa mesmo path do posto-bandeira para reaproveitar endpoint GET
    // Sanitiza o postoId para usar como chave de arquivo (remove chars problemáticos)
    const safeId = postoId.replace(/[^a-zA-Z0-9_\-]/g, '_')
    const r2LogoKey = `posto-bandeira/${safeId}.${ext}`

    // Limpar extensões antigas
    for (const oldExt of ['jpg', 'png', 'webp']) {
      if (oldExt !== ext) {
        try { await r2.delete(`posto-bandeira/${safeId}.${oldExt}`) } catch {}
      }
    }
    await r2.put(r2LogoKey, bytes, { httpMetadata: { contentType: mime } })

    const uploadTs = Date.now()
    const logoUrl = `/api/admin/posto-band/logo-img/${safeId}`

    // Atualizar o KV posto:band:{postoId} com fotoUrl = logoUrl (logo tem prioridade)
    const bandKey = `posto:band:${postoId}`
    const bandRaw = await kv.get(bandKey)
    const band: Record<string, unknown> = bandRaw ? JSON.parse(bandRaw) : { postoId }
    band.fotoUrl  = logoUrl
    band.logoUrl  = logoUrl
    band.fotoTs   = uploadTs
    band.logoUploadAdmin = true
    await kv.put(bandKey, JSON.stringify(band), { expirationTtl: 365 * 24 * 3600 })

    // Invalidar cache em memória para que a logo apareça imediatamente
    cache.clear()

    return c.json({ ok: true, logoUrl, uploadTs, postoId, safeId })
  } catch(e) {
    console.error('[posto-band/logo] erro:', e)
    return c.json({ ok: false, erro: 'Erro interno: ' + String(e) }, 500)
  }
})

// ── GET /api/admin/posto-band/logo-img/:safeId — serve logo de posto do mapa ─────────────────
app.get('/api/admin/posto-band/logo-img/:safeId', async (c) => {
  try {
    const r2 = (c.env as Record<string, unknown>)?.ROTAPOSTO_R2 as R2Bucket | undefined
    if (!r2) return c.notFound()
    const safeId = c.req.param('safeId')
    for (const ext of ['png', 'jpg', 'webp']) {
      const obj = await r2.get(`posto-bandeira/${safeId}.${ext}`)
      if (obj) {
        return new Response(obj.body, {
          headers: {
            'Content-Type': obj.httpMetadata?.contentType || `image/${ext}`,
            'Cache-Control': 'no-cache',
          }
        })
      }
    }
    return c.notFound()
  } catch { return c.notFound() }
})

// ── GET /api/parceiros/anp-consultar — scraping CDP ANP via CNPJ ─────────────
// Consulta dados públicos do posto na ANP (Agência Nacional do Petróleo)
// Retorna: nome_fantasia, bandeira, endereço, autorização, equipamentos
app.get('/api/parceiros/anp-consultar', async (c) => {
  try {
    const token   = c.req.header('Authorization')?.replace('Bearer ', '') || ''
    const cnpjRaw = c.req.query('cnpj') || ''
    const cnpj    = cnpjRaw.replace(/[^0-9]/g, '').slice(0, 14)
    if (cnpj.length < 14) return c.json({ ok: false, erro: 'CNPJ inválido. Informe 14 dígitos.' }, 400)

    // Autenticar parceiro
    const kv = getKV(c.env) ?? undefined
    const r2 = (c.env as Record<string, unknown>)?.ROTAPOSTO_R2 as R2Bucket | undefined
    if (!token) return c.json({ ok: false, erro: 'Token obrigatório' }, 401)
    const sess = await kvGetParceiro(kv, `sess_${token}`, r2) as Record<string, unknown> | null
    if (!sess || (sess.exp as number) < Date.now()) return c.json({ ok: false, erro: 'Sessão expirada' }, 401)

    // ── PASSO 1: Iniciar sessão APEX no CDP ANP ─────────────────────────────
    const BASE = 'https://cdp.anp.gov.br'
    const UA   = 'Mozilla/5.0 (compatible; RotaPosto-ANP-Integrator/1.0)'

    // Buscar página principal para obter p_instance e cookies
    const r1 = await fetch(`${BASE}/ords/r/cdp_apex/consulta-dados-publicos-cdp/principal`, {
      headers: { 'User-Agent': UA, 'Accept': 'text/html,application/xhtml+xml' },
      redirect: 'follow'
    })
    if (!r1.ok) return c.json({ ok: false, erro: 'CDP ANP indisponível no momento.' }, 502)

    const html1    = await r1.text()
    const cookies1 = r1.headers.get('set-cookie') || ''

    // Extrair p_instance (identificador de sessão APEX)
    const instMatch = html1.match(/p_instance["\s:=]+["']?([A-Z0-9]+)["']?/i)
                   || html1.match(/wwv_flow\.g_instance\s*=\s*["']([^"']+)["']/i)
                   || html1.match(/id="pInstance"\s+value="([^"]+)"/)
    const pInstance = instMatch ? instMatch[1] : ''

    // Extrair p_flow_id (ID do app APEX)
    const flowMatch = html1.match(/p_flow_id["\s:=]+["']?(\d+)["']?/i)
                   || html1.match(/wwv_flow\.g_flow_id\s*=\s*(\d+)/i)
                   || html1.match(/"app-id":(\d+)/)
    const pFlowId = flowMatch ? flowMatch[1] : '120'

    // ── PASSO 2: Tentar busca via endpoint de pesquisa APEX ─────────────────
    // O CDP ANP usa APEX AJAX para filtrar resultados por CNPJ
    const cookieHeader = cookies1.split(',').map((c: string) => c.split(';')[0].trim()).join('; ')

    const searchPayload = new URLSearchParams({
      p_flow_id:       pFlowId,
      p_flow_step_id:  '1',
      p_instance:      pInstance,
      p_request:       'NATIVE=SEARCH',
      p_widget_name:   'classic_report',
      p_widget_action: 'PAGINATE',
      x01:             cnpj,  // CNPJ como filtro
      p_json:          JSON.stringify({ regionId: 'R_LISTA_POSTOS', cnpj })
    })

    // Tentar busca via wwv_flow.show (endpoint padrão APEX para relatórios)
    const r2resp = await fetch(`${BASE}/ords/wwv_flow.show`, {
      method: 'POST',
      headers: {
        'User-Agent':    UA,
        'Content-Type':  'application/x-www-form-urlencoded',
        'Referer':       `${BASE}/ords/r/cdp_apex/consulta-dados-publicos-cdp/principal`,
        'Cookie':        cookieHeader,
        'X-Requested-With': 'XMLHttpRequest'
      },
      body: searchPayload.toString()
    })

    // ── PASSO 3: Parsear HTML retornado buscando dados do posto ──────────────
    let htmlResult = ''
    if (r2resp.ok) {
      htmlResult = await r2resp.text()
    } else {
      // Fallback: buscar diretamente na página principal com CNPJ na URL
      const r3 = await fetch(`${BASE}/ords/r/cdp_apex/consulta-dados-publicos-cdp/principal?cnpj=${cnpj}`, {
        headers: { 'User-Agent': UA, 'Cookie': cookieHeader }
      })
      if (r3.ok) htmlResult = await r3.text()
    }

    // ── PASSO 4: Extrair dados estruturados do HTML ──────────────────────────
    // Função auxiliar para extrair conteúdo entre tags ou após labels
    function extrairCampo(html: string, label: string): string {
      // Padrão 1: <td>LABEL</td><td>VALOR</td>
      const re1 = new RegExp(`<td[^>]*>[^<]*${label}[^<]*<\\/td>\\s*<td[^>]*>([^<]+)<\\/td>`, 'i')
      const m1  = html.match(re1)
      if (m1) return m1[1].trim()
      // Padrão 2: <label>LABEL</label>...<span>VALOR</span>
      const re2 = new RegExp(`${label}[^<]*<\\/[^>]+>[^<]*<[^>]+>([^<]{2,80})<\\/`, 'i')
      const m2  = html.match(re2)
      if (m2) return m2[1].trim()
      // Padrão 3: data-label="LABEL" data-value="VALOR"
      const re3 = new RegExp(`data-label="${label}"[^>]*data-value="([^"]+)"`, 'i')
      const m3  = html.match(re3)
      if (m3) return m3[1].trim()
      return ''
    }

    // Mapeamento bandeira ANP → nome normalizado RotaPosto
    function normalizarBandeira(raw: string): string {
      const b = raw.toUpperCase().trim()
      if (b.includes('PETROBRAS') || b.includes('BR DISTRIBUIDORA') || b.includes('VIBRA')) return 'Petrobras BR'
      if (b.includes('SHELL') || b.includes('RAIZEN') || b.includes('RAÍZEN'))              return 'Shell'
      if (b.includes('IPIRANGA'))                                                            return 'Ipiranga'
      if (b.includes('ALE') || b.includes('ALÉ'))                                           return 'Ale'
      if (b.includes('BANDEIRA BRANCA') || b.includes('SEM BANDEIRA') || b.includes('BRANCA')) return 'Sem bandeira'
      if (b.includes('COSAN') || b.includes('LUBRAX'))                                      return 'Outra'
      if (b.length > 1) return 'Outra'
      return 'Sem bandeira'
    }

    // Verificar se encontrou dados na página
    const temDados = htmlResult.length > 500 &&
      (htmlResult.includes(cnpj) ||
       htmlResult.toLowerCase().includes('nome fantasia') ||
       htmlResult.toLowerCase().includes('razão social') ||
       htmlResult.toLowerCase().includes('razao social') ||
       htmlResult.toLowerCase().includes('distribuidor') ||
       htmlResult.toLowerCase().includes('bandeira'))

    if (!temDados) {
      // Retornar estrutura vazia mas indicando CNPJ não encontrado na ANP
      return c.json({
        ok: false,
        erro: 'CNPJ não encontrado na base de dados ANP CDP. Verifique se o posto está regularizado e tente novamente.',
        cnpj,
        encontrado: false
      })
    }

    // Extrair campos principais
    const nomeFant   = extrairCampo(htmlResult, 'Nome Fantasia') || extrairCampo(htmlResult, 'NOME FANTASIA')
    const razaoSoc   = extrairCampo(htmlResult, 'Raz.o Social')  || extrairCampo(htmlResult, 'RAZAO SOCIAL') || extrairCampo(htmlResult, 'RAZÃO SOCIAL')
    const bandeiraR  = extrairCampo(htmlResult, 'Bandeira')      || extrairCampo(htmlResult, 'BANDEIRA')     || extrairCampo(htmlResult, 'Distribuidora')
    const autorizaca = extrairCampo(htmlResult, 'Autoriza')      || extrairCampo(htmlResult, 'N. Autoriza')
    const logradouro = extrairCampo(htmlResult, 'Logradouro')    || extrairCampo(htmlResult, 'Endere.o')
    const numero_end = extrairCampo(htmlResult, 'N.mero')        || extrairCampo(htmlResult, 'Numero')
    const bairro_end = extrairCampo(htmlResult, 'Bairro')
    const municipio  = extrairCampo(htmlResult, 'Munic.pio')     || extrairCampo(htmlResult, 'Cidade')
    const uf_end     = extrairCampo(htmlResult, '>UF<')          || extrairCampo(htmlResult, 'Estado')
    const cep_end    = extrairCampo(htmlResult, 'CEP')

    // Extrair equipamentos (tanques + bicos) se presentes
    const equipamentos: Array<{produto: string, tancagem: string, bicos: string}> = []
    const eqRegex = /<tr[^>]*>[\s\S]*?<td[^>]*>([\w\s]+combustível[\w\s]*|gasolina|etanol|diesel|gnv|arla|lubrificante)[^<]*<\/td>[\s\S]*?<td[^>]*>(\d+[.,]?\d*)<\/td>[\s\S]*?<td[^>]*>(\d+)<\/td>/gi
    let eqMatch: RegExpExecArray | null
    while ((eqMatch = eqRegex.exec(htmlResult)) !== null) {
      equipamentos.push({ produto: eqMatch[1].trim(), tancagem: eqMatch[2], bicos: eqMatch[3] })
    }

    const dados = {
      cnpj,
      nome_fantasia:   nomeFant  || razaoSoc || '',
      razao_social:    razaoSoc  || '',
      bandeira_raw:    bandeiraR || '',
      bandeira:        normalizarBandeira(bandeiraR || ''),
      autorizacao:     autorizaca || '',
      endereco: {
        logradouro: logradouro || '',
        numero:     numero_end || '',
        bairro:     bairro_end || '',
        municipio:  municipio  || '',
        uf:         uf_end     || '',
        cep:        (cep_end || '').replace(/[^0-9]/g, '')
      },
      equipamentos,
      encontrado:  true,
      fonte:       'ANP CDP - Dados Públicos',
      consultadoEm: new Date().toISOString()
    }

    return c.json({ ok: true, dados })
  } catch(e) {
    const msg = e instanceof Error ? e.message : 'Erro desconhecido'
    return c.json({ ok: false, erro: `Erro ao consultar ANP: ${msg}` }, 500)
  }
})

// ── POST /api/parceiros/anp-aplicar — aplica dados ANP ao perfil do parceiro ──
app.post('/api/parceiros/anp-aplicar', async (c) => {
  try {
    const kv    = getKV(c.env) ?? undefined
    const r2    = (c.env as Record<string, unknown>)?.ROTAPOSTO_R2 as R2Bucket | undefined
    const token = c.req.header('Authorization')?.replace('Bearer ', '') || ''
    const body  = await c.req.json() as Record<string, unknown>

    // Autenticar
    if (!token) return c.json({ ok: false, erro: 'Token obrigatório' }, 401)
    const sess = await kvGetParceiro(kv, `sess_${token}`, r2) as Record<string, unknown> | null
    if (!sess || (sess.exp as number) < Date.now()) return c.json({ ok: false, erro: 'Sessão expirada' }, 401)
    const parceiroId = String(sess.parceiroId)

    const parceiro = await kvGetParceiro(kv, parceiroId, r2) as Record<string, unknown> | null
    if (!parceiro) return c.json({ ok: false, erro: 'Posto não encontrado' }, 404)

    // Campos a aplicar (enviados pelo frontend após confirmação do dono)
    const campos = body.campos as Record<string, unknown> || {}
    const updated: Record<string, unknown> = { ...parceiro }

    if (campos.nome_fantasia)     updated.nomePosto  = campos.nome_fantasia
    if (campos.bandeira)          updated.bandeira   = campos.bandeira
    if (campos.cnpj)              updated.cnpj       = String(campos.cnpj).replace(/[^0-9]/g, '')
    if (campos.autorizacao)       updated.anpAutorizacao = campos.autorizacao
    if (campos.equipamentos)      updated.anpEquipamentos = campos.equipamentos
    if (campos.endereco) {
      const end = campos.endereco as Record<string, string>
      updated.endereco = {
        cep:     end.cep     || (parceiro.endereco as Record<string,string>)?.cep    || '',
        rua:     end.logradouro || (parceiro.endereco as Record<string,string>)?.rua || '',
        numero:  end.numero  || (parceiro.endereco as Record<string,string>)?.numero || '',
        bairro:  end.bairro  || (parceiro.endereco as Record<string,string>)?.bairro || '',
        cidade:  end.municipio || (parceiro.endereco as Record<string,string>)?.cidade || '',
        estado:  end.uf      || (parceiro.endereco as Record<string,string>)?.estado  || ''
      }
      // Geocodificar endereço ANP para obter lat/lng
      if (!body.lat) {
        try {
          const endStr = [end.logradouro, end.numero, end.bairro, end.municipio, end.uf].filter(Boolean).join(', ')
          const gKey   = (c.env as any)?.GOOGLE_PLACES_KEY as string || ''
          if (gKey && endStr) {
            const geoResp = await fetch(`https://maps.googleapis.com/maps/api/geocode/json?address=${encodeURIComponent(endStr + ', Brasil')}&key=${gKey}`)
            if (geoResp.ok) {
              const geoData = await geoResp.json() as any
              const loc = geoData?.results?.[0]?.geometry?.location
              if (loc) { updated.lat = loc.lat; updated.lng = loc.lng }
            }
          }
        } catch {}
      }
    }
    if (body.lat) updated.lat = body.lat
    if (body.lng) updated.lng = body.lng

    updated.anpEnriquecidoEm = new Date().toISOString()
    updated.atualizadoEm     = new Date().toISOString()

    await kvSetParceiro(kv, parceiroId, updated, undefined, r2)

    // Atualizar posto no índice do mapa se tiver lat/lng
    if (updated.lat && updated.lng) {
      try {
        const postoKey  = `posto:${parceiroId}`
        const postoData = await kv?.get(postoKey)
        if (postoData) {
          const posto = JSON.parse(postoData) as Record<string, unknown>
          posto.lat      = updated.lat
          posto.lng      = updated.lng
          posto.nome     = updated.nomePosto     || posto.nome
          posto.bandeira = updated.bandeira      || posto.bandeira
          posto.endereco = updated.endereco      || posto.endereco
          await kv?.put(postoKey, JSON.stringify(posto))
        }
      } catch {}
    }

    return c.json({
      ok: true,
      mensagem: 'Dados ANP aplicados com sucesso ao perfil!',
      campos_aplicados: Object.keys(campos),
      lat: updated.lat,
      lng: updated.lng
    })
  } catch(e) {
    return c.json({ ok: false, erro: 'Erro ao aplicar dados ANP' }, 500)
  }
})

// ── POST /api/parceiros/perfil ────────────────────────────────────────────────
app.post('/api/parceiros/perfil', async (c) => {
  try {
    const kv = getKV(c.env) ?? undefined
    const r2 = (c.env as Record<string, unknown>)?.ROTAPOSTO_R2 as R2Bucket | undefined
    const token = c.req.header('Authorization')?.replace('Bearer ', '') || ''
    const body = await c.req.json() as Record<string, unknown>
    const postoId = String(body.postoId || '')

    // Auth via token ou postoId direto
    let parceiroId = postoId
    if (token) {
      const sess = await kvGetParceiro(kv, `sess_${token}`, r2) as Record<string, unknown> | null
      if (!sess || (sess.exp as number) < Date.now()) return c.json({ ok: false, erro: 'Sessão expirada' }, 401)
      parceiroId = String(sess.parceiroId)
    }
    if (!parceiroId) return c.json({ ok: false, erro: 'postoId obrigatório' }, 400)

    const parceiro = await kvGetParceiro(kv, parceiroId, r2) as Record<string, unknown> | null
    if (!parceiro) return c.json({ ok: false, erro: 'Posto não encontrado' }, 404)

    // Atualizar campos
    const updated: Record<string, unknown> = {
      ...parceiro,
      nomePosto: body.nome || parceiro.nomePosto,
      bandeira: body.bandeira || parceiro.bandeira,
      tel: body.tel ?? parceiro.tel,
      horario: body.horario ?? parceiro.horario,
      email: body.email ?? parceiro.email,
      cnpj: body.cnpj ?? parceiro.cnpj,
      endereco: body.endereco ?? parceiro.endereco,
      servicos: body.servicos ?? parceiro.servicos,
      atualizadoEm: new Date().toISOString()
    }
    if (body.lat) updated.lat = body.lat
    if (body.lng) updated.lng = body.lng

    await kvSetParceiro(kv, parceiroId, updated, undefined, r2)

    // Se tiver lat/lng, atualizar também no R2/KV de postos para o mapa do app
    if (body.lat && body.lng) {
      try {
        const postoKey = `posto:${parceiroId}`
        const postoData = await kv?.get(postoKey)
        if (postoData) {
          const posto = JSON.parse(postoData) as Record<string, unknown>
          posto.lat = body.lat; posto.lng = body.lng
          posto.nome = body.nome || posto.nome
          posto.bandeira = body.bandeira || posto.bandeira
          posto.tel = body.tel || posto.tel
          posto.horario = body.horario || posto.horario
          posto.endereco = body.endereco || posto.endereco
          await kv?.put(postoKey, JSON.stringify(posto))
        }
      } catch {}
    }

    return c.json({ ok: true, mensagem: 'Perfil atualizado com sucesso!' })
  } catch(e) {
    return c.json({ ok: false, erro: 'Erro interno' }, 500)
  }
})

// ── POST /api/parceiros/cupons/validar ────────────────────────────────────────
app.post('/api/parceiros/cupons/validar', async (c) => {
  try {
    const kv = getKV(c.env) ?? undefined
  const r2 = (c.env as Record<string, unknown>)?.ROTAPOSTO_R2 as R2Bucket | undefined
    const body = await c.req.json() as Record<string, string>
    const { codigo, postoId } = body

    if (!codigo || codigo.length < 6) {
      return c.json({ valido: false, mensagem: 'Código inválido. Digite os 6 dígitos.' }, 400)
    }

    const codigoLimpo = codigo.replace(/[^0-9]/g, '').padStart(6, '0').slice(-6)
    const cupom = await kvGetCupom(kv, codigoLimpo, r2) as Record<string, unknown> | null

    if (!cupom) {
      return c.json({ valido: false, mensagem: 'Cupom não encontrado ou expirado.' }, 404)
    }

    // Verificar status
    if (cupom.status === 'UTILIZADO') {
      return c.json({
        valido: false,
        mensagem: '❌ Este cupom já foi utilizado!',
        dataUso: cupom.dataUso
      }, 400)
    }

    if (cupom.status === 'EXPIRADO') {
      return c.json({ valido: false, mensagem: '⏰ Cupom expirado! O cliente deve gerar um novo.' }, 400)
    }

    // Verificar tempo (5 minutos = 300 segundos)
    const agora = Date.now()
    const criadoEm = Number(cupom.criadoEm) || 0
    const deltaSegundos = (agora - criadoEm) / 1000
    if (deltaSegundos > 300) {
      if (kv) await kvSetCupom(kv, codigoLimpo, { ...cupom, status: 'EXPIRADO' }, 3600, r2)
      return c.json({ valido: false, mensagem: '⏰ Cupom expirado (5 minutos)! Peça ao cliente gerar outro.' }, 400)
    }

    // Buscar preços do posto para calcular desconto
    const precos = postoId ? await kvGetPrecos(kv, postoId, r2) as Record<string, unknown> | null : null
    const combustivel = String(cupom.combustivel || 'Gasolina Comum')
    let precoBomba = 5.90
    let desconto = 0.10
    let precoFinal = precoBomba - desconto

    if (precos) {
      const p = precos as Record<string, Record<string, number>>
      const dadosComb = p[combustivel]
      if (dadosComb) {
        precoBomba = dadosComb.precoBomba || precoBomba
        desconto = dadosComb.desconto || desconto
        precoFinal = precoBomba - desconto
      }
    }

    // Para cupons tipo POSTO: decrementar usos; tipo USUARIO: marcar UTILIZADO
    const tipo = String((cupom as Record<string,unknown>).tipo || 'USUARIO')
    let cupomAtualizado: Record<string,unknown>
    if (tipo === 'POSTO') {
      const usosRestantes = Math.max(0, Number((cupom as Record<string,unknown>).usosRestantes || 1) - 1)
      cupomAtualizado = { ...cupom, usosRestantes, dataUltUso: new Date().toISOString(), postoId: postoId || '',
        status: usosRestantes <= 0 ? 'ESGOTADO' : 'ATIVO' }
      const ttlRestante = Math.max(60, Math.floor((Number((cupom as Record<string,unknown>).expiraEm || 0) - Date.now()) / 1000))
      await kvSetCupom(kv, codigoLimpo, cupomAtualizado, ttlRestante, r2)
      // Atualizar também na lista do posto
      if (postoId && kv) {
        const listaKey = `posto_cupons:${postoId}`
        try {
          const listaRaw = await kv.get(listaKey)
          if (listaRaw) {
            const lista = JSON.parse(listaRaw) as Record<string,unknown>[]
            const idx = lista.findIndex(x => x.codigo === codigoLimpo)
            if (idx >= 0) lista[idx] = cupomAtualizado
            await kv.put(listaKey, JSON.stringify(lista), { expirationTtl: 86400 * 7 })
          }
        } catch {}
      }
      // Usar desconto do próprio cupom criado pelo posto
      desconto = Number((cupom as Record<string,unknown>).desconto || desconto)
      precoFinal = precoBomba - desconto
    } else {
      cupomAtualizado = { ...cupom, status: 'UTILIZADO', dataUso: new Date().toISOString(), postoId: postoId || '' }
      await kvSetCupom(kv, codigoLimpo, cupomAtualizado, 86400, r2)
    }

    // Registrar no histórico do posto
    if (postoId && kv) {
      const histKey = `historico:${postoId}`
      let hist = []
      try { hist = JSON.parse(await kv.get(histKey) || '[]') } catch {}
      hist.push({
        codigo: codigoLimpo,
        usuario: cupom.nomeUsuario || 'Assinante Premium',
        combustivel,
        precoBomba,
        desconto,
        precoFinal,
        dataUso: cupomAtualizado.dataUso,
        status: 'UTILIZADO'
      })
      await kv.put(histKey, JSON.stringify(hist.slice(-200)), { expirationTtl: 2592000 }) // 30 dias
    }

    // Atualizar métricas do posto
    if (postoId && kv) {
      const mesAtual = new Date().toISOString().slice(0, 7)
      const metKey = `metricas:${postoId}:${mesAtual}`
      let met = { cliques: 0, cupons: 0, impressoes: 0, conversao: 0 }
      try { met = { ...met, ...JSON.parse(await kv.get(metKey) || '{}') } } catch {}
      met.cupons++
      await kv.put(metKey, JSON.stringify(met), { expirationTtl: 2678400 }) // 31 dias
    }

    return c.json({
      valido: true,
      mensagem: '✅ CUPOM CONFIRMADO!',
      usuario: cupom.nomeUsuario || 'Assinante Premium',
      uid: cupom.uid || '',
      combustivel,
      precoBomba: precoBomba.toFixed(2),
      desconto: desconto.toFixed(2),
      precoFinal: precoFinal.toFixed(2),
      instrucao: `Aplique R$ ${precoFinal.toFixed(2)}/litro na bomba de ${combustivel}`
    })
  } catch (e) {
    console.error('[parceiros/cupons/validar]', e)
    return c.json({ valido: false, mensagem: 'Erro interno ao validar cupom' }, 500)
  }
})

// ── GET /api/parceiros/cupons ─────────────────────────────────────────────────
app.get('/api/parceiros/cupons', async (c) => {
  try {
    const kv = getKV(c.env) ?? undefined
  const r2 = (c.env as Record<string, unknown>)?.ROTAPOSTO_R2 as R2Bucket | undefined
    const postoId = c.req.query('postoId') || ''
    const status = c.req.query('status') || '' // GERADO | UTILIZADO | EXPIRADO
    const token = c.req.header('Authorization')?.replace('Bearer ', '') || c.req.query('token') || ''

    let parceiroId = postoId
    if (!parceiroId && token) {
      const sess = await kvGetParceiro(kv, `sess_${token}`, r2) as Record<string, unknown> | null
      if (sess && (sess.exp as number) > Date.now()) parceiroId = String(sess.parceiroId)
    }
    if (!parceiroId) return c.json({ ok: false, erro: 'postoId obrigatório' }, 400)

    const histKey = `historico:${parceiroId}`
    let hist: Record<string, unknown>[] = []
    try { hist = JSON.parse(await kv?.get(histKey) || '[]') } catch {}

    if (status) hist = hist.filter(h => h.status === status)

    return c.json({
      ok: true,
      total: hist.length,
      cupons: hist.slice(-100).reverse(),
      resumo: {
        total: hist.length,
        utilizados: hist.filter(h => h.status === 'UTILIZADO').length,
        expirados: hist.filter(h => h.status === 'EXPIRADO').length,
      }
    })
  } catch (e) {
    console.error('[parceiros/cupons]', e)
    return c.json({ ok: false, erro: 'Erro interno' }, 500)
  }
})

// ── POST /api/parceiros/precos ────────────────────────────────────────────────
app.post('/api/parceiros/precos', async (c) => {
  try {
    const kv = getKV(c.env) ?? undefined
  const r2 = (c.env as Record<string, unknown>)?.ROTAPOSTO_R2 as R2Bucket | undefined
    const body = await c.req.json() as Record<string, unknown>
    const { postoId, token, precos } = body as { postoId: string; token: string; precos: Record<string, { precoBomba: number; desconto: number }> }

    // Autenticação
    let parceiroId = postoId
    if (!parceiroId && token) {
      const sess = await kvGetParceiro(kv, `sess_${token}`, r2) as Record<string, unknown> | null
      if (sess && (sess.exp as number) > Date.now()) parceiroId = String(sess.parceiroId)
    }
    if (!parceiroId) return c.json({ ok: false, erro: 'postoId obrigatório' }, 400)
    if (!precos || typeof precos !== 'object') return c.json({ ok: false, erro: 'precos obrigatório' }, 400)

    // Calcular preço final de cada combustível
    const precosCalculados: Record<string, unknown> = {}
    for (const [comb, dados] of Object.entries(precos)) {
      const bomba = Number(dados.precoBomba) || 0
      const desc = Number(dados.desconto) || 0
      precosCalculados[comb] = {
        precoBomba: bomba,
        desconto: desc,
        precoFinal: +(bomba - desc).toFixed(3),
        atualizadoEm: new Date().toISOString()
      }
    }

    if (kv) await kv.put(`precos:${parceiroId}`, JSON.stringify(precosCalculados), { expirationTtl: 172800 }) // 2 dias

    // Notificar usuários que monitoram este posto (simulado — em produção usaria FCM)

    return c.json({
      ok: true,
      mensagem: 'Preços atualizados com sucesso!',
      precos: precosCalculados
    })
  } catch (e) {
    console.error('[parceiros/precos]', e)
    return c.json({ ok: false, erro: 'Erro interno' }, 500)
  }
})

